// Bootstrap, run-status, format utils, and plotly utils are in separate files.
// See: bootstrap.js, run-status.js, format-utils.js, plotly-utils.js, reload.js

// URL hash routing: lets a link jump straight to a specific generator/noise/
// strategy/repeat + scan-view-mode + Bayesian sub-tab, e.g.
// #generator=NVCenter-lorentzian&noise=Gauss(0.0067)&strategy=Bayesian-SMC&repeat=0&view=speed&bayesTab=bayes-convergence-section
// Read on load and on hashchange (manual edits, shared links); written via
// replaceState (not pushState) as the user navigates, so the address bar
// always reflects the current view without spamming browser history.
function getHashParams() {
    try { return new URLSearchParams((location.hash || '').replace(/^#/, '')); }
    catch (e) { return new URLSearchParams(); }
}

function writeHashState(state) {
    const params = new URLSearchParams();
    ['generator', 'noise', 'strategy', 'repeat', 'view', 'bayesTab'].forEach((key) => {
        if (state[key]) params.set(key, state[key]);
    });
    const next = params.toString();
    const url = location.pathname + location.search + (next ? '#' + next : '');
    history.replaceState(null, '', url);
}

function main() {
    initRunStatusBanner();
    initHelpToggles();

    let plots = [];
    let currentPlot = null;
    // Set from the URL hash's bayesTab param; consumed once by updateBayesTabs()
    // the first time the Bayesian tab bar is built (see there for why).
    let pendingHashBayesTab = null;
    // Splitting (zeeman_shift) convergence is the primary milestone; 'full'/'all_converged'
    // are verification only. Default to primary_converged (falls back to 'full' when a
    // loaded run has no primary milestone — see updateStoppingCriteriaVisibility).
    let currentStoppingCriteria = 'primary_converged'; // 'full' | 'primary_converged' | 'all_converged'
    try {
        plots = window.MANIFEST;
        if (!Array.isArray(plots)) {
            throw new Error('Invalid manifest format');
        }
    } catch (error) {
        console.error('Error reading plots manifest from window.MANIFEST:', error);
        // Show an error message to the user
        const errorDiv = document.createElement('div');
        errorDiv.setAttribute('role', 'alert');
        errorDiv.style.padding = '20px';
        errorDiv.style.margin = '20px';
        errorDiv.style.border = '1px solid #f5c6cb';
        errorDiv.style.backgroundColor = '#f8d7da';
        errorDiv.style.color = '#721c24';
        errorDiv.style.borderRadius = '4px';
        errorDiv.innerHTML = '<h3>Error: Invalid data format</h3><p>Could not parse the plot data. The data might be corrupted or in an unexpected format.</p>';
        document.body.appendChild(errorDiv);
        return;
    }

    const settings = window.SETTINGS || {};
    const outDirDisplay = document.getElementById('out-dir-display');
    if (outDirDisplay && settings.out_dir) {
        outDirDisplay.textContent = `(${settings.out_dir})`;
    }

    const locatorResultsLink = document.querySelector('a[download][href="locator_results.parquet"]');
    if (locatorResultsLink) {
        locatorResultsLink.href = resolveAssetPath('locator_results.parquet');
        // Older run directories (or ones not yet re-rendered since the Parquet
        // migration) only have locator_results.csv on disk. Probe for the Parquet
        // file and fall back to the CSV so the link isn't a dead 404.
        fetch(locatorResultsLink.href, { method: 'HEAD', cache: 'no-store' })
            .then((resp) => {
                if (!resp.ok) {
                    locatorResultsLink.href = resolveAssetPath('locator_results.csv');
                    locatorResultsLink.textContent = 'Download locator_results.csv';
                }
            })
            .catch(() => {});
    }

    plots.forEach((p) => {
        if (p && typeof p.path === 'string' && p.path.length > 0) {
            p.path = resolveAssetPath(p.path);
        }
    });

    const scanPlots = plots.filter((p) => p.type === 'scan');
    // Real (MATLAB) runs only: per-drive-frequency-point mean/std/min/max of every recorded
    // shot, overlaid as candle-like whiskers on top of the sampled-measurements
    // scan plot (see _getDriveFreqStatsOverlayTraces) rather than shown as its own panel.
    const matlabDriveFreqStatsPlots = plots.filter((p) => p.type === 'matlab_drive_freq_stats');
    const bayesSection = document.getElementById('bayes-section-container');
    const bayesImage = document.getElementById('bayes-image');
    const bayesPlots = plots.filter((p) => p.type === 'bayesian');
    // New JSON-data types (generated by plots_data.py writers)
    const bayesPosteriorDataPlots = plots.filter((p) => p.type === 'bayesian_posterior_data');
    const bayesParamConvDataPlots = plots.filter((p) => p.type === 'bayesian_parameter_convergence_data');
    const bayesConvMetricsDataPlots = plots.filter((p) => p.type === 'bayesian_convergence_metrics_data');
    const bayesFisherDataPlots = plots.filter((p) => p.type === 'bayesian_fisher_data');
    // Legacy iframe types (kept for backward compatibility with cached runs)
    const bayesInteractivePlots = plots.filter((p) => p.type === 'bayesian_interactive');
    const bayesFisherPlots = plots.filter((p) => p.type === 'bayesian_fisher_information');
    const bayesFisherPairsPlots = plots.filter((p) => p.type === 'bayesian_fisher_crlb_pairs');
    const bayesEllipsePlots = plots.filter((p) => p.type === 'bayesian_covariance_ellipses_data');
    const bayesConvergencePlots = plots.filter((p) => p.type === 'bayesian_parameter_convergence');
    const bayesConvMetricsPlots = plots.filter((p) => p.type === 'bayesian_convergence_metrics');
    const bayesJitterPlots = plots.filter((p) => p.type === 'bayesian_jitter');

    const bayesInteractiveSection = document.getElementById('bayes-interactive-section');
    const bayesInteractiveIframe = document.getElementById('bayes-interactive-iframe');
    const bayesConvergenceSection = document.getElementById('bayes-convergence-section');
    const bayesConvergenceIframe = document.getElementById('bayes-convergence-iframe');
    const bayesConvMetricsIframe = document.getElementById('bayes-conv-metrics-iframe');
    const bayesFisherSection = document.getElementById('bayes-fisher-section');
    const bayesFisherIframe = document.getElementById('bayes-fisher-iframe');
    const bayesFisherPairsSection = document.getElementById('bayes-fisher-pairs-section');
    const bayesFisherPairsIframe = document.getElementById('bayes-fisher-pairs-iframe');
    const bayesCovarianceSection = document.getElementById('bayes-covariance-section');
    const bayesEllipseContainer = document.getElementById('bayes-ellipse-container');
    const bayesJitterContent = document.getElementById('bayes-jitter-content');
    const bayesStatsPlots = plots.filter((p) => p.type === 'bayesian_stats');
    const bayesStatsSection = document.getElementById('bayes-stats-section');
    const posteriorHistoryImage = document.getElementById('posterior-history-image');
    const convergenceStatsImage = document.getElementById('convergence-stats-image');
    const hasBayesArtifacts =
        bayesPlots.length > 0 ||
        bayesPosteriorDataPlots.length > 0 ||
        bayesInteractivePlots.length > 0 ||
        bayesParamConvDataPlots.length > 0 ||
        bayesConvMetricsDataPlots.length > 0 ||
        bayesFisherDataPlots.length > 0 ||
        bayesStatsPlots.length > 0 ||
        plots.some((p) => p.type === 'bayesian_parameter_convergence') ||
        plots.some((p) => p.type === 'bayesian_convergence_metrics') ||
        plots.some((p) => p.type === 'bayesian_fisher_bounds') ||
        plots.some((p) => p.type === 'bayesian_fisher_crlb_pairs') ||
        plots.some((p) => p.type === 'bayesian_jitter') ||
        plots.some((p) => p.type === 'bayesian_covariance_ellipses_data');
    // Global Timeline Controls Sync Controller
    const globalControls = document.getElementById('global-timeline-controls');
    const globalPlayBtn = document.getElementById('global-play-btn');
    const globalSlider = document.getElementById('global-range-slider');
    const noiseMetricsView = document.getElementById('noise-metrics-view');
    const globalLabel = document.getElementById('global-step-label');
    const globalSpeedSelect = document.getElementById('global-speed-select');

    let globalIsPlaying = false;
    let globalPlayInterval = null;
    let globalTotalFrames = 0;
    let globalStepValues = [];

    // Track registered iframes
    const activeIframes = new Set();
    // Adapter that lets the global play/scrub timeline also drive the scan
    // measurements plot (item: play button should redraw "scan with sampled
    // measurements" per step). Created lazily on first scan render; survives
    // activeIframes.clear() calls elsewhere by being re-added there.
    let scanTimelineAdapter = null;
    // The timeline is also re-synced programmatically whenever Bayesian plot data
    // loads (updateGlobalTimelineMetadata -> syncFrames(currentSliderValue), which
    // defaults to 0) — without this flag that would immediately clobber the scan
    // plot's "View at" convergence-cap default down to just its first measurement.
    // Set true only by genuine user interaction (dragging the slider or pressing
    // play) — from then on the scan plot follows the timeline like the Bayesian
    // plots already do.
    let scanTimelineUserDriven = false;

    function registerIframeForTimeline(iframe) {
        if (!iframe) return;

        function onIframeLoaded() {
            try {
                const win = iframe.contentWindow;
                if (win && win.showFrame && win.totalFrames !== undefined) {
                    activeIframes.add(iframe);
                    updateGlobalTimelineMetadata();
                } else {
                    let attempts = 0;
                    const poll = setInterval(() => {
                        attempts++;
                        if (win && win.showFrame && win.totalFrames !== undefined) {
                            activeIframes.add(iframe);
                            updateGlobalTimelineMetadata();
                            clearInterval(poll);
                        }
                        if (attempts > 30) clearInterval(poll);
                    }, 100);
                }
            } catch (e) {
                console.error("Timeline registration cross-origin error:", e);
            }
        }

        iframe.addEventListener('load', onIframeLoaded);
        onIframeLoaded();
    }

    function getStoppingFrameLimit() {
        if (!currentPlot || currentStoppingCriteria === 'full') return null;
        const m = currentPlot.metrics || {};
        if (currentStoppingCriteria === 'primary_converged' && m.primary_converged_step != null)
            return Math.max(0, m.primary_converged_step);
        if (currentStoppingCriteria === 'all_converged' && m.all_converged_step != null)
            return Math.max(0, m.all_converged_step);
        return null;
    }

    function applyStoppingFrameLimit() {
        if (globalTotalFrames === 0) return;
        const limit = getStoppingFrameLimit();
        const cap = limit != null ? Math.min(limit, globalTotalFrames - 1) : globalTotalFrames - 1;
        globalSlider.max = cap;
        const cur = parseInt(globalSlider.value, 10);
        if (cur > cap) {
            globalSlider.value = cap;
            syncFrames(cap);
        }
        updateGlobalLabel(parseInt(globalSlider.value, 10));
    }

    function updateGlobalTimelineMetadata() {
        let maxFrames = 0;
        let steps = [];
        for (const iframe of activeIframes) {
            try {
                const win = iframe.contentWindow;
                if (win && win.totalFrames > maxFrames) {
                    maxFrames = win.totalFrames;
                    if (win.stepValues && win.stepValues.length > 0) {
                        steps = win.stepValues;
                    }
                }
            } catch (e) { }
        }

        if (maxFrames > 0) {
            globalTotalFrames = maxFrames;
            globalStepValues = steps;
            globalSlider.max = maxFrames - 1;
            globalControls.style.display = 'flex';
            applyStoppingFrameLimit();
            syncFrames(parseInt(globalSlider.value, 10));
            renderTimelineMilestoneMarkers();
        } else {
            globalTotalFrames = 0;
            globalStepValues = [];
            globalControls.style.display = 'none';
            if (globalIsPlaying) {
                globalPause();
            }
            renderTimelineMilestoneMarkers();
        }
    }

    // Maps a real step value (as reported in a plot's metrics, e.g.
    // primary_converged_step) to the closest global timeline frame index —
    // globalStepValues may be a subsampled, non-contiguous list of real step
    // numbers for long runs (see _subsample_snapshots in plots.py), so the exact
    // value isn't always present.
    function _closestFrameIndexForStep(step) {
        if (!globalStepValues || !globalStepValues.length) return -1;
        let best = 0;
        let bestDiff = Math.abs(globalStepValues[0] - step);
        for (let i = 1; i < globalStepValues.length; i++) {
            const diff = Math.abs(globalStepValues[i] - step);
            if (diff < bestDiff) { best = i; bestDiff = diff; }
        }
        return best;
    }

    // Moves the timeline playhead to the frame closest to `realStep` and marks
    // the timeline as user-driven, exactly like dragging the slider there by hand.
    function jumpTimelineToStep(realStep) {
        if (globalTotalFrames === 0) return;
        // Milestone marker clicks call setStoppingCriteria() first, which (via
        // applyStoppingFrameLimit) shrinks globalSlider.max down to that milestone's
        // own step. A range input's thumb position is (value/max), so setting .value
        // right after — even to the correct frame — would render at 100% of that
        // now-shrunk track, i.e. visually at the far right, no matter which milestone
        // (primary_converged/all_converged/full) was clicked. The milestone dots
        // themselves are positioned against the fixed globalTotalFrames, so the thumb
        // has to render against that same fixed scale to land where the dot is.
        globalSlider.max = globalTotalFrames - 1;
        const idx = Math.max(0, Math.min(_closestFrameIndexForStep(realStep), globalTotalFrames - 1));
        globalSlider.value = idx;
        scanTimelineUserDriven = true;
        syncFrames(idx);
    }

    // Renders clickable "jump to" markers on the global timeline for the
    // convergence milestones that used to be a separate "View at" button row
    // (Full / Primary converged / Converged) in single-scan ("Run") mode —
    // clicking one both jumps the playhead there and sets currentStoppingCriteria,
    // same as the old buttons did.
    function renderTimelineMilestoneMarkers() {
        const container = document.getElementById('timeline-ticks-container');
        if (!container) return;
        container.querySelectorAll('.timeline-milestone').forEach((el) => el.remove());
        if (globalTotalFrames <= 1 || !currentPlot) return;

        const d = _phaseData(currentPlot);
        const milestones = [];
        const primaryStep = _mv(d, 'primary_converged_step', 'steps_to_primary');
        if (primaryStep != null) {
            milestones.push({ value: 'primary_converged', label: 'Primary converged', step: primaryStep, cls: 'milestone-primary' });
        }
        const allStep = _mv(d, 'all_converged_step');
        if (allStep != null) {
            milestones.push({ value: 'all_converged', label: 'Converged', step: allStep, cls: 'milestone-all' });
        }
        // "Full" = jump to the end of the timeline (no cap, everything visible).
        milestones.push({ value: 'full', label: 'Full', step: globalStepValues[globalTotalFrames - 1], cls: 'milestone-full' });

        // A converged run's milestones often land close together (e.g. "Converged"
        // right before the final step, or equal to it) — their 12px circles would
        // then overlap and the one painted last (always "Full", added above) would
        // silently swallow clicks meant for the others. Stack any that fall within
        // MIN_GAP_PCT of an already-placed marker one row higher instead, so every
        // milestone stays independently clickable regardless of how close the run's
        // real step values are.
        const MIN_GAP_PCT = 5;
        const positioned = milestones
            .map((m) => {
                const idx = _closestFrameIndexForStep(m.step);
                const pct = idx >= 0 && globalTotalFrames > 1 ? (idx / (globalTotalFrames - 1)) * 100 : null;
                return Object.assign({}, m, { idx, pct });
            })
            .filter((m) => m.idx >= 0 && m.pct != null)
            .sort((a, b) => a.pct - b.pct);

        const placedPctByRow = [];
        positioned.forEach((m) => {
            let row = 0;
            while (placedPctByRow[row] != null && Math.abs(m.pct - placedPctByRow[row]) < MIN_GAP_PCT) {
                row += 1;
            }
            placedPctByRow[row] = m.pct;
            m.row = row;
        });

        positioned.forEach((m) => {
            const marker = document.createElement('button');
            marker.type = 'button';
            marker.className = `timeline-milestone ${m.cls}`;
            marker.style.left = `calc(${m.pct}% - 6px)`;
            if (m.row > 0) marker.style.marginTop = `${-15 - m.row * 14}px`;
            marker.title = `Jump to: ${m.label} (step ${formatCount(m.step)})`;
            marker.setAttribute('aria-label', `Jump to ${m.label}`);
            marker.addEventListener('click', (e) => {
                e.preventDefault();
                setStoppingCriteria(m.value);
                updateScanViewAtCaption(currentPlot);
                jumpTimelineToStep(m.step);
            });
            container.appendChild(marker);
        });
    }

    function updateGlobalLabel(idx) {
        if (!globalTotalFrames) {
            globalLabel.innerHTML = 'Step: --';
            return;
        }
        const val = (globalStepValues && globalStepValues[idx] !== undefined) ? globalStepValues[idx] : idx;
        globalLabel.innerHTML = `Step: ${val} (${idx + 1} / ${globalTotalFrames})`;
    }

    function syncFrames(idx) {
        updateGlobalLabel(idx);
        for (const iframe of activeIframes) {
            try {
                const win = iframe.contentWindow;
                if (win && typeof win.showFrame === 'function') {
                    // totalFrames === 0 means "no fixed frame count" (e.g. the scan
                    // measurements adapter, which filters by real step value rather than
                    // a local frame index) — pass idx through unclamped in that case.
                    const localIdx = (win.totalFrames > 0) ? Math.min(idx, win.totalFrames - 1) : idx;
                    win.showFrame(localIdx);
                }
            } catch (e) { }
        }
    }

    globalSlider.addEventListener('input', (e) => {
        scanTimelineUserDriven = true;
        const idx = parseInt(e.target.value, 10);
        syncFrames(idx);
    });

    globalPlayBtn.addEventListener('click', () => {
        if (globalIsPlaying) {
            globalPause();
        } else {
            globalPlay();
        }
    });

    globalSpeedSelect.addEventListener('change', () => {
        if (globalIsPlaying) {
            globalPause();
            globalPlay();
        }
    });

    function globalPlay() {
        globalIsPlaying = true;
        globalPlayBtn.innerHTML = '<svg width="12" height="12" viewBox="0 0 24 24" fill="currentColor" style="display:inline-block; vertical-align:middle; margin-right:4px;"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg><span>Pause</span>';
        globalPlayBtn.style.background = '#ffebe6';
        globalPlayBtn.style.borderColor = '#ff4d4d';
        globalPlayBtn.style.color = '#960000';

        const intervalMs = parseInt(globalSpeedSelect.value, 10);
        scanTimelineUserDriven = true;
        globalPlayInterval = setInterval(() => {
            let nextIdx = parseInt(globalSlider.value, 10) + 1;
            if (nextIdx > parseInt(globalSlider.max, 10)) {
                nextIdx = 0;
            }
            globalSlider.value = nextIdx;
            syncFrames(nextIdx);
        }, intervalMs);
    }

    function globalPause() {
        globalIsPlaying = false;
        globalPlayBtn.innerHTML = '<svg width="12" height="12" viewBox="0 0 24 24" fill="currentColor" style="display:inline-block; vertical-align:middle; margin-right:4px;"><path d="M8 5v14l11-7z"/></svg><span>Play</span>';
        globalPlayBtn.style.background = '#e6f2ff';
        globalPlayBtn.style.borderColor = '#1e90ff';
        globalPlayBtn.style.color = '#005b96';

        clearInterval(globalPlayInterval);
    }

    function updateBayesView(selectedPlot) {
        if (!bayesSection || !bayesImage) {
            return;
        }

        if (!selectedPlot) {
            bayesImage.hidden = true;
            bayesImage.removeAttribute('src');
            return;
        }

        const bayesPlot = bayesPlots.find(
            (p) =>
                p.generator === selectedPlot.generator &&
                p.noise === selectedPlot.noise &&
                p.strategy === selectedPlot.strategy &&
                p.repeat === selectedPlot.repeat
        );

        if (!bayesPlot) {
            bayesImage.hidden = true;
            bayesImage.removeAttribute('src');
            return;
        }

        bayesImage.src = bayesPlot.path;
        bayesImage.hidden = false;
    }

    // Helper: get-or-create a div container for JSON-rendered plots inside a section.
    // The iframe is hidden when the div is used, and cleared when neither is available.
    function _jsonContainer(section, iframeEl, divId) {
        let div = document.getElementById(divId);
        if (!div) {
            div = document.createElement('div');
            div.id = divId;
            section.appendChild(div);
        }
        div.style.display = 'block';
        if (iframeEl) { iframeEl.style.display = 'none'; iframeEl.src = ''; }
        return div;
    }

    function _iframeContainer(section, iframeEl, divId, src) {
        const div = document.getElementById(divId);
        if (div) { div.style.display = 'none'; div.innerHTML = ''; }
        if (iframeEl) { iframeEl.style.display = ''; iframeEl.src = src; }
    }

    function _matchesSelected(p, sel) {
        return p.generator === sel.generator &&
               p.noise === sel.noise &&
               p.strategy === sel.strategy &&
               p.repeat === sel.repeat;
    }

    function updateBayesInteractiveView(selectedPlot) {
        if (!bayesInteractiveSection || !bayesInteractiveIframe) {
            return;
        }

        // Clear registered iframes/adapters and reset the slider
        activeIframes.clear();
        // The scan measurements adapter is independent of which Bayesian plots
        // are selected — keep it registered across the clear above.
        if (scanTimelineAdapter) activeIframes.add(scanTimelineAdapter);
        const ticksContainer = document.getElementById('timeline-ticks-container');
        if (ticksContainer) ticksContainer.innerHTML = '';
        globalTotalFrames = 0;
        globalStepValues = [];
        globalSlider.value = 0;
        globalSlider.max = 0;
        updateGlobalTimelineMetadata();

        if (!selectedPlot) {
            bayesInteractiveSection.dataset.available = 'false';
            bayesInteractiveIframe.src = '';
            bayesConvergenceSection.dataset.available = 'false';
            bayesConvergenceIframe.src = '';
            bayesConvMetricsIframe.src = '';
            bayesFisherSection.dataset.available = 'false';
            bayesFisherIframe.src = '';
            bayesFisherPairsSection.dataset.available = 'false';
            bayesFisherPairsIframe.src = '';
            bayesCovarianceSection.dataset.available = 'false';
            bayesEllipseContainer.innerHTML = '';
            bayesJitterContent.innerHTML = '';
            ['bayes-posterior-container', 'bayes-conv-json-container',
             'bayes-conv-metrics-json-container', 'bayes-fisher-json-container'].forEach((id) => {
                const el = document.getElementById(id);
                if (el) { el.style.display = 'none'; el.innerHTML = ''; }
            });
            return;
        }

        // CRLB overlay data — resolved once up front so the posterior/convergence
        // renderers below can draw the Cramér-Rao bound alongside their existing
        // actual-uncertainty and convergence-threshold lines.
        const fisherDataPlotForOverlay = bayesFisherDataPlots.find((p) => _matchesSelected(p, selectedPlot));
        const crlbOverlayPath = fisherDataPlotForOverlay ? fisherDataPlotForOverlay.path : null;

        // --- Posterior animation ---
        const posteriorDataPlot = bayesPosteriorDataPlots.find((p) => _matchesSelected(p, selectedPlot));
        const interactivePlot = bayesInteractivePlots.find((p) => _matchesSelected(p, selectedPlot));

        if (posteriorDataPlot) {
            const div = _jsonContainer(bayesInteractiveSection, bayesInteractiveIframe, 'bayes-posterior-container');
            bayesInteractiveSection.dataset.available = 'true';
            renderPosterior(div, posteriorDataPlot.path, (adapter) => {
                registerTimelineAdapter(adapter);
            }, crlbOverlayPath);
        } else if (interactivePlot) {
            _iframeContainer(bayesInteractiveSection, bayesInteractiveIframe, 'bayes-posterior-container', interactivePlot.path);
            bayesInteractiveIframe.style.height = '85vh';
            bayesInteractiveSection.dataset.available = 'true';
            registerIframeForTimeline(bayesInteractiveIframe);
        } else {
            bayesInteractiveSection.dataset.available = 'false';
            bayesInteractiveIframe.src = '';
            bayesInteractiveIframe.style.height = '';
        }

        // --- Parameter convergence ---
        const paramConvDataPlot = bayesParamConvDataPlots.find((p) => _matchesSelected(p, selectedPlot));
        const convergencePlot = plots.find((p) => p.type === 'bayesian_parameter_convergence' && _matchesSelected(p, selectedPlot));
        const convMetricsDataPlot = bayesConvMetricsDataPlots.find((p) => _matchesSelected(p, selectedPlot));
        const convMetricsPlot = plots.find((p) => p.type === 'bayesian_convergence_metrics' && _matchesSelected(p, selectedPlot));

        if (paramConvDataPlot || convMetricsDataPlot) {
            bayesConvergenceSection.dataset.available = 'true';
            if (convMetricsDataPlot) {
                const topDiv = document.getElementById('bayes-conv-json-container');
                if (topDiv) topDiv.style.display = 'none';
                if (bayesConvergenceIframe) {
                    bayesConvergenceIframe.style.display = 'none';
                    bayesConvergenceIframe.src = '';
                }
                const div = _jsonContainer(bayesConvergenceSection, bayesConvMetricsIframe, 'bayes-conv-metrics-json-container');
                renderConvergenceMetrics(div, convMetricsDataPlot.path, (adapter) => {
                    registerTimelineAdapter(adapter);
                }, crlbOverlayPath, posteriorDataPlot ? posteriorDataPlot.path : null);
            } else {
                if (paramConvDataPlot) {
                    const div = _jsonContainer(bayesConvergenceSection, bayesConvergenceIframe, 'bayes-conv-json-container');
                    renderParameterConvergence(div, paramConvDataPlot.path, (adapter) => {
                        registerTimelineAdapter(adapter);
                    }, crlbOverlayPath, posteriorDataPlot ? posteriorDataPlot.path : null);
                } else {
                    _iframeContainer(bayesConvergenceSection, bayesConvergenceIframe, 'bayes-conv-json-container', convergencePlot ? convergencePlot.path : '');
                }
                _iframeContainer(bayesConvergenceSection, bayesConvMetricsIframe, 'bayes-conv-metrics-json-container', convMetricsPlot ? convMetricsPlot.path : '');
            }
        } else if (convergencePlot || convMetricsPlot) {
            bayesConvergenceSection.dataset.available = 'true';
            _iframeContainer(bayesConvergenceSection, bayesConvergenceIframe, 'bayes-conv-json-container', convergencePlot ? convergencePlot.path : '');
            _iframeContainer(bayesConvergenceSection, bayesConvMetricsIframe, 'bayes-conv-metrics-json-container', convMetricsPlot ? convMetricsPlot.path : '');
        } else {
            bayesConvergenceSection.dataset.available = 'false';
            bayesConvergenceIframe.src = '';
            bayesConvMetricsIframe.src = '';
        }

        // --- Fisher information ---
        const fisherDataPlot = fisherDataPlotForOverlay;
        const fisherPlot = plots.find((p) => p.type === 'bayesian_fisher_bounds' && _matchesSelected(p, selectedPlot));
        const fisherPairsPlot = plots.find((p) => p.type === 'bayesian_fisher_crlb_pairs' && _matchesSelected(p, selectedPlot));

        if (fisherDataPlot) {
            const div = _jsonContainer(bayesFisherSection, bayesFisherIframe, 'bayes-fisher-json-container');
            bayesFisherSection.dataset.available = 'true';
            bayesFisherPairsSection.dataset.available = 'false';
            bayesFisherPairsIframe.src = '';
            renderFisher(div, fisherDataPlot.path);
        } else if (fisherPlot) {
            _iframeContainer(bayesFisherSection, bayesFisherIframe, 'bayes-fisher-json-container', fisherPlot.path);
            bayesFisherSection.dataset.available = 'true';
            if (fisherPairsPlot) {
                bayesFisherPairsIframe.src = fisherPairsPlot.path;
                bayesFisherPairsSection.dataset.available = 'true';
            } else {
                bayesFisherPairsSection.dataset.available = 'false';
                bayesFisherPairsIframe.src = '';
            }
        } else {
            bayesFisherSection.dataset.available = 'false';
            bayesFisherIframe.src = '';
            bayesFisherPairsSection.dataset.available = 'false';
            bayesFisherPairsIframe.src = '';
        }

        // --- Covariance ellipses (already JSON-based) ---
        const ellipsePlot = plots.find((p) => p.type === 'bayesian_covariance_ellipses_data' && _matchesSelected(p, selectedPlot));
        if (ellipsePlot) {
            renderCovarianceEllipses(bayesEllipseContainer, ellipsePlot.path, (adapter) => {
                registerTimelineAdapter(adapter);
            });
        } else {
            bayesEllipseContainer.innerHTML = '';
        }

        // --- Jitter ---
        const jitterPlot = plots.find((p) => p.type === 'bayesian_jitter' && _matchesSelected(p, selectedPlot));
        if (jitterPlot && bayesJitterContent) {
            renderJitterView(bayesJitterContent, jitterPlot);
        } else if (bayesJitterContent) {
            bayesJitterContent.innerHTML = '';
        }

        if (ellipsePlot || jitterPlot) {
            bayesCovarianceSection.dataset.available = 'true';
        } else {
            bayesCovarianceSection.dataset.available = 'false';
        }
    }

    function updateBayesStatsView(selectedPlot) {
        if (!bayesStatsSection || !posteriorHistoryImage || !convergenceStatsImage) {
            return;
        }

        if (!selectedPlot) {
            bayesStatsSection.dataset.available = 'false';
            return;
        }

        const posteriorPlot = bayesStatsPlots.find(
            (p) =>
                p.kind === 'posterior_history' &&
                p.generator === selectedPlot.generator &&
                p.noise === selectedPlot.noise &&
                p.strategy === selectedPlot.strategy &&
                p.repeat === selectedPlot.repeat
        );

        const convergencePlot = bayesStatsPlots.find(
            (p) =>
                p.kind === 'convergence_stats' &&
                p.generator === selectedPlot.generator &&
                p.noise === selectedPlot.noise &&
                p.strategy === selectedPlot.strategy &&
                p.repeat === selectedPlot.repeat
        );

        if (posteriorPlot) {
            posteriorHistoryImage.src = posteriorPlot.path;
            posteriorHistoryImage.hidden = false;
        } else {
            posteriorHistoryImage.hidden = true;
        }

        if (convergencePlot) {
            convergenceStatsImage.src = convergencePlot.path;
            convergenceStatsImage.hidden = false;
        } else {
            convergenceStatsImage.hidden = true;
        }

        if (posteriorPlot || convergencePlot) {
            bayesStatsSection.dataset.available = 'true';
        } else {
            bayesStatsSection.dataset.available = 'false';
        }
    }



    function updateBayesTabs() {
        const tabBar = document.getElementById('bayes-tab-bar');
        if (!tabBar) return;

        const sections = [
            { id: 'bayes-interactive-section', label: 'Posterior Evolution' },
            { id: 'bayes-convergence-section', label: 'Convergence' },
            { id: 'bayes-fisher-section', label: 'Fisher Bounds' },
            { id: 'bayes-fisher-pairs-section', label: 'CRLB Pairs' },
            { id: 'bayes-covariance-section', label: 'Covariance' },
            { id: 'bayes-stats-section', label: 'Statistics' },
        ];

        const available = sections.filter((s) => {
            const el = document.getElementById(s.id);
            return el && el.dataset.available === 'true';
        });

        const bayesSectionContainer = document.getElementById('bayes-section-container');
        const noDataMsg = document.getElementById('bayes-no-data-message');

        const isRange = isNoiseRangeMode() || isGeneratorRangeMode();
        const isPlainSweep = currentPlot && currentPlot.strategy && currentPlot.strategy.startsWith('SimpleSweep');

        if (!currentPlot || isRange || isPlainSweep || (
                bayesPlots.length === 0 && bayesInteractivePlots.length === 0 &&
                bayesPosteriorDataPlots.length === 0 && bayesParamConvDataPlots.length === 0 &&
                bayesConvMetricsDataPlots.length === 0 && bayesFisherDataPlots.length === 0 &&
                bayesEllipsePlots.length === 0 && bayesJitterPlots.length === 0)) {
            if (bayesSectionContainer) bayesSectionContainer.style.display = 'none';
            if (globalControls) globalControls.style.display = 'none';
            return;
        }

        if (available.length === 0) {
            tabBar.style.display = 'none';
            if (globalControls) globalControls.style.display = 'none';
            if (noDataMsg) noDataMsg.style.display = 'block';
            if (bayesSectionContainer) bayesSectionContainer.style.display = 'block';
        } else {
            tabBar.style.display = 'flex';
            if (noDataMsg) noDataMsg.style.display = 'none';
            if (bayesSectionContainer) bayesSectionContainer.style.display = 'block';
        }

        const currentActive = tabBar.querySelector('.bayes-tab-button.is-active');
        let activeId = currentActive ? currentActive.dataset.tab : null;
        // First build of this tab bar (no active button yet): honor a bayesTab
        // requested via the URL hash before falling back to the first section.
        if (!activeId && pendingHashBayesTab && available.some((s) => s.id === pendingHashBayesTab)) {
            activeId = pendingHashBayesTab;
        }
        pendingHashBayesTab = null;
        if (!available.some((s) => s.id === activeId)) {
            activeId = available[0] ? available[0].id : null;
        }

        tabBar.innerHTML = '';
        for (const s of available) {
            const btn = document.createElement('button');
            btn.className = 'bayes-tab-button' + (s.id === activeId ? ' is-active' : '');
            btn.type = 'button';
            btn.textContent = s.label;
            btn.setAttribute("role", "tab");
            btn.setAttribute("aria-selected", s.id === activeId ? "true" : "false");
            btn.tabIndex = s.id === activeId ? 0 : -1;
            btn.setAttribute("aria-controls", s.id);
            btn.setAttribute("id", "tab-" + s.id);
            const panel = document.getElementById(s.id);
            if (panel) {
                panel.setAttribute("aria-labelledby", "tab-" + s.id);
            }
            btn.dataset.tab = s.id;
            btn.addEventListener('click', () => {
                tabBar.querySelectorAll('.bayes-tab-button').forEach((b) => {
                    b.classList.remove('is-active');
                    b.setAttribute("aria-selected", "false");
                    b.tabIndex = -1;
                });
                btn.setAttribute("aria-selected", "true");
                btn.tabIndex = 0;
                btn.classList.add('is-active');
                sections.forEach((sec) => {
                    const el = document.getElementById(sec.id);
                    if (el) el.classList.toggle('is-active', sec.id === s.id);
                });
                // Trigger a window resize event so responsive Plotly charts adjust to their visible containers
                setTimeout(() => {
                    window.dispatchEvent(new Event('resize'));
                }, 0);
                // Sync frames to refresh plots and active step line
                const currentIdx = parseInt(globalSlider.value, 10);
                if (!isNaN(currentIdx)) {
                    syncFrames(currentIdx);
                }
                syncHashFromState();
            });
            btn.addEventListener('keydown', (e) => {
                const buttons = Array.from(tabBar.querySelectorAll('.bayes-tab-button'));
                const index = buttons.indexOf(btn);
                let nextIndex = null;
                if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
                    nextIndex = (index + 1) % buttons.length;
                } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
                    nextIndex = (index - 1 + buttons.length) % buttons.length;
                }
                if (nextIndex !== null) {
                    e.preventDefault();
                    buttons[nextIndex].focus();
                    buttons[nextIndex].click();
                }
            });
            tabBar.appendChild(btn);
        }

        sections.forEach((s) => {
            const el = document.getElementById(s.id);
            if (el) el.classList.toggle('is-active', s.id === activeId);
        });
    }

    const scanDefault = scanPlots.length > 0 ? scanPlots[0] : null;

    const scanGenerator = document.getElementById('scan-generator');
    const scanGeneratorFlatRow = document.getElementById('scan-generator-flat-row');
    const scanGeneratorFamilyRow = document.getElementById('scan-generator-family-row');
    const scanGeneratorFamily = document.getElementById('scan-generator-family');
    const scanGeneratorFacetsRow = document.getElementById('scan-generator-facets-row');
    const scanGeneratorFacets = document.getElementById('scan-generator-facets');
    const scanNoise = document.getElementById('scan-noise');
    const scanStrategy = document.getElementById('scan-strategy');
    const scanRepeat = document.getElementById('scan-repeat');
    const scanRepeatPrev = document.getElementById('scan-repeat-prev');
    const scanRepeatNext = document.getElementById('scan-repeat-next');
    const scanIframe = document.getElementById('scan-iframe');
    const scanMetrics = document.getElementById('scan-metrics');
    const scanSweepMetrics = document.getElementById('scan-sweep-metrics');
    const scanCompareSweep = document.getElementById('scan-compare-sweep');
    const scanCompareSweepContainer = document.getElementById('scan-compare-sweep-row') || document.getElementById('scan-compare-sweep-container');
    let currentRepeatItems = [];
    // Legend visibility the user chose on the scan plot, keyed by trace name
    // (true = shown, false = legendonly). Re-applied to every re-render (timeline
    // scrub/jump, step cap, repeat switch) so toggles persist.
    const scanLegendVisibility = new Map();
    let scanFlipViewEnabled = false;

    function resolveTraceVisibleState(value) {
        if (Array.isArray(value)) {
            if (value.length === 0) {
                return null;
            }
            return resolveTraceVisibleState(value[0]);
        }
        if (value === true) {
            return true;
        }
        if (value === false || value === 'legendonly') {
            return false;
        }
        return null;
    }

    function _getScanGraphDiv() {
        const scanPlotDiv = document.getElementById('scan-plot-div');
        if (scanPlotDiv && scanPlotDiv.style.display !== 'none' && scanPlotDiv.data) {
            return { graphDiv: scanPlotDiv, plotly: window.Plotly };
        }
        if (scanIframe && scanIframe.contentWindow && scanIframe.contentWindow.Plotly) {
            const fd = scanIframe.contentDocument;
            if (fd) {
                const gd = fd.querySelector('.plotly-graph-div');
                if (gd) return { graphDiv: gd, plotly: scanIframe.contentWindow.Plotly };
            }
        }
        return null;
    }

    function _scanLegendKey(trace) {
        if (!trace || trace.showlegend === false || trace.name == null) return null;
        const name = String(trace.name).trim();
        return name === '' ? null : name;
    }

    // Applies the remembered legend visibility to figure traces in place, before
    // Plotly.react, so re-renders don't flash back to the default visibility.
    function applyScanLegendPreferenceToFigure(figData) {
        if (!Array.isArray(figData) || scanLegendVisibility.size === 0) return figData;
        for (const trace of figData) {
            const key = _scanLegendKey(trace);
            if (key !== null && scanLegendVisibility.has(key)) {
                trace.visible = scanLegendVisibility.get(key) ? true : 'legendonly';
            }
        }
        return figData;
    }

    function applyScanLegendPreferenceInScanIframe() {
        if (scanLegendVisibility.size === 0) return;
        const s = _getScanGraphDiv();
        if (!s || !Array.isArray(s.graphDiv.data)) return;
        const shown = [];
        const hidden = [];
        s.graphDiv.data.forEach((trace, idx) => {
            const key = _scanLegendKey(trace);
            if (key === null || !scanLegendVisibility.has(key)) return;
            const want = scanLegendVisibility.get(key);
            const current = trace.visible === undefined ? true : resolveTraceVisibleState(trace.visible);
            if (current === want) return;
            (want ? shown : hidden).push(idx);
        });
        if (shown.length) s.plotly.restyle(s.graphDiv, { visible: true }, shown);
        if (hidden.length) s.plotly.restyle(s.graphDiv, { visible: 'legendonly' }, hidden);
        const fitVisible = !scanLegendVisibility.has('locator most likely signal') || scanLegendVisibility.get('locator most likely signal') !== false;
        _toggleFitVsRealVisibilityOnGraph(s.graphDiv, fitVisible);
    }


    function _toggleFitVsRealVisibilityOnGraph(graphDiv, isVisible) {
        if (!graphDiv || !graphDiv.layout) return;
        let changed = false;
        const annotations = (graphDiv.layout.annotations || []).map(a => {
            if (a && (a._isFitVsReal || (a.meta && a.meta.isFitVsReal))) {
                if (a.visible !== isVisible) {
                    changed = true;
                    return Object.assign({}, a, { visible: isVisible });
                }
            }
            return a;
        });
        const shapes = (graphDiv.layout.shapes || []).map(s => {
            if (s && (s._isFitVsReal || (s.meta && s.meta.isFitVsReal))) {
                if (s.visible !== isVisible) {
                    changed = true;
                    return Object.assign({}, s, { visible: isVisible });
                }
            }
            return s;
        });
        if (changed && window.Plotly) {
            Plotly.relayout(graphDiv, { annotations, shapes });
        }
    }

    function _syncFitVsRealVisibilityInLayout(layout, isVisible) {
        if (!layout) return;
        if (Array.isArray(layout.annotations)) {
            layout.annotations.forEach(a => {
                if (a && (a._isFitVsReal || (a.meta && a.meta.isFitVsReal))) {
                    a.visible = isVisible;
                }
            });
        }
        if (Array.isArray(layout.shapes)) {
            layout.shapes.forEach(s => {
                if (s && (s._isFitVsReal || (s.meta && s.meta.isFitVsReal))) {
                    s.visible = isVisible;
                }
            });
        }
    }

    function _isSweepStrategyName(name) {
        if (!name) return false;
        const s = String(name).toLowerCase();
        return s.includes('sweep');
    }

    function updateScanCompareSweepControl(plot, rawData) {
        const scanCompareSweep = document.getElementById('scan-compare-sweep');
        const container = document.getElementById('scan-compare-sweep-row') || document.getElementById('scan-compare-sweep-container');
        if (!scanCompareSweep || !container) return;

        // Current strategy from plot or scanStrategy dropdown
        const currentStrategy = (plot && plot.strategy) || controlValue(scanStrategy) || '';
        if (_isSweepStrategyName(currentStrategy)) {
            container.style.display = 'none';
            scanCompareSweep.innerHTML = '<option value="">None (hidden)</option>';
            return;
        }

        container.style.display = 'flex';
        const currentValue = scanCompareSweep.value || '';

        // Known sweeping manners supported in NVision
        const knownSweeps = [
            'SimpleSweep-2perFWHM',
            'SimpleSweep-3perFWHM',
            'SimpleSweep-4perFWHM',
            'Smart-Sweep'
        ];

        // Also discover any additional sweep strategies present in MANIFEST or scanPlots
        const extraSweeps = (window.MANIFEST || scanPlots || [])
            .map(p => p.strategy)
            .filter(s => _isSweepStrategyName(s));

        const stratNames = [...new Set([...knownSweeps, ...extraSweeps])].sort();

        // Check if rawData has baked-in sweep measurements baseline
        const raw = rawData || (document.getElementById('scan-plot-div') && document.getElementById('scan-plot-div')._scanRawData);
        const hasBaseline = !!(raw && raw.sweep_measurements && raw.sweep_measurements.x && raw.sweep_measurements.x.length);
        if (hasBaseline && !stratNames.some(s => s.toLowerCase() === 'simplesweep (baseline)')) {
            stratNames.unshift('SimpleSweep (baseline)');
        }

        let html = '<option value="">None (hidden)</option>';
        for (const name of stratNames) {
            const sel = (name === currentValue) ? ' selected' : '';
            html += `<option value="${escapeHtml(name)}"${sel}>${escapeHtml(name)}</option>`;
        }
        scanCompareSweep.innerHTML = html;
        if (currentValue && stratNames.includes(currentValue)) {
            scanCompareSweep.value = currentValue;
        } else {
            scanCompareSweep.value = '';
        }
    }

    async function applySweepComparisonOverlay(selectedSweep) {
        const scanPlotDiv = document.getElementById('scan-plot-div');
        if (!scanPlotDiv || !window.Plotly || scanPlotDiv.style.display === 'none') return;

        // Remove any previous sweep comparison traces
        if (Array.isArray(scanPlotDiv.data)) {
            const compIdx = scanPlotDiv.data
                .map((t, i) => (t.meta && t.meta.isSweepComparison) ? i : -1)
                .filter(i => i >= 0);
            if (compIdx.length) {
                await Plotly.deleteTraces(scanPlotDiv, compIdx).catch(() => {});
            }
        }

        if (!selectedSweep) return;

        const raw = scanPlotDiv._scanRawData;
        const curGen = (currentPlot && currentPlot.generator) || controlValue(scanGenerator);
        const curNoise = (currentPlot && currentPlot.noise) || getEffectiveScanNoise();
        const curRepeatVal = controlValue(scanRepeat);

        const T = (window.GRAPH_DEFS && window.GRAPH_DEFS.scan && window.GRAPH_DEFS.scan.traces) || {};
        const baseMeas = T.sweep_meas || { type: 'scatter', mode: 'markers', marker: { size: 7, color: 'rgba(140,86,75,0.85)', line: { width: 0.6, color: '#5b3a32' } } };
        const baseMode = T.sweep_mode || { type: 'scatter', mode: 'lines', line: { color: '#8c564b', width: 2, dash: 'dot' } };

        // 1. If baseline is selected and available directly on raw
        if (selectedSweep === 'SimpleSweep (baseline)' && raw && raw.sweep_measurements && raw.sweep_measurements.x && raw.sweep_measurements.x.length) {
            const baseline = _scanBaseline(raw.y_dense);
            const traces = [];
            traces.push(Object.assign({}, baseMeas, {
                name: 'sweep measurements (baseline)',
                x: raw.sweep_measurements.x,
                y: raw.sweep_measurements.y,
                customdata: Array.from(raw.sweep_measurements.y).map(y => _depthPct(y, baseline)),
                meta: { isSweepComparison: true },
                visible: true,
            }));
            if (raw.sweep_mode_y && raw.sweep_mode_y.length) {
                traces.push(Object.assign({}, baseMode, {
                    name: 'sweep most likely signal (baseline)',
                    x: raw.x_dense,
                    y: raw.sweep_mode_y,
                    meta: { isSweepComparison: true },
                    visible: true,
                }));
            }
            if (traces.length) await Plotly.addTraces(scanPlotDiv, traces);
            return;
        }

        // 2. Try to find plot entry for the chosen strategy in MANIFEST or scanPlots
        const sweepPlot = (window.MANIFEST || scanPlots || []).find(p =>
            p.type === 'scan' &&
            p.generator === curGen &&
            p.noise === curNoise &&
            p.strategy === selectedSweep &&
            (curRepeatVal == null || String(p.repeat ?? p.attempt ?? '') === String(curRepeatVal)) &&
            p.path
        );

        if (sweepPlot && sweepPlot.path) {
            try {
                const sweepData = await _fetchJson(sweepPlot.path);
                if (sweepData) {
                    const traces = [];
                    const baseline = _scanBaseline(sweepData.y_dense || (raw && raw.y_dense));
                    if (sweepData.measurements) {
                        const m = sweepData.measurements;
                        let mx = [], my = [];
                        if (m.mode === 'steps' && m.x && m.y) {
                            mx = m.x; my = m.y;
                        } else if (m.mode === 'phases') {
                            mx = [].concat(m.coarse_x || [], m.secondary_x || [], m.tertiary_x || [], m.fine_x || []);
                            my = [].concat(m.coarse_y || [], m.secondary_y || [], m.tertiary_y || [], m.fine_y || []);
                        }
                        if (mx.length) {
                            traces.push(Object.assign({}, baseMeas, {
                                name: `sweep measurements (${selectedSweep})`,
                                x: mx, y: my,
                                customdata: Array.from(my).map(y => _depthPct(y, baseline)),
                                meta: { isSweepComparison: true },
                                visible: true,
                            }));
                        }
                        if (sweepData.y_dense_mode && sweepData.y_dense_mode.length) {
                            traces.push(Object.assign({}, baseMode, {
                                name: `sweep most likely signal (${selectedSweep})`,
                                x: sweepData.x_dense,
                                y: sweepData.y_dense_mode,
                                meta: { isSweepComparison: true },
                                visible: true,
                            }));
                        }
                    } else if (Array.isArray(sweepData.data)) {
                        for (const t of sweepData.data) {
                            const tName = t.name || '';
                            if (tName.includes('measurements') || tName.includes('sweep measurements') || tName.includes('steps')) {
                                traces.push(Object.assign({}, baseMeas, {
                                    name: `sweep measurements (${selectedSweep})`,
                                    x: t.x, y: t.y,
                                    customdata: t.customdata,
                                    meta: { isSweepComparison: true },
                                    visible: true,
                                }));
                            } else if (tName.includes('most likely signal') || tName.includes('mode belief') || tName.includes('mode_signal')) {
                                traces.push(Object.assign({}, baseMode, {
                                    name: `sweep most likely signal (${selectedSweep})`,
                                    x: t.x, y: t.y,
                                    meta: { isSweepComparison: true },
                                    visible: true,
                                }));
                            }
                        }
                    }
                    if (traces.length) {
                        await Plotly.addTraces(scanPlotDiv, traces);
                        return;
                    }
                }
            } catch (e) {
                console.warn('applySweepComparisonOverlay failed fetching sweep plot:', e);
            }
        }

        // 3. Fallback to baked-in baseline in raw data if available
        if (raw && raw.sweep_measurements && raw.sweep_measurements.x && raw.sweep_measurements.x.length) {
            const baseline = _scanBaseline(raw.y_dense);
            const traces = [];
            traces.push(Object.assign({}, baseMeas, {
                name: `sweep measurements (${selectedSweep})`,
                x: raw.sweep_measurements.x,
                y: raw.sweep_measurements.y,
                customdata: Array.from(raw.sweep_measurements.y).map(y => _depthPct(y, baseline)),
                meta: { isSweepComparison: true },
                visible: true,
            }));
            if (raw.sweep_mode_y && raw.sweep_mode_y.length) {
                traces.push(Object.assign({}, baseMode, {
                    name: `sweep most likely signal (${selectedSweep})`,
                    x: raw.x_dense,
                    y: raw.sweep_mode_y,
                    meta: { isSweepComparison: true },
                    visible: true,
                }));
            }
            if (traces.length) {
                await Plotly.addTraces(scanPlotDiv, traces);
            }
        }
    }

    function bindScanIframeLegendPreferenceSync() {
        const s = _getScanGraphDiv();
        if (!s) return;
        const graphDiv = s.graphDiv;
        if (graphDiv.dataset.scanLegendListenerAttached === '1') return;
        graphDiv.dataset.scanLegendListenerAttached = '1';
        graphDiv.on('plotly_restyle', (restyleData) => {
            if (!Array.isArray(restyleData) || restyleData.length < 2) return;
            const updates = restyleData[0] || {};
            const traceIndices = Array.isArray(restyleData[1]) ? restyleData[1] : [];
            if (!('visible' in updates) || traceIndices.length === 0 || !Array.isArray(graphDiv.data)) return;
            const visibleUpdate = updates.visible;
            traceIndices.forEach((traceIdx, i) => {
                const key = _scanLegendKey(graphDiv.data[traceIdx]);
                if (key === null) return;
                const perTrace = Array.isArray(visibleUpdate) ? visibleUpdate[i % visibleUpdate.length] : visibleUpdate;
                const nextState = resolveTraceVisibleState(perTrace);
                if (nextState !== null) scanLegendVisibility.set(key, nextState);
                if (key.includes('most likely signal') || key.includes('mode belief signal')) {
                    _toggleFitVsRealVisibilityOnGraph(graphDiv, nextState !== false);
                }
            });
        });
    }


    function formatDuration(value) {
        if (typeof value === 'number' && Number.isFinite(value)) {
            const totalMs = value;
            const ms = Math.floor(totalMs % 1000);
            const totalSecs = Math.floor(totalMs / 1000);
            const secs = totalSecs % 60;
            const totalMins = Math.floor(totalSecs / 60);
            const mins = totalMins % 60;
            const hours = Math.floor(totalMins / 60);

            const msStr = ms.toString().padStart(3, '0');
            const secsStr = secs.toString().padStart(2, '0');
            const minsStr = mins.toString().padStart(2, '0');
            const hoursStr = hours.toString().padStart(2, '0');

            if (hours > 0) {
                return hoursStr + ':' + minsStr + ':' + secsStr + '.' + msStr;
            } else {
                return minsStr + ':' + secsStr + '.' + msStr;
            }
        }
        return 'N/A';
    }

    function formatTimestamp(isoString) {
        if (!isoString || typeof isoString !== 'string') {
            return 'N/A';
        }
        try {
            const d = new Date(isoString);
            if (Number.isNaN(d.getTime())) {
                return isoString;
            }
            return d.toLocaleString();
        } catch (e) {
            return isoString;
        }
    }

    function renderSweepMetricsPanel(container, metrics) {
        if (!container) return;
        container.innerHTML = '';
        // Build a displayable focus_window string from acquisition bounds,
        // but only for sweep locators that support focus (indicated by
        // the presence of expected_focused_points).
        if (metrics.expected_focused_points != null &&
            metrics.acquisition_lo != null && metrics.acquisition_hi != null) {
            const lo = Number(metrics.acquisition_lo);
            const hi = Number(metrics.acquisition_hi);
            if (Number.isFinite(lo) && Number.isFinite(hi)) {
                metrics.focus_window = '[' + lo.toExponential(3) + ', ' + hi.toExponential(3) + ']';
            }
        }
        const items = [
            { key: 'measurements_done', label: 'Measurements done', tip: 'Actual measurements taken before stopping or hitting the step limit.', fmt: formatCount },
            { key: 'dips_detected', label: 'Dips detected', tip: 'Dips found in the initial sweep after noise filtering. When the sweep is too sparse to detect dips, falls back to the true ground-truth dip count.', fmt: formatCount },
            { key: 'dips_merged', label: 'Dips merged', tip: 'Whether detected dips are close enough to be treated as one combined range.', fmt: function (v) { return v ? 'Yes' : 'No'; } },
            { key: 'min_dip_width', label: 'Dip width', tip: 'Width of the actual signal dip in physical frequency units.', fmt: formatHz },
            { key: 'total_signal_span', label: 'Signal span', tip: 'Total span from first dip start to last dip end in physical frequency units.', fmt: formatHz },
            { key: 'sweep_efficiency', label: 'Efficiency', tip: 'Expected uniform points / actual measurements. >1 means the locator was efficient.', fmt: formatMetricValue },
            { key: 'focus_window', label: 'Focus window', tip: 'Drive-frequency window the locator restricts EIG candidates to (the padded bounding interval of the significant dips detected in the measurements; absent while it is the full drive axis). Detected dips are drawn separately.', fmt: function (v) { return v; } },
        ];
        let any = false;
        for (const it of items) {
            const val = metrics[it.key];
            if (val == null || (typeof val === 'number' && !Number.isFinite(val))) continue;
            any = true;
            const el = document.createElement('div');
            el.className = 'metric-item';
            if (it.key === 'sweep_efficiency' && val != null) {
                if (val >= 1) {
                    el.classList.add('efficiency-good');
                } else if (val >= 0.5) {
                    el.classList.add('efficiency-medium');
                } else {
                    el.classList.add('efficiency-bad');
                }
            }
            let formula = '';
            if (it.key === 'sweep_efficiency' && metrics.expected_uniform_points != null && metrics.measurements_done != null) {
                formula = '<div class="metric-formula">' + formatCount(metrics.expected_uniform_points) + ' expected / ' + formatCount(metrics.measurements_done) + ' actual = ' + it.fmt(val) + '×</div>';
            }
            el.innerHTML =
                '<div class="metric-header">' +
                '<span class="metric-label">' + it.label + '</span>' +
                '<span class="help-icon" tabindex="0" title="' + it.tip.replace(/"/g, '&quot;') + '">?</span>' +
                '</div>' +
                '<div class="metric-value">' + it.fmt(val) + '</div>' + formula;
            container.appendChild(el);
        }
        container.hidden = !any;
    }


    // Parse plot data from scan file on-demand (handles lean data, .json.gz, and legacy .html)
    async function loadPlotDataFromScanHtml(plot) {
        if (!plot || !plot.path) return null;
        try {
            if (plot.path.endsWith('.json') || plot.path.endsWith('.json.gz')) {
                const raw = await _fetchJson(plot.path);
                if (raw && raw._graph_type === 'scan') {
                    // Lean scan data — return the plot_data subset as plain arrays
                    const pd = _decodePlotlyFigure(raw);  // already decoded; re-run is idempotent
                    const toPlainArr = (v) => ArrayBuffer.isView(v) ? Array.from(v) : v;
                    const plainMeas = (m) => {
                        if (!m || typeof m !== 'object') return { mode: 'empty' };
                        const r = { mode: m.mode };
                        for (const k of Object.keys(m)) {
                            if (k === 'mode') continue;
                            r[k] = ArrayBuffer.isView(m[k]) ? Array.from(m[k]) : m[k];
                        }
                        return r;
                    };
                    const out = {
                        x_dense: toPlainArr(raw.x_dense),
                        y_dense: toPlainArr(raw.y_dense),
                        has_metrics: !!raw.has_metrics,
                        measurements: plainMeas(raw.measurements),
                    };
                    if (raw.y_dense_noisy) out.y_dense_noisy = toPlainArr(raw.y_dense_noisy);
                    if (raw.y_dense_noisy_lo) out.y_dense_noisy_lo = toPlainArr(raw.y_dense_noisy_lo);
                    if (raw.y_dense_noisy_hi) out.y_dense_noisy_hi = toPlainArr(raw.y_dense_noisy_hi);
                    if (raw.y_dense_noisy_lo2) out.y_dense_noisy_lo2 = toPlainArr(raw.y_dense_noisy_lo2);
                    if (raw.y_dense_noisy_hi2) out.y_dense_noisy_hi2 = toPlainArr(raw.y_dense_noisy_hi2);
                    if (raw.y_dense_mode) out.y_dense_mode = toPlainArr(raw.y_dense_mode);
                    if (raw.focus_window) out.focus_window = Array.isArray(raw.focus_window) ? raw.focus_window : Array.from(raw.focus_window);
                    if (raw.narrowed_param_bounds) out.narrowed_param_bounds = raw.narrowed_param_bounds;
                    return out;
                }
                // Full Plotly figure (legacy) — extract from traces
                if (!raw || !Array.isArray(raw.data)) return null;
                const out = extractPlotDataFromTraces(raw.data);
                if (!out) return null;
                const meta = raw.layout && raw.layout.meta;
                if (meta && meta.narrowed_param_bounds && typeof meta.narrowed_param_bounds === 'object') {
                    out.narrowed_param_bounds = meta.narrowed_param_bounds;
                }
                return out;
            }
            const response = await fetch(resolveAssetPath(plot.path), { cache: 'no-store' });
            if (!response.ok) return null;
            const html = await response.text();
            return parsePlotDataFromHtml(html);
        } catch (e) {
            console.warn('Failed to load plot data from', plot.path, e);
            return null;
        }
    }

    function parsePlotDataFromHtml(html) {
        // Extract Plotly.newPlot data arrays + layout from HTML
        const m = html.match(/Plotly\.newPlot\(\s*"[^"]+",\s*/);
        if (!m) return null;
        const pos = m.index + m[0].length;
        try {
            const dataStr = html.slice(pos);
            // Find the end of the data array (first top-level array close)
            let depth = 0;
            let end = 0;
            for (let i = 0; i < dataStr.length; i++) {
                if (dataStr[i] === '[') depth++;
                else if (dataStr[i] === ']') {
                    depth--;
                    if (depth === 0) { end = i + 1; break; }
                } else if (dataStr[i] === '{' && depth === 0) {
                    // Started object before array - malformed
                    break;
                }
            }
            const data = JSON.parse(dataStr.slice(0, end));
            if (!Array.isArray(data)) return null;
            const out = extractPlotDataFromTraces(data);
            if (!out) return null;

            // Try to parse layout for narrowed_param_bounds in meta
            try {
                let layoutStart = pos + end;
                while (layoutStart < html.length && /[\s,]/.test(html[layoutStart])) layoutStart++;
                if (html[layoutStart] === '{') {
                    // find matching closing brace
                    let ldepth = 0, lend = 0;
                    for (let i = layoutStart; i < html.length; i++) {
                        if (html[i] === '{') ldepth++;
                        else if (html[i] === '}') {
                            ldepth--;
                            if (ldepth === 0) { lend = i + 1; break; }
                        }
                    }
                    if (lend > layoutStart) {
                        const layout = JSON.parse(html.slice(layoutStart, lend));
                        const meta = layout && layout.meta;
                        if (meta && meta.narrowed_param_bounds && typeof meta.narrowed_param_bounds === 'object') {
                            out.narrowed_param_bounds = meta.narrowed_param_bounds;
                        }
                    }
                }
            } catch (layoutErr) {
                // Non-critical: layout parse failures are silently ignored
            }
            return out;
        } catch (e) {
            console.warn('Failed to parse plot data from HTML:', e);
            return null;
        }
    }


    function extractPlotDataFromTraces(traces) {
        let x_dense = null, y_dense = null, y_dense_noisy = null, y_dense_mode = null;
        let coarse_x = [], coarse_y = [], secondary_x = [], secondary_y = [], tertiary_x = [], tertiary_y = [], fine_x = [], fine_y = [], fine_step = [];
        let step_x = [], step_y = [], step_idx = [];
        let has_metrics = false, focus_window = null;

        for (const tr of traces) {
            const name = tr.name || '';
            const mode = tr.mode || '';
            if ((name === 'locator most likely signal' || name === 'locator mode belief signal') && mode.includes('lines')) {
                y_dense_mode = tr.y;
            } else if (name === 'true signal' && mode.includes('lines')) {
                x_dense = tr.x;
                y_dense = tr.y;
            } else if (name === 'simulated noisy signal (over-frequency)' && mode.includes('lines')) {
                y_dense_noisy = tr.y?.map((v, i) => v != null ? v : (y_dense?.[i] || 0));
            } else if (name === 'measurements (coarse)') {
                coarse_x = tr.x || [];
                coarse_y = tr.y || [];
            } else if (name === 'measurements (secondary)') {
                secondary_x = tr.x || [];
                secondary_y = tr.y || [];
            } else if (name === 'measurements (tertiary)') {
                tertiary_x = tr.x || [];
                tertiary_y = tr.y || [];
            } else if (name === 'measurements (inference)') {
                fine_x = tr.x || [];
                fine_y = tr.y || [];
                fine_step = tr.marker?.color || fine_x.map((_, i) => i);
            } else if (name === 'measurements (noisy)') {
                step_x = tr.x || [];
                step_y = tr.y || [];
                step_idx = tr.marker?.color || step_x.map((_, i) => i);
            } else if (name === 'Entropy' || name === 'Uncertainty') {
                has_metrics = true;
            }
        }

        if (!x_dense || !y_dense) return null;

        const out = { x_dense, y_dense, has_metrics };
        if (y_dense_mode && y_dense_mode.length === x_dense.length) out.y_dense_mode = y_dense_mode;
        if (y_dense_noisy && y_dense_noisy.length === x_dense.length) out.y_dense_noisy = y_dense_noisy;

        if (coarse_x.length || secondary_x.length || tertiary_x.length || fine_x.length) {
            out.measurements = {
                mode: 'phases',
                coarse_x, coarse_y: coarse_y.map(y => y == null ? null : Number(y)),
                secondary_x, secondary_y: secondary_y.map(y => y == null ? null : Number(y)),
                tertiary_x, tertiary_y: tertiary_y.map(y => y == null ? null : Number(y)),
                fine_x, fine_y: fine_y.map(y => y == null ? null : Number(y)),
                fine_step: fine_step.map(s => Number(s))
            };
        } else if (step_x.length) {
            out.measurements = {
                mode: 'steps',
                x: step_x,
                y: step_y.map(y => y == null ? null : Number(y)),
                step: step_idx.map(s => Number(s))
            };
        } else {
            out.measurements = { mode: 'empty' };
        }

        return out;
    }


    // Fold a scan figure at the true zero_field_freq: every trace is clipped to its
    // right half (x >= center), and the true-signal curve's left half is reflected
    // (x -> 2*center - x) and re-plotted as a dotted overlay on that same right-half
    // range, so Zeeman/hyperfine symmetry can be checked visually with the halves
    // superimposed instead of side by side. Fallback used when the signal has no
    // Zeeman splitting to split into two per-group subplots.
    function _foldScanFigureAtCenter(figData, figLayout, center) {
        if (!Array.isArray(figData) || !figData.length) return { data: figData, layout: figLayout };

        let lo = Infinity, hi = -Infinity;
        for (const t of figData) {
            if (!t.x || !t.x.length) continue;
            for (const v of t.x) {
                if (v == null || !Number.isFinite(v)) continue;
                if (v < lo) lo = v;
                if (v > hi) hi = v;
            }
        }
        if (!Number.isFinite(lo) || !Number.isFinite(hi)) return { data: figData, layout: figLayout };
        if (center === null || center === undefined) center = (lo + hi) / 2;

        const filterRight = (t) => {
            if (!t.x || !t.x.length) return t;
            const idx = [];
            for (let i = 0; i < t.x.length; i++) {
                const v = t.x[i];
                if (v != null && Number.isFinite(v) && v >= center) idx.push(i);
            }
            const pick = (arr) => (Array.isArray(arr) && arr.length === t.x.length) ? idx.map((i) => arr[i]) : arr;
            const out = Object.assign({}, t, { x: idx.map((i) => t.x[i]), y: pick(t.y), customdata: pick(t.customdata) });
            // error_y.array/arrayminus (the per-drive-frequency-point stats overlay's asymmetric
            // whiskers) are nested per-point fields parallel to x -- filter them the
            // same way so lengths stay in sync, or Plotly misaligns them post-filter.
            if (t.error_y && (t.error_y.array || t.error_y.arrayminus)) {
                out.error_y = Object.assign({}, t.error_y, { array: pick(t.error_y.array), arrayminus: pick(t.error_y.arrayminus) });
            }
            return out;
        };

        const newData = figData.map(filterRight);

        // Mirror the true-signal curve's left half onto the right-half range.
        const trueTrace = figData.find((t) => t.name === 'true signal');
        if (trueTrace && trueTrace.x && trueTrace.x.length) {
            const pts = [];
            for (let i = 0; i < trueTrace.x.length; i++) {
                const v = trueTrace.x[i];
                if (v != null && Number.isFinite(v) && v < center) {
                    pts.push([2 * center - v, trueTrace.y[i]]);
                }
            }
            pts.sort((a, b) => a[0] - b[0]);
            if (pts.length) {
                newData.push({
                    type: 'scatter', mode: 'lines',
                    name: 'true signal (mirrored left half)',
                    x: pts.map((p) => p[0]), y: pts.map((p) => p[1]),
                    line: { color: 'blue', dash: 'dot', width: 1.5 },
                });
            }
        }

        const newLayout = Object.assign({}, figLayout, {
            xaxis: Object.assign({}, figLayout && figLayout.xaxis, { range: [center, hi] }),
        });
        return { data: newData, layout: newLayout };
    }

    // Window one trace's points to [lo, hi] and, if mirrorAbout is given, reflect
    // x -> 2*mirrorAbout - x (re-sorted by x) so a mirrored trace reads in the same
    // left-to-right orientation as its un-mirrored counterpart. Also carries along
    // error_y.array/arrayminus (the per-drive-frequency-point stats overlay's whiskers) --
    // a nested field parallel to x/y that would otherwise desync from it.
    function _windowAndMirrorTrace(t, lo, hi, mirrorAbout) {
        if (!t.x || !t.x.length) return null;
        const idx = [];
        for (let i = 0; i < t.x.length; i++) {
            const v = t.x[i];
            if (v != null && Number.isFinite(v) && v >= lo && v <= hi) idx.push(i);
        }
        if (!idx.length) return null;
        const pick = (arr) => (Array.isArray(arr) && arr.length === t.x.length) ? idx.map((i) => arr[i]) : arr;
        const fieldNames = ['y', 'customdata'].filter((f) => t[f] !== undefined);
        const hasErrorY = t.error_y && (t.error_y.array || t.error_y.arrayminus);
        let xs = idx.map((i) => t.x[i]);
        const fields = {};
        for (const f of fieldNames) fields[f] = pick(t[f]);
        let errorY = hasErrorY ? { array: pick(t.error_y.array), arrayminus: pick(t.error_y.arrayminus) } : null;
        if (mirrorAbout != null) {
            const order = xs.map((_, i) => i);
            order.sort((a, b) => (2 * mirrorAbout - xs[a]) - (2 * mirrorAbout - xs[b]));
            const mirroredXs = order.map((i) => 2 * mirrorAbout - xs[i]);
            for (const f of fieldNames) {
                fields[f] = Array.isArray(fields[f]) ? order.map((i) => fields[f][i]) : fields[f];
            }
            if (errorY) {
                errorY = {
                    array: Array.isArray(errorY.array) ? order.map((i) => errorY.array[i]) : errorY.array,
                    arrayminus: Array.isArray(errorY.arrayminus) ? order.map((i) => errorY.arrayminus[i]) : errorY.arrayminus,
                };
            }
            xs = mirroredXs;
        }
        const out = Object.assign({}, t, { x: xs }, fields);
        if (errorY) out.error_y = Object.assign({}, t.error_y, errorY);
        return out;
    }

    // Split a scan figure into two stacked subplots, one per Zeeman group (centered
    // at frequency +/- zeeman_shift). The lower-frequency group has every trace
    // mirrored about its own center so both panels read in the same orientation and
    // can be visually compared for symmetry -- each panel keeps its own measurement
    // markers, so (unlike a single combined-overlay fold) you can see which specific
    // measurements landed in each group.
    function _splitScanFigureByZeemanGroup(figData, figLayout, center, zeemanShift) {
        const hw = Math.abs(zeemanShift) * 0.9;
        const c2 = center + zeemanShift; // higher-frequency group, as-is
        const c1 = center - zeemanShift; // lower-frequency group, mirrored about c1

        const topData = [];
        const bottomData = [];
        for (const t of figData) {
            // Skip metrics-row traces (entropy/uncertainty vs. step) -- not meaningful
            // windowed against a drive-frequency range, and would collide with the x2/y2
            // axes reused below for the second Zeeman-group panel.
            if (t.xaxis === 'x2' || t.yaxis === 'y2') continue;

            const top = _windowAndMirrorTrace(t, c2 - hw, c2 + hw, null);
            if (top) topData.push(Object.assign({}, top, { xaxis: 'x', yaxis: 'y' }));

            const bottom = _windowAndMirrorTrace(t, c1 - hw, c1 + hw, c1);
            if (bottom) {
                bottomData.push(Object.assign({}, bottom, {
                    xaxis: 'x2', yaxis: 'y2',
                    name: bottom.name ? bottom.name + ' (mirrored)' : bottom.name,
                }));
            }
        }

        const newLayout = Object.assign({}, figLayout, {
            shapes: [],
            annotations: [],
            grid: { rows: 2, columns: 1, pattern: 'independent' },
            xaxis: Object.assign({}, figLayout && figLayout.xaxis, {
                domain: [0, 1], anchor: 'y', range: [c2 - hw, c2 + hw],
                title: { text: 'drive_freq — Zeeman group @ zero_field_freq+' + formatHz(Math.abs(zeemanShift)) },
            }),
            yaxis: Object.assign({}, figLayout && figLayout.yaxis, { domain: [0.55, 1], anchor: 'x' }),
            xaxis2: {
                domain: [0, 1], anchor: 'y2', range: [c1 - hw, c1 + hw],
                title: { text: 'drive_freq — Zeeman group @ zero_field_freq−' + formatHz(Math.abs(zeemanShift)) + ' (mirrored)' },
                tickformat: figLayout && figLayout.xaxis && figLayout.xaxis.tickformat,
            },
            yaxis2: Object.assign({}, figLayout && figLayout.yaxis, { domain: [0, 0.45], anchor: 'x2' }),
            height: 800,
        });

        return { data: topData.concat(bottomData), layout: newLayout };
    }

    // Dispatcher for the "Flip view" toggle: splits by Zeeman group when the signal has
    // Zeeman splitting, otherwise falls back to the single center-fold.
    //
    // Folds about the *found* center and zeeman_shift (the locator's reported final estimates),
    // falling back per parameter to the true value only when the locator didn't estimate
    // it -- e.g. the center under the simulated grid's fixed-zero_field_freq default, where the
    // true value is exactly what the model assumed. Real measurements have no true value
    // at all, and their center sits ~1-2 MHz off the window midpoint the fold used to
    // default to.
    function _foldScanFigureForFlipView(figData, figLayout) {
        if (!Array.isArray(figData) || !figData.length) return { data: figData, layout: figLayout };
        const meta = (figLayout && figLayout.meta) || {};
        const fp = meta.found_params || {};
        const tp = (meta.true_params && meta.true_params.params) || {};
        const pick = (name) => Number.isFinite(fp[name]) ? fp[name] : (Number.isFinite(tp[name]) ? tp[name] : null);
        const center = pick('zero_field_freq');
        const zeemanShift = pick('zeeman_shift');
        if (center !== null && zeemanShift !== null && Math.abs(zeemanShift) > 1e-9) {
            return _splitScanFigureByZeemanGroup(figData, figLayout, center, zeemanShift);
        }
        return _foldScanFigureAtCenter(figData, figLayout, center);
    }

    async function renderPlotFromJson(container, jsonPath) {
        if (!jsonPath) { container.innerHTML = ''; return; }
        container._lastJsonPath = jsonPath;
        // Purge any pending Plotly operations on this container before replacing it.
        // Without this, an in-flight Plotly.restyle blocks the queue and subsequent
        // Plotly.react calls never execute.
        try { if (window.Plotly) Plotly.purge(container); } catch (_) {}
        // purge drops Plotly's event listeners, so the legend-sync one must be re-bound.
        delete container.dataset.scanLegendListenerAttached;
        // Tag this render so a stale fetch doesn't overwrite a newer one
        const renderToken = {};
        container._renderToken = renderToken;
        // Captured synchronously (before any await) so a repeat/generator switch
        // that races this render can't attach the wrong plot's overlay trace.
        const plotAtStart = currentPlot;
        container.innerHTML = '<div style="padding:1.5em;color:#64748b;text-align:center;">Loading…</div>';
        try {
            await ensurePlotly();
            const raw = await _fetchJson(jsonPath);
            // Abort if a newer renderPlotFromJson started while we were fetching
            if (container._renderToken !== renderToken) return;

            // Convert TypedArrays (Float32Array etc.) to plain JS arrays for Plotly compatibility.
            // Required for fill="tonexty", customdata, marker.color, and other Plotly features
            // that don't accept typed arrays in all versions.
            const toPlain = (o) => {
                if (o === null || o === undefined) return o;
                if (ArrayBuffer.isView(o)) return Array.from(o);
                if (Array.isArray(o)) return o.map(toPlain);
                if (typeof o === 'object') {
                    const r = {};
                    for (const k of Object.keys(o)) r[k] = toPlain(o[k]);
                    return r;
                }
                return o;
            };

            const isScanPlot = container.id === 'scan-plot-div';
            const plain = toPlain(raw);
            const isScanFigure = isScanPlot && plain && plain._graph_type === 'scan';
            if (isScanFigure) {
                // Keep the decoded data around so the global play/scrub timeline and the
                // "View at" convergence-criteria selector can re-filter measurements by
                // step and re-render without re-fetching.
                container._scanRawData = plain;
            }

            let figData, figLayout;
            if (raw && raw._graph_type) {
                // Lean data file — build figure from static definition.
                // toPlain applied so builders receive plain arrays throughout.
                let dataForBuild = plain;
                if (isScanFigure && plain.measurements) {
                    const cap = getStoppingFrameLimit();
                    if (cap != null) {
                        dataForBuild = Object.assign({}, plain, {
                            measurements: _filterScanMeasurementsByStep(plain.measurements, cap),
                        });
                    }
                }
                const built = await buildFigureFromData(dataForBuild);
                figData = built.data;
                figLayout = Object.assign({}, built.layout, { autosize: true });
                if (isScanFigure) {
                    const withOverlay = await _withDriveFreqStatsOverlay(figData, figLayout, plotAtStart, !!plain.has_metrics);
                    if (container._renderToken !== renderToken) return;
                    figData = withOverlay.data;
                    figLayout = withOverlay.layout;
                }
            } else {
                // Full Plotly figure (legacy or Bayesian) — render as-is
                const fig = plain;
                figData = fig.data || [];
                figLayout = Object.assign({}, fig.layout || {}, { autosize: true });
            }

            if (isScanPlot && scanFlipViewEnabled && raw && raw._graph_type === 'scan') {
                const folded = _foldScanFigureForFlipView(figData, figLayout);
                figData = folded.data;
                figLayout = folded.layout;
            }

            // If this is a noise sweep summary plot, draw vertical reference line(s) for selected noise(s)
            const isSweepPlot = ['comp-iframe-summary-err-json-div', 'comp-iframe-summary-meas-json-div', 'comp-iframe-summary-savings-json-div'].includes(container.id);
            if (isSweepPlot) {
                const selectedNoises = getSelectedScanNoises();
                if (selectedNoises && selectedNoises.length) {
                    figLayout.shapes = figLayout.shapes || [];
                    selectedNoises.forEach(noiseVal => {
                        const exists = figLayout.shapes.some(s => s.type === 'line' && s.x0 === noiseVal);
                        if (!exists) {
                            figLayout.shapes.push({
                                type: 'line',
                                xref: 'x',
                                yref: 'paper',
                                x0: noiseVal,
                                x1: noiseVal,
                                y0: 0,
                                y1: 1,
                                line: {
                                    color: '#f43f5e',
                                    width: 2,
                                    dash: 'dash'
                                }
                            });
                        }
                    });
                }
            }

            if (isScanPlot) {
                applyScanLegendPreferenceToFigure(figData);
                const fitVisible = !scanLegendVisibility.has('locator most likely signal') || scanLegendVisibility.get('locator most likely signal') !== false;
                _syncFitVsRealVisibilityInLayout(figLayout, fitVisible);
            }

            // Plotly.react modifies DOM synchronously; don't await so a concurrent render
            // on the same container doesn't stall this one.
            Plotly.react(container, figData, figLayout, { responsive: true }).catch((e) => {
                console.error('Plotly.react failed for', jsonPath, e);
                if (container._renderToken === renderToken) {
                    container.innerHTML = `<div style="padding:1em;color:#ef4444;">Chart render error: ${e && e.message ? e.message : String(e)}</div>`;
                }
            });
            if (isScanPlot) {
                applyScanLegendPreferenceInScanIframe();
                bindScanIframeLegendPreferenceSync();
                renderNarrowedBoundsFromIframe();
                updateScanCompareSweepControl(plotAtStart, plain);
                const compareSweepEl = document.getElementById('scan-compare-sweep');
                if (compareSweepEl && compareSweepEl.value) {
                    applySweepComparisonOverlay(compareSweepEl.value);
                }
            }
            if (isScanFigure) {
                ensureScanTimelineAdapter();
            }
        } catch (e) {
            if (container._renderToken !== renderToken) return;
            console.warn('renderPlotFromJson failed for', jsonPath, e);
            container.innerHTML = `<div style="padding:1em;color:#ef4444;">Failed to load plot: ${e && e.message ? e.message : String(e)}</div>`;
        }
    }

    // Re-renders the scan measurements plot with only the points recorded at or
    // before `realStep` (an inference-step number, same units as the measurement
    // `step`/`fine_step` fields and as primary_converged_step/all_converged_step).
    // Pass null/undefined to show every measurement. Used by both the global
    // play/scrub timeline (per-frame) and the "View at" convergence selector (default cap).
    async function applyScanStepCap(realStep) {
        const container = document.getElementById('scan-plot-div');
        if (!container || !container._scanRawData || !window.Plotly) return;
        const raw = container._scanRawData;
        const stepCandidates = _focusWindowCandidatesForStep(currentPlot && currentPlot.series, realStep);
        const selSweep = scanCompareSweep ? scanCompareSweep.value : '';
        const includeSweep = (selSweep === 'SimpleSweep (baseline)');
        const fitVisible = !scanLegendVisibility.has('locator most likely signal') || scanLegendVisibility.get('locator most likely signal') !== false;
        const filtered = Object.assign({}, raw, {
            measurements: _filterScanMeasurementsByStep(raw.measurements, realStep),
            focus_window_candidates: stepCandidates,
            include_sweep_overlay: includeSweep,
            sweep_strategy_label: includeSweep ? 'SimpleSweep' : undefined,
            fit_vs_real_visible: fitVisible,
        });
        try {
            const built = await buildFigureFromData(filtered);
            let figData = built.data;
            let figLayout = Object.assign({}, built.layout, { autosize: true });
            // The per-drive-frequency-point stats overlay covers every recorded shot regardless of
            // inference step, so it's exempt from the step cap -- re-added at full extent.
            const withOverlay = await _withDriveFreqStatsOverlay(figData, figLayout, currentPlot, !!raw.has_metrics);
            figData = withOverlay.data;
            figLayout = withOverlay.layout;
            if (scanFlipViewEnabled) {
                const folded = _foldScanFigureForFlipView(figData, figLayout);
                figData = folded.data;
                figLayout = folded.layout;
            }
            applyScanLegendPreferenceToFigure(figData);
            _syncFitVsRealVisibilityInLayout(figLayout, fitVisible);
            await Plotly.react(container, figData, figLayout, { responsive: true });
            bindScanIframeLegendPreferenceSync();
            if (scanCompareSweep && scanCompareSweep.value) {
                await applySweepComparisonOverlay(scanCompareSweep.value);
            }
        } catch (e) {
            console.warn('applyScanStepCap failed', e);
        }
    }

    // Re-applies the "View at" stopping-criteria cap to the scan plot once
    // currentPlot.metrics is known (it may not be populated yet at first render —
    // mirrors the existing applyStoppingFrameLimit() re-apply pattern).
    function refreshScanStepCapFromCriteria() {
        const container = document.getElementById('scan-plot-div');
        if (!container || !container._scanRawData) return;
        applyScanStepCap(getStoppingFrameLimit());
    }

    // Lets the global play/scrub timeline drive the scan measurements plot too,
    // alongside the Bayesian posterior/convergence/fisher/ellipse plots.
    function ensureScanTimelineAdapter() {
        if (!scanTimelineAdapter) {
            scanTimelineAdapter = {
                contentWindow: {
                    showFrame: (idx) => {
                        // Ignore programmatic syncs (data just loaded) — only a real user
                        // interaction with the timeline should override the "View at" cap.
                        if (!scanTimelineUserDriven) return;
                        const realStep = (globalStepValues && idx < globalStepValues.length && globalStepValues[idx] != null)
                            ? globalStepValues[idx] : idx;
                        applyScanStepCap(realStep);
                    },
                    // 0 = "no fixed frame count": never wins the max-frames vote in
                    // updateGlobalTimelineMetadata, and syncFrames passes idx through
                    // unclamped (see the totalFrames > 0 guard there).
                    totalFrames: 0,
                },
                addEventListener: () => {},
            };
        }
        registerTimelineAdapter(scanTimelineAdapter);
    }

    // Builds the "actual averages per-drive-frequency-point" overlay traces for a MATLAB run
    // -- the per-bin mean/std/min/max of every shot recorded in the .mat file
    // (independent of which bins the adaptive locator actually visited). Drawn
    // as candle-like error-bar pairs rather than Plotly's own `candlestick`
    // trace type, which has no width control (confirmed against its attribute
    // schema -- only `line.width` and a `whiskerwidth` that candlestick ignores)
    // and can't mark a fifth point (the mean) inside the box: a thin whisker
    // (pixel-width, not data-width, so it stays thin at any zoom or bin spacing)
    // spans the true min-max range, and a thicker, shorter marker+error-bar pair
    // centered exactly on the mean spans ±std with an explicit horizontal tick
    // at the mean itself.
    function _buildDriveFreqStatsOverlayTraces(data) {
        const driveFreqPhys = Array.from(data.drive_freq_phys);
        const mean = Array.from(data.mean);
        const std = Array.from(data.std);
        const traces = [];
        const hasExtremes = Array.isArray(data.min) || ArrayBuffer.isView(data.min);
        if (hasExtremes) {
            const min = Array.from(data.min);
            const max = Array.from(data.max);
            traces.push({
                type: 'scatter',
                mode: 'markers',
                x: driveFreqPhys,
                y: mean,
                marker: { size: 0, color: 'rgba(180,83,9,0.9)' },
                error_y: {
                    type: 'data',
                    symmetric: false,
                    array: mean.map((m, i) => max[i] - m),
                    arrayminus: mean.map((m, i) => m - min[i]),
                    thickness: 1.25,
                    width: 0,
                    color: 'rgba(180,83,9,0.9)',
                },
                customdata: min.map((m, i) => [m, max[i]]),
                hovertemplate: 'drive frequency=%{x}<br>min=%{customdata[0]:.4f}<br>max=%{customdata[1]:.4f}<extra></extra>',
                name: 'Extremes (min–max)',
                legendgroup: 'matlab-drive-freq-stats',
                showlegend: true,
            });
        }
        traces.push({
            type: 'scatter',
            mode: 'markers',
            x: driveFreqPhys,
            y: mean,
            // Amber, not blue: this now shares a chart with the blue "recorded mean
            // signal" line (a related but distinct statistic -- ratio-of-means vs.
            // this trace's mean-of-ratios), and needs its own color to stay legible
            // as a separate series rather than reading as a wide/fuzzy version of it.
            marker: { symbol: 'line-ew', size: 10, line: { width: 2, color: '#b45309' } },
            error_y: {
                type: 'data', symmetric: true, array: std,
                thickness: 5, width: 0, color: 'rgba(217,119,6,0.55)',
            },
            customdata: std,
            hovertemplate: 'drive frequency=%{x}<br>average=%{y:.4f}<br>std=±%{customdata:.4f}<extra></extra>',
            name: 'Actual averages per drive-frequency point (mean ± std)',
            legendgroup: 'matlab-drive-freq-stats',
            showlegend: true,
        });
        return traces;
    }

    // Fetches (and caches on the manifest entry, mirroring ensureRepeatMeta) the
    // matlab_drive_freq_stats companion data for the given scan plot and builds it into
    // overlay traces -- present only for MATLAB (real-data) generators, which
    // have a matching matlab_drive_freq_stats entry. Resolves null when there is none.
    function _getDriveFreqStatsOverlayTraces(plot) {
        const statsPlot = plot ? matlabDriveFreqStatsPlots.find((p) => _matchesSelected(p, plot)) : null;
        if (!statsPlot) return Promise.resolve(null);
        if (!statsPlot._overlayTracesPromise) {
            statsPlot._overlayTracesPromise = _fetchJson(statsPlot.path).then((data) => {
                if (data.schema !== 'matlab_drive_freq_stats_v1' || !data.drive_freq_phys) return null;
                return _buildDriveFreqStatsOverlayTraces(data);
            }).catch((e) => {
                console.warn('Failed to load per-drive-frequency-point stats overlay', e);
                return null;
            });
        }
        return statsPlot._overlayTracesPromise;
    }

    // Appends the per-drive-frequency-point mean/std/min/max overlay (if any exists for
    // `plot`) on top of a scan figure's traces -- last in `data` so it draws over
    // the sampled-measurements markers rather than under them. `legend.groupclick:
    // 'togglegroup'` makes clicking either of the two overlay legend entries (they
    // share legendgroup 'matlab-drive-freq-stats') hide/show both together, since they're
    // two halves of one statistic rather than independent series.
    async function _withDriveFreqStatsOverlay(figData, figLayout, plot, hasMetrics) {
        const overlayTraces = await _getDriveFreqStatsOverlayTraces(plot);
        if (!overlayTraces || !overlayTraces.length) return { data: figData, layout: figLayout };
        const traces = hasMetrics
            ? overlayTraces.map((t) => Object.assign({}, t, { xaxis: 'x', yaxis: 'y' }))
            : overlayTraces;
        return {
            data: figData.concat(traces),
            layout: Object.assign({}, figLayout, {
                legend: Object.assign({}, figLayout.legend, { groupclick: 'togglegroup' }),
            }),
        };
    }

    function _getOrCreateSiblingDiv(iframeEl) {
        if (!iframeEl) return null;
        const id = iframeEl.id + '-json-div';
        let div = document.getElementById(id);
        if (!div) {
            div = document.createElement('div');
            div.id = id;
            div.style.width = '100%';
            const h = iframeEl.style.height;
            if (h) div.style.height = h;
            iframeEl.parentNode.insertBefore(div, iframeEl);
        }
        return div;
    }

    function setPlotSrc(iframeEl, divElOrNull, path) {
        const divEl = divElOrNull !== undefined ? divElOrNull : _getOrCreateSiblingDiv(iframeEl);
        if (!path) {
            if (divEl) { divEl.style.display = 'none'; divEl.innerHTML = ''; }
            if (iframeEl) { iframeEl.style.display = 'none'; iframeEl.src = ''; }
            return;
        }
        if (path.endsWith('.json') || path.endsWith('.json.gz')) {
            if (iframeEl) { iframeEl.style.display = 'none'; iframeEl.src = ''; }
            if (divEl) { divEl.style.display = ''; renderPlotFromJson(divEl, path); }
        } else {
            if (divEl) { divEl.style.display = 'none'; divEl.innerHTML = ''; }
            if (iframeEl) { iframeEl.style.display = ''; iframeEl.src = path; }
        }
    }

    function addHeadToHeadMeasurementTraces(traces, m, label, side) {
        const cs = side === 'left' ? 'Oranges' : 'Purples';
        const symbol = side === 'left' ? 'circle' : 'diamond';
        if (!m || m.mode === 'empty') {
            return;
        }
        if (m.mode === 'phases') {
            const coarseColor = 'rgba(176,176,176,0.9)';
            const secondaryColor = 'rgba(255,127,14,0.9)';
            const tertiaryColor = 'rgba(148,0,211,0.9)';
            if (m.coarse_x && m.coarse_x.length) {
                traces.push({
                    type: 'scatter',
                    x: m.coarse_x,
                    y: m.coarse_y,
                    mode: 'markers',
                    name: `${label} (coarse)`,
                    marker: {
                        size: 7,
                        color: coarseColor,
                        symbol: symbol,
                        line: { width: 0.6, color: '#4a4a4a' },
                    },
                    hovertemplate: 'x=%{x}<br>y=%{y:.4f}<br>phase=initial sweep<extra></extra>',
                });
            }
            if (m.secondary_x && m.secondary_x.length) {
                traces.push({
                    type: 'scatter',
                    x: m.secondary_x,
                    y: m.secondary_y,
                    mode: 'markers',
                    name: `${label} (secondary)`,
                    marker: {
                        size: 7,
                        color: secondaryColor,
                        symbol: symbol,
                        line: { width: 0.6, color: '#8B4513' },
                    },
                    hovertemplate: 'x=%{x}<br>y=%{y:.4f}<br>phase=secondary sweep<extra></extra>',
                });
            }
            if (m.tertiary_x && m.tertiary_x.length) {
                traces.push({
                    type: 'scatter',
                    x: m.tertiary_x,
                    y: m.tertiary_y,
                    mode: 'markers',
                    name: `${label} (tertiary)`,
                    marker: {
                        size: 7,
                        color: tertiaryColor,
                        symbol: symbol,
                        line: { width: 0.6, color: '#4B0082' },
                    },
                    hovertemplate: 'x=%{x}<br>y=%{y:.4f}<br>phase=tertiary sweep<extra></extra>',
                });
            }
            if (m.fine_x && m.fine_x.length) {
                const fineSteps =
                    Array.isArray(m.fine_step) && m.fine_step.length === m.fine_x.length
                        ? m.fine_step
                        : m.fine_x.map((_, i) => i);
                const maxStep = Math.max(1, fineSteps.length - 1);
                const finePct = fineSteps.map((s) => (s / maxStep) * 100.0);
                traces.push({
                    type: 'scatter',
                    x: m.fine_x,
                    y: m.fine_y,
                    mode: 'markers',
                    name: `${label} (fine)`,
                    marker: {
                        size: 8,
                        color: fineSteps,
                        colorscale: cs,
                        showscale: false,
                        symbol: symbol,
                        line: { width: 0.5, color: '#222' },
                    },
                    customdata: finePct,
                    hovertemplate:
                        'x=%{x}<br>y=%{y:.4f}<br>inference step=%{marker.color}<br>inference progress=%{customdata:.1f}%<extra></extra>',
                });
            }
            return;
        }
        if (m.mode === 'steps') {
            traces.push({
                type: 'scatter',
                x: m.x,
                y: m.y,
                mode: 'markers',
                name: `${label} (measurements)`,
                marker: {
                    size: 8,
                    color: m.step,
                    colorscale: cs,
                    symbol: symbol,
                    line: { width: 0.5, color: '#222' },
                    showscale: false,
                },
            });
        }
    }

    function buildHeadToHeadFocusShapes(pdL, pdR) {
        const shapes = [];
        if (pdL.focus_window && pdL.focus_window.length === 2) {
            const x0 = pdL.focus_window[0];
            const x1 = pdL.focus_window[1];
            if (Number.isFinite(x0) && Number.isFinite(x1) && x1 > x0) {
                shapes.push({
                    type: 'rect',
                    xref: 'x',
                    yref: 'paper',
                    x0,
                    x1,
                    y0: 0,
                    y1: 1,
                    fillcolor: 'rgba(46, 204, 113, 0.12)',
                    line: { color: 'rgba(46, 204, 113, 0.45)', width: 1 },
                    layer: 'below',
                });
            }
        }
        if (pdR.focus_window && pdR.focus_window.length === 2) {
            const x0 = pdR.focus_window[0];
            const x1 = pdR.focus_window[1];
            if (Number.isFinite(x0) && Number.isFinite(x1) && x1 > x0) {
                shapes.push({
                    type: 'rect',
                    xref: 'x',
                    yref: 'paper',
                    x0,
                    x1,
                    y0: 0,
                    y1: 1,
                    fillcolor: 'rgba(59, 130, 246, 0.1)',
                    line: { color: 'rgba(59, 130, 246, 0.45)', width: 1, dash: 'dot' },
                    layer: 'below',
                });
            }
        }
        return shapes;
    }

    function buildHeadToHeadTraces(pdL, pdR, nameL, nameR) {
        const traces = [];
        traces.push({
            type: 'scatter',
            x: pdL.x_dense,
            y: pdL.y_dense,
            mode: 'lines',
            name: 'true signal',
            line: { color: '#2563eb', width: 2 },
        });
        if (
            pdL.y_dense_noisy_lo &&
            pdL.y_dense_noisy_lo.length &&
            pdL.y_dense_noisy_lo.length === pdL.x_dense.length
        ) {
            if (
                pdL.y_dense_noisy_lo2 &&
                pdL.y_dense_noisy_lo2.length === pdL.x_dense.length
            ) {
                traces.push({
                    type: 'scatter', x: pdL.x_dense, y: pdL.y_dense_noisy_lo2, mode: 'lines',
                    line: { width: 0, color: 'rgba(100,100,100,0)' },
                    showlegend: false, hoverinfo: 'skip',
                });
                traces.push({
                    type: 'scatter', x: pdL.x_dense, y: pdL.y_dense_noisy_hi2, mode: 'lines',
                    name: 'possible measurement range (±2σ)',
                    line: { width: 0, color: 'rgba(100,100,100,0)' },
                    fill: 'tonexty', fillcolor: 'rgba(100,100,100,0.15)',
                });
            }
            traces.push({
                type: 'scatter', x: pdL.x_dense, y: pdL.y_dense_noisy_lo, mode: 'lines',
                line: { width: 0, color: 'rgba(100,100,100,0)' },
                showlegend: false, hoverinfo: 'skip',
            });
            traces.push({
                type: 'scatter', x: pdL.x_dense, y: pdL.y_dense_noisy_hi, mode: 'lines',
                name: 'possible measurement range (±1σ)',
                line: { width: 0, color: 'rgba(100,100,100,0)' },
                fill: 'tonexty', fillcolor: 'rgba(100,100,100,0.30)',
            });
        } else if (
            pdL.y_dense_noisy &&
            pdL.y_dense_noisy.length &&
            pdL.y_dense_noisy.length === pdL.x_dense.length
        ) {
            traces.push({
                type: 'scatter',
                x: pdL.x_dense,
                y: pdL.y_dense_noisy,
                mode: 'lines',
                name: 'simulated noisy signal (over-frequency)',
                line: { color: '#fb923c', dash: 'dot', width: 1.5 },
            });
        }
        if (
            pdL.y_dense_mode &&
            pdL.y_dense_mode.length &&
            pdL.y_dense_mode.length === pdL.x_dense.length
        ) {
            traces.push({
                type: 'scatter',
                x: pdL.x_dense,
                y: pdL.y_dense_mode,
                mode: 'lines',
                name: nameL + ' (most likely)',
                line: { color: '#dc2626', dash: 'dash', width: 2 },
            });
        }
        if (
            pdR.y_dense_mode &&
            pdR.y_dense_mode.length &&
            pdR.y_dense_mode.length === pdR.x_dense.length
        ) {
            traces.push({
                type: 'scatter',
                x: pdR.x_dense,
                y: pdR.y_dense_mode,
                mode: 'lines',
                name: nameR + ' (most likely)',
                line: { color: '#9333ea', dash: 'dash', width: 2 },
            });
        }
        addHeadToHeadMeasurementTraces(traces, pdL.measurements, nameL, 'left');
        addHeadToHeadMeasurementTraces(traces, pdR.measurements, nameR, 'right');
        return traces;
    }

    function controlValue(control) {
        if (control instanceof HTMLSelectElement) {
            return control.value || control.dataset.value || '';
        }
        return control.dataset.value ?? '';
    }

    function setControlValue(control, value, { silent = false } = {}) {
        const normalized = value ?? '';
        control.dataset.value = normalized;
        const buttons = control.querySelectorAll('button');
        for (const button of buttons) {
            const isActive = button.dataset.value === normalized;
            button.classList.toggle('is-active', isActive);
            button.setAttribute('aria-checked', String(isActive));
            button.tabIndex = isActive ? 0 : -1;
        }
        if (!silent) {
            control.dispatchEvent(
                new CustomEvent('controlchange', {
                    bubbles: false,
                    detail: { value: normalized },
                }),
            );
        }
    }

    // Reflects the current generator/noise/strategy/repeat selection plus the
    // active scan-view-mode and Bayesian sub-tab into the URL hash. Called from
    // the few places that are the actual source of truth for each piece of
    // state (findAndDisplayPlot, showScanViewPanels, the bayes-tab click
    // handler) rather than from every individual control listener.
    function syncHashFromState() {
        const viewBtn = document.querySelector('#scan-view-mode button.is-active');
        const bayesBtn = document.querySelector('#bayes-tab-bar .bayes-tab-button.is-active');
        writeHashState({
            generator: controlValue(scanGenerator) || null,
            noise: getEffectiveScanNoise() || null,
            strategy: controlValue(scanStrategy) || null,
            repeat: controlValue(scanRepeat) || null,
            view: viewBtn ? viewBtn.dataset.value : null,
            bayesTab: bayesBtn ? bayesBtn.dataset.tab : null,
        });
    }

    // ── Collapsible UI Sections ───────────────────────────────────────────────
    const COLLAPSE_ARROW_SVG =
        '<svg class="section-collapse-arrow" width="10" height="10" viewBox="0 0 16 16" fill="currentColor">' +
            '<path d="M4 6 L8 10 L12 6 Z"/>' +
        '</svg>';

    const collapsedSectionState = {};

    function isSectionCollapsed(sectionId, defaultCollapsed = false) {
        if (collapsedSectionState[sectionId] !== undefined) {
            return collapsedSectionState[sectionId];
        }
        try {
            const stored = localStorage.getItem('nvision_collapsed_' + sectionId);
            if (stored !== null) {
                const val = stored === 'true';
                collapsedSectionState[sectionId] = val;
                return val;
            }
        } catch (_) {}
        return defaultCollapsed;
    }

    function setSectionCollapsed(sectionId, isCollapsed) {
        collapsedSectionState[sectionId] = isCollapsed;
        try {
            localStorage.setItem('nvision_collapsed_' + sectionId, String(isCollapsed));
        } catch (_) {}
    }

    function toggleCollapsibleSection(sectionId, headerEl, contentEl) {
        const currentlyCollapsed = contentEl.style.display === 'none' || headerEl.classList.contains('is-collapsed');
        const willCollapse = !currentlyCollapsed;
        setSectionCollapsed(sectionId, willCollapse);
        if (willCollapse) {
            headerEl.classList.add('is-collapsed');
            headerEl.setAttribute('aria-expanded', 'false');
            headerEl.setAttribute('title', 'Click to expand');
            contentEl.style.display = 'none';
        } else {
            headerEl.classList.remove('is-collapsed');
            headerEl.setAttribute('aria-expanded', 'true');
            headerEl.setAttribute('title', 'Click to collapse');
            contentEl.style.display = '';
        }
    }

    function renderCollapsibleSectionHtml(sectionId, title, contentHtml, extraHeaderStyle = '') {
        const isCollapsed = isSectionCollapsed(sectionId);
        return `<div class="section-collapsible-wrapper" data-section-id="${escapeHtml(sectionId)}">` +
            `<div class="section-collapsible-header${isCollapsed ? ' is-collapsed' : ''}" role="button" tabindex="0" aria-expanded="${!isCollapsed}" data-section-id="${escapeHtml(sectionId)}" title="${isCollapsed ? 'Click to expand' : 'Click to collapse'}" style="margin-bottom:0.4em;font-weight:600;color:#334155;font-size:0.85em;${extraHeaderStyle}">` +
                `<span class="section-collapse-arrow" aria-hidden="true">${COLLAPSE_ARROW_SVG}</span>` +
                `<span>${escapeHtml(title)}</span>` +
            `</div>` +
            `<div class="section-collapsible-content"${isCollapsed ? ' style="display:none;"' : ''}>` +
                contentHtml +
            `</div>` +
        `</div>`;
    }

    function attachCollapsibleSectionListeners(container) {
        if (!container) return;
        const headers = container.querySelectorAll('.section-collapsible-header');
        headers.forEach((header) => {
            const sectionId = header.dataset.sectionId;
            if (!sectionId) return;
            const wrapper = header.closest('.section-collapsible-wrapper');
            const content = wrapper
                ? wrapper.querySelector('.section-collapsible-content')
                : header.nextElementSibling;
            if (!content) return;

            const toggle = () => toggleCollapsibleSection(sectionId, header, content);
            header.addEventListener('click', toggle);
            header.addEventListener('keydown', (e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    toggle();
                }
            });
        });
    }

    function renderSegmentedControl(control, items, previousValue, options = {}) {
        const disabledItems = options.disabledItems instanceof Set
            ? options.disabledItems
            : new Set(options.disabledItems || []);
        const uniqueItems = [
            ...new Set(
                items.filter((item) => item !== undefined && item !== null)
            ),
        ]
            .map((item) => String(item))
            .sort((a, b) => a.localeCompare(b));

        control.innerHTML = '';

        for (const item of uniqueItems) {
            const button = document.createElement('button');
            button.type = 'button';
            button.dataset.value = item;
            button.setAttribute('role', 'radio');
            button.setAttribute('aria-checked', 'false');
            button.tabIndex = -1;
            button.textContent = item;
            if (disabledItems.has(item)) {
                button.disabled = true;
                button.title = 'No scan data yet. Run this strategy with nvision run, then render.';
            }
            button.addEventListener('click', () => {
                if (button.disabled) {
                    return;
                }
                setControlValue(control, item);
            });
            button.addEventListener('keydown', (e) => {
                const buttons = Array.from(control.querySelectorAll('button'));
                const index = buttons.indexOf(button);
                let nextIndex = null;
                if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
                    nextIndex = (index + 1) % buttons.length;
                } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
                    nextIndex = (index - 1 + buttons.length) % buttons.length;
                }
                if (nextIndex !== null) {
                    e.preventDefault();
                    buttons[nextIndex].focus();
                    buttons[nextIndex].click();
                }
            });
            control.appendChild(button);
        }

        let nextValue = '';
        const enabledItems = uniqueItems.filter((item) => !disabledItems.has(item));
        if (enabledItems.length > 0) {
            if (previousValue && enabledItems.includes(previousValue)) {
                nextValue = previousValue;
            } else if (previousValue && uniqueItems.includes(previousValue)) {
                nextValue = enabledItems[0];
            } else {
                nextValue = enabledItems[0];
            }
        }

        setControlValue(control, nextValue, { silent: true });
        return nextValue;
    }

    function renderSelectControl(select, items, previousValue) {
        const uniqueItems = [
            ...new Set(items.filter((item) => item !== undefined && item !== null)),
        ]
            .map((item) => String(item))
            .sort((a, b) => Number(a) - Number(b));

        let nextValue = '';
        if (uniqueItems.length > 0) {
            if (previousValue && uniqueItems.includes(previousValue)) {
                nextValue = previousValue;
            } else {
                nextValue = uniqueItems[0];
            }
        }

        select.innerHTML = '';
        for (const item of uniqueItems) {
            const option = document.createElement('option');
            option.value = item;
            option.textContent = item;
            select.appendChild(option);
        }

        if (nextValue) {
            select.value = nextValue;
        } else {
            select.value = '';
        }
        select.dataset.value = nextValue;
        select.dataset.options = JSON.stringify(uniqueItems);
        return { value: nextValue, items: uniqueItems };
    }

    // Look up the swept axes for a generator produced by a parameter-grid study, so
    // the UI can offer one dropdown per axis instead of a flat list of opaque
    // generator names. Returns null for non-grid generators (e.g. bare
    // "NVCenter-lorentzian", or a MATLAB generator -- neither has grid_* metrics).
    // Backed by /api/generator-grid-info (one cheap repeat-0 read per distinct
    // generator, fetched once by bootstrap.js into window.NVISION_GENERATOR_GRID_INFO),
    // not by parsing the generator name string -- a generator's swept-parameter
    // values are data recorded at run time (nvision/runner/metrics.py), and the name
    // is just a human-readable label for them, not the other way around.
    function parseGeneratorFacets(name) {
        const info = window.NVISION_GENERATOR_GRID_INFO && window.NVISION_GENERATOR_GRID_INFO[name];
        return window.nvisionGeneratorAxes(info);
    }

    // Real-measurement generators from `nv matlab-run` (see matlab_cmd.py), named
    // "MATLAB:<filename>". They carry no swept numeric axes to facet on, so they get
    // their own flat "study" bucket (see groupGeneratorsByFamily) instead of either
    // pretending to be a parameter-grid family or falling into "Default (ungrouped)"
    // alongside unrelated plain/bare generators.
    function isMatlabGenerator(name) {
        return typeof name === 'string' && name.startsWith('MATLAB:');
    }

    // Group generator names into parameter-study "families" (same variant + same
    // swept axes), a "matlab" bucket for real-measurement generators, and an
    // "__ungrouped__" bucket for anything else that doesn't parse (e.g. bare default
    // generators from a plain, non-grid run).
    function groupGeneratorsByFamily(items) {
        const families = new Map();
        const ungrouped = [];
        const matlab = [];
        for (const name of items) {
            if (isMatlabGenerator(name)) {
                matlab.push(name);
                continue;
            }
            const parsed = parseGeneratorFacets(name);
            if (!parsed) {
                ungrouped.push(name);
                continue;
            }
            if (!families.has(parsed.family)) {
                families.set(parsed.family, { label: parsed.familyLabel, axes: parsed.axes.map((a) => a.key), members: [] });
            }
            families.get(parsed.family).members.push({ name, axisValues: parsed.axes });
        }
        return { families, ungrouped, matlab };
    }

    function axisDisplayValue(v) {
        // Most axes (width, contrast, sigma_inhom, ...) are numeric; isotope
        // (hyperfine) is categorical ("unresolved"/"n14"/"n15") and passes
        // through as-is -- Number.isInteger(v) is false for a string, so this
        // must be checked before the numeric formatting below runs .toFixed on it.
        if (typeof v === 'string') return v;
        return Number.isInteger(v) ? String(v) : String(Number(v.toFixed(4)));
    }

    // Comparator for sorting an axis's raw or display values: numeric axes sort
    // by magnitude, the categorical isotope axis (and anything else non-numeric)
    // sorts alphabetically instead of via NaN-producing subtraction.
    function axisValueCompare(a, b) {
        const na = Number(a);
        const nb = Number(b);
        if (!Number.isNaN(na) && !Number.isNaN(nb)) return na - nb;
        return String(a).localeCompare(String(b));
    }

    // Per-family, per-axis selected values (as axisDisplayValue strings), keyed by
    // family key so a multi-selection survives the full facet re-render that
    // every axis change triggers (via scanGenerator's 'controlchange' -->
    // updateAllScanControls --> updateScanSignalControls --> this function again).
    // Without this store, that re-render would reseed each axis from the single
    // primary generator and silently collapse any multi-selection back to one.
    const facetSelectionStore = new Map();

    // Render one multi-select button group per axis for the given family (same
    // click/range UX as the noise selector), wired so that any axis's selection
    // recomputes the set of matching generator names. The primary (first) match
    // is pushed into the existing #scan-generator control (dataset.value +
    // 'controlchange') so single-generator consumers of controlValue(scanGenerator)
    // keep working unchanged; the full match set is exposed via
    // getSelectedScanGenerators() for consumers that compare across values.
    function renderGeneratorFacetSelects(familyGroup, previousGeneratorName, familyKey) {
        const axisMeta = familyGroup.members[0].axisValues.map((a) => ({ key: a.key, label: a.label }));
        if (!facetSelectionStore.has(familyKey)) facetSelectionStore.set(familyKey, {});
        const store = facetSelectionStore.get(familyKey);
        const prevMember = familyGroup.members.find((m) => m.name === previousGeneratorName);

        function computeMatches() {
            return familyGroup.members.filter((m) =>
                axisMeta.every((meta) => {
                    const sel = store[meta.key];
                    if (!sel || sel.size === 0) return false;
                    return sel.has(axisDisplayValue(m.axisValues.find((a) => a.key === meta.key).value));
                }),
            );
        }

        function applySelection(options = {}) {
            const matches = computeMatches();
            const effective = matches.length ? matches : [familyGroup.members[0]];
            scanGeneratorFacets.dataset.selectedGenerators = JSON.stringify(effective.map((m) => m.name));
            setControlValue(scanGenerator, effective[0].name, options);
        }

        scanGeneratorFacets.innerHTML = '';
        // An axis with one value in the family has nothing to choose (the SNR study fixes the linewidth and the
        // contrast): it is listed as fixed instead of offering a one-button picker. When no axis varies, all stay.
        const valuesOf = (meta) =>
            [...new Set(familyGroup.members.map((m) => m.axisValues.find((a) => a.key === meta.key).value))];
        const anyVaries = axisMeta.some((meta) => valuesOf(meta).length > 1);
        const fixedNotes = [];
        for (const meta of axisMeta) {
            if (anyVaries && valuesOf(meta).length === 1) {
                const [only] = valuesOf(meta);
                store[meta.key] = new Set([axisDisplayValue(only)]);
                fixedNotes.push(`${meta.label}${paramLetterSuffix(meta.key)} ${axisDisplayValue(only)}`);
                continue;
            }
            const wrapper = document.createElement('span');
            wrapper.className = 'facet-select-wrapper';
            const label = document.createElement('label');
            label.textContent = `${meta.label}${paramLetterSuffix(meta.key)}: `;
            label.className = 'facet-select-label';

            const values = [...new Set(familyGroup.members.map((m) => m.axisValues.find((a) => a.key === meta.key).value))]
                .sort(axisValueCompare)
                .map(axisDisplayValue);

            let seed = store[meta.key] ? [...store[meta.key]].filter((v) => values.includes(v)) : [];
            if (!seed.length) {
                const prevAxis = prevMember && axisDisplayValue(prevMember.axisValues.find((a) => a.key === meta.key).value);
                seed = prevAxis && values.includes(prevAxis) ? [prevAxis] : [values[0]];
            }

            const btnGroup = document.createElement('span');
            btnGroup.setAttribute('aria-label', meta.label);
            renderMultiSelectButtonControl(btnGroup, values, seed, axisValueCompare);
            store[meta.key] = new Set(JSON.parse(btnGroup.dataset.selectedValues || '[]'));

            btnGroup.addEventListener('controlchange', () => {
                store[meta.key] = new Set(JSON.parse(btnGroup.dataset.selectedValues || '[]'));
                // Apply silently -- setting scanGenerator's value with a dispatched
                // 'controlchange' would trigger updateAllScanControls(), which calls
                // this function again and rebuilds every axis's buttons (a fresh
                // control has no _rangeAnchor), wiping the anchor before a second
                // click can complete a range gesture. Instead, run only the narrower
                // refresh (noise items + downstream controls) that a facet change
                // actually needs; the full facet rebuild is reserved for family
                // switches and other paths that go through scanGenerator directly.
                applySelection({ silent: true });
                const nextGen = controlValue(scanGenerator);
                if (!isGeneratorRangeMode() && nextGen && window.nvisionNeedsWiderLoad && window.nvisionNeedsWiderLoad(nextGen)) {
                    refreshScanNoiseControlForSelectedGenerators();
                    updateNoiseViewMode();
                    updateScanStrategyControl();
                    updateScanRepeatControl();
                    syncHashFromState();
                    window.nvisionNavigateToGenerator(nextGen);
                    return;
                }
                lastComparePairIds = { a: null, b: null };
                lastSummaryKey = null;
                refreshScanNoiseControlForSelectedGenerators();
                updateNoiseViewMode();
                updateScanStrategyControl();
                updateScanRepeatControl();
                findAndDisplayPlot();
            });

            label.appendChild(btnGroup);
            wrapper.appendChild(label);
            scanGeneratorFacets.appendChild(wrapper);
        }
        if (fixedNotes.length) {
            const note = document.createElement('span');
            note.className = 'facet-fixed-note';
            note.textContent = `fixed: ${fixedNotes.join(' · ')}`;
            scanGeneratorFacets.appendChild(note);
        }

        // Initial render: set state without dispatching 'controlchange' (mirrors
        // renderSegmentedControl's own silent initial setControlValue) -- avoids a
        // reentrant updateScanSignalControls() call on every render, not just on
        // user-driven changes.
        applySelection({ silent: true });
    }

    function updateRepeatNavButtons() {
        if (!scanRepeatPrev || !scanRepeatNext) {
            return;
        }
        if (currentRepeatItems.length === 0) {
            scanRepeatPrev.disabled = true;
            scanRepeatNext.disabled = true;
            return;
        }
        const currentValue = scanRepeat.value || currentRepeatItems[0] || '';
        const currentIndex = currentRepeatItems.indexOf(currentValue);
        const hasValidSelection = currentIndex !== -1;
        scanRepeatPrev.disabled = !hasValidSelection || currentIndex <= 0;
        scanRepeatNext.disabled = !hasValidSelection || currentIndex >= currentRepeatItems.length - 1;
    }

    function selectRepeatByIndex(index) {
        if (currentRepeatItems.length === 0) {
            return;
        }
        const clampedIndex = Math.max(0, Math.min(index, currentRepeatItems.length - 1));
        const nextValue = currentRepeatItems[clampedIndex];
        if (nextValue === undefined) {
            return;
        }
        scanRepeat.value = nextValue;
        scanRepeat.dataset.value = nextValue;
        updateRepeatNavButtons();
        findAndDisplayPlot();
    }

    function selectRepeatByOffset(offset) {
        if (currentRepeatItems.length === 0) {
            return;
        }
        const currentValue = scanRepeat.value || currentRepeatItems[0];
        let currentIndex = currentRepeatItems.indexOf(currentValue);
        if (currentIndex === -1) {
            currentIndex = 0;
        }
        const targetIndex = currentIndex + offset;
        if (targetIndex < 0 || targetIndex >= currentRepeatItems.length) {
            return;
        }
        selectRepeatByIndex(targetIndex);
    }

    // ── Noise range-select control ────────────────────────────────────────────
    // Click 1: sets the anchor (single selection, darker highlight).
    // Click 2 on a different button: selects the full range from anchor to here.
    // Hovering while an anchor is set previews the range.

    function _getNoiseSelectedSet(control) {
        try { return new Set(JSON.parse(control.dataset.selectedValues || '[]')); }
        catch { return new Set(); }
    }

    function _setNoiseSelected(control, values, { silent = false } = {}) {
        const valSet = new Set(values);
        control.dataset.selectedValues = JSON.stringify([...valSet]);
        for (const btn of control.querySelectorAll('button')) {
            const sel = valSet.has(btn.dataset.value);
            btn.classList.toggle('is-active', sel);
            btn.setAttribute('aria-checked', String(sel));
        }
        if (!silent) {
            control.dispatchEvent(new CustomEvent('controlchange', {
                bubbles: false, detail: { values: [...valSet] },
            }));
        }
    }

    // The shared contrast_total of the selected generators, when they all record one: an older Gauss(sigma) run of
    // a fixed contrast is then labelled by its SNR = contrast / sigma too.
    function selectedSharedContrast() {
        const info = window.NVISION_GENERATOR_GRID_INFO || {};
        const contrasts = getSelectedScanGenerators().map((g) => info[g] && info[g].grid_contrast_total);
        if (!contrasts.length || contrasts.some((c) => c == null)) return null;
        return new Set(contrasts).size === 1 ? contrasts[0] : null;
    }

    // The noise buttons: one per SNR for the SNR studies (`SNR(x)` names), ascending, the name as the tooltip; an
    // older `Gauss(sigma)` name keeps its sigma order unless the selected signals share a contrast (then SNR order).
    function renderMultiSelectNoiseControl(control, items, previousValues) {
        const snrOf = (name) => {
            const m = name.match(/^SNR\(([\d.e+-]+)\)/);
            return m ? parseFloat(m[1]) : null;
        };
        const sigmaOf = (name) => {
            const m = name.match(/Gauss\(([\d.]+)\)/);
            return m ? parseFloat(m[1]) : null;
        };
        const contrast = selectedSharedContrast();
        const bySigma = (a, b) => {
            const na = snrOf(a);
            const nb = snrOf(b);
            if (na != null && nb != null) return na - nb;
            const sa = sigmaOf(a);
            const sb = sigmaOf(b);
            if (sa != null && sb != null) return contrast != null ? sb - sa : sa - sb;
            if (sa != null || na != null) return -1;
            if (sb != null || nb != null) return 1;
            return a.localeCompare(b);
        };
        const label = (name) => window.nvisionNoiseSnrLabel(name, contrast) || name;
        return renderMultiSelectButtonControl(control, items, previousValues, bySigma, label);
    }

    // Generic multi-select button group. Plain click (or keyboard Enter/Space)
    // selects a single item, replacing the prior selection. Press-and-drag from
    // one button to another selects the contiguous range between them, previewed
    // live as the drag crosses buttons. `sortFn` orders the buttons left-to-right;
    // pass a numeric comparator when items are numeric strings so range-select is
    // contiguous in value order. `labelFn(item)` (optional) gives the button text; the item itself stays the
    // value and the tooltip.
    function renderMultiSelectButtonControl(control, items, previousValues, sortFn, labelFn = null) {
        const prev = Array.isArray(previousValues) ? previousValues : (previousValues ? [previousValues] : []);
        const uniqueItems = [...new Set(items.filter(Boolean).map(String))].sort(sortFn);

        control.innerHTML = '';
        control.setAttribute('role', 'group');
        control._dragAnchor = null;
        control._dragCurrent = null;
        control._dragMoved = false;
        control._justDragged = false;

        const commitDrag = () => {
            if (!control._dragAnchor) return;
            const allBtns = [...control.querySelectorAll('button')];
            allBtns.forEach(b => b.classList.remove('is-range-preview', 'is-range-anchor'));
            if (control._dragMoved) {
                const ai = allBtns.findIndex(b => b.dataset.value === control._dragAnchor);
                const bi = allBtns.findIndex(b => b.dataset.value === control._dragCurrent);
                const lo = Math.min(ai, bi), hi = Math.max(ai, bi);
                const range = allBtns.slice(lo, hi + 1).map(b => b.dataset.value);
                control._justDragged = true;
                _setNoiseSelected(control, range);
            }
            control._dragAnchor = null;
            control._dragCurrent = null;
            control._dragMoved = false;
        };

        // Bound once per control element (survives re-renders that only replace
        // the buttons), so a drag released outside any button still commits.
        if (!control._dragCommitBound) {
            control._dragCommitBound = true;
            document.addEventListener('mouseup', commitDrag);
        }

        for (const item of uniqueItems) {
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.dataset.value = item;
            btn.setAttribute('role', 'checkbox');
            btn.setAttribute('aria-checked', 'false');
            btn.tabIndex = 0;
            btn.textContent = labelFn ? labelFn(item) : item;
            if (labelFn) btn.title = item;
            btn.className = 'noise-btn';

            btn.addEventListener('mousedown', (e) => {
                e.preventDefault(); // avoid text-selection while dragging
                control._dragAnchor = item;
                control._dragCurrent = item;
                control._dragMoved = false;
                btn.classList.add('is-range-anchor');
            });

            btn.addEventListener('mouseenter', () => {
                if (!control._dragAnchor) return;
                control._dragCurrent = item;
                control._dragMoved = item !== control._dragAnchor;
                const allBtns = [...control.querySelectorAll('button')];
                const ai = allBtns.findIndex(b => b.dataset.value === control._dragAnchor);
                const bi = allBtns.findIndex(b => b.dataset.value === item);
                const lo = Math.min(ai, bi), hi = Math.max(ai, bi);
                allBtns.forEach((b, i) =>
                    b.classList.toggle('is-range-preview', i >= lo && i <= hi && !b.classList.contains('is-range-anchor'))
                );
            });

            btn.addEventListener('click', () => {
                // A completed drag already committed via the document mouseup
                // handler above; this plain click (mouse, or keyboard Enter/Space
                // which never fires mousedown/mouseenter) selects one item.
                if (control._justDragged) {
                    control._justDragged = false;
                    return;
                }
                const allBtns = [...control.querySelectorAll('button')];
                allBtns.forEach(b => b.classList.remove('is-range-preview', 'is-range-anchor'));
                _setNoiseSelected(control, [item]);
            });

            control.appendChild(btn);
        }

        // Restore previous selection; keep valid items; fallback to first
        let nextValues = prev.filter(v => uniqueItems.includes(v));
        if (nextValues.length === 0 && uniqueItems.length > 0) nextValues = [uniqueItems[0]];
        _setNoiseSelected(control, nextValues, { silent: true });
        return nextValues;
    }

    function getSelectedScanNoises() {
        try { return JSON.parse(scanNoise.dataset.selectedValues || '[]').filter(Boolean); }
        catch { return []; }
    }

    function getEffectiveScanNoise() {
        const noises = getSelectedScanNoises();
        return noises[0] || '';
    }

    function isNoiseRangeMode() {
        return getSelectedScanNoises().length > 1;
    }

    // getSelectedScanGenerators: the full set of generators matched by the
    // Width/Contrast (or other parameter-grid axis) multi-select buttons.
    // Falls back to the single #scan-generator value for plain/ungrouped
    // generators, where there is no facet control.
    function getSelectedScanGenerators() {
        try {
            const stored = JSON.parse(scanGeneratorFacets.dataset.selectedGenerators || '[]');
            if (stored.length) return stored;
        } catch { /* fall through to single-value fallback */ }
        const v = controlValue(scanGenerator);
        return v ? [v] : [];
    }

    function isGeneratorRangeMode() {
        return getSelectedScanGenerators().length > 1;
    }

    // Generator argument the aggregate renderers (Stages/Accuracy/Failed Runs)
    // expect: an array in generator-range mode, otherwise the single value.
    function compareGeneratorsArg() {
        const gens = getSelectedScanGenerators();
        return gens.length > 1 ? gens : (gens[0] || '');
    }

    function updateNoiseViewMode() {
        const range = isNoiseRangeMode() || isGeneratorRangeMode();
        const singleBtn = document.getElementById('scan-view-single-btn');
        if (singleBtn) singleBtn.style.display = range ? 'none' : '';

        if (range) {
            const activeBtn = document.querySelector('#scan-view-mode button.is-active');
            if (activeBtn && activeBtn.dataset.value === 'single') {
                const stagesBtn = document.querySelector('#scan-view-mode button[data-value="stages"]');
                if (stagesBtn) stagesBtn.click();
            }
        }
    }

    /** Left column: generator, noise (signal / experiment path).
     *
     * Parameter-grid studies (see sim/presets.py's saturation_voigt_param_grid_generators
     * / param_grid_generators) produce many generator names that only differ by their
     * swept-parameter values (e.g. "NVCenter-saturation_voigt-s5.00-si0.30MHz"). Scrolling
     * a flat list of ~25 such names is hard to navigate, so when the manifest contains a
     * parseable grid we offer one dropdown per swept axis instead. Falls back to the
     * original flat segmented-control for plain (non-grid) generators, and adds a "Study"
     * dropdown when both grid and non-grid generators are present in the same manifest
     * (e.g. an artifacts directory accumulated across multiple run types).
     */
    // forcedFamilyKey: when the user just changed the family <select> itself, its new
    // value must win over the family re-derived from the (not-yet-updated) previously
    // selected generator -- otherwise this same function's own re-render, triggered by
    // its onchange handler, would immediately revert the dropdown to the old family.
    function updateScanSignalControls(forcedFamilyKey = null) {
        // window.NVISION_ALL_GENERATORS (set by bootstrap.js from the cheap /api/combos
        // index) covers every generator in the cache, even ones whose data isn't loaded
        // into `plots` yet — bootstrap.js only fetches the initially-selected generator's
        // parameter-study family to keep page load fast on a large shared cache. Falls
        // back to scanPlots' own generators for the static-export path, where the whole
        // manifest is always loaded and this global is never set.
        const scanGeneratorItems = Array.isArray(window.NVISION_ALL_GENERATORS) && window.NVISION_ALL_GENERATORS.length
            ? window.NVISION_ALL_GENERATORS
            : [...new Set(scanPlots.map((p) => p.generator))].sort();
        const { families, ungrouped, matlab } = groupGeneratorsByFamily(scanGeneratorItems);
        const familyKeys = [...families.keys()];
        const previousGenerator = controlValue(scanGenerator);

        let selectedScanGenerator;

        if (familyKeys.length === 0 && matlab.length === 0) {
            // No parseable grid families and no MATLAB generators: original flat list.
            scanGeneratorFlatRow.style.display = '';
            scanGeneratorFamilyRow.style.display = 'none';
            scanGeneratorFacetsRow.style.display = 'none';
            scanGeneratorFacets.dataset.selectedGenerators = '[]';
            selectedScanGenerator = renderSegmentedControl(scanGenerator, scanGeneratorItems, previousGenerator);
        } else {
            const familyOptions = [
                ...familyKeys.map((key) => ({ key, label: families.get(key).label })),
                ...(matlab.length > 0 ? [{ key: '__matlab__', label: 'MATLAB (real data)' }] : []),
                ...(ungrouped.length > 0 ? [{ key: '__ungrouped__', label: 'Default (ungrouped)' }] : []),
            ];
            const needsFamilyPicker = familyOptions.length > 1;

            scanGeneratorFlatRow.style.display = 'none';
            scanGeneratorFamilyRow.style.display = needsFamilyPicker ? '' : 'none';

            let selectedFamilyKey;
            if (needsFamilyPicker) {
                const prevParsed = parseGeneratorFacets(previousGenerator);
                const prevFamilyKey = prevParsed
                    ? prevParsed.family
                    : isMatlabGenerator(previousGenerator)
                        ? '__matlab__'
                        : (ungrouped.includes(previousGenerator) ? '__ungrouped__' : null);
                scanGeneratorFamily.innerHTML = '';
                for (const opt of familyOptions) {
                    const option = document.createElement('option');
                    option.value = opt.key;
                    option.textContent = opt.label;
                    scanGeneratorFamily.appendChild(option);
                }
                const candidateKey = forcedFamilyKey ?? prevFamilyKey;
                selectedFamilyKey = candidateKey && familyOptions.some((o) => o.key === candidateKey)
                    ? candidateKey
                    : familyOptions[0].key;
                scanGeneratorFamily.value = selectedFamilyKey;
                scanGeneratorFamily.onchange = () => {
                    updateScanSignalControls(scanGeneratorFamily.value);
                    updateScanStrategyControl();
                    updateScanRepeatControl();
                    findAndDisplayPlot();
                };
            } else {
                selectedFamilyKey = familyOptions[0].key;
            }

            if (selectedFamilyKey === '__ungrouped__') {
                scanGeneratorFacetsRow.style.display = 'none';
                scanGeneratorFlatRow.style.display = '';
                scanGeneratorFacets.dataset.selectedGenerators = '[]';
                selectedScanGenerator = renderSegmentedControl(scanGenerator, ungrouped, previousGenerator);
            } else if (selectedFamilyKey === '__matlab__') {
                scanGeneratorFacetsRow.style.display = 'none';
                scanGeneratorFlatRow.style.display = '';
                scanGeneratorFacets.dataset.selectedGenerators = '[]';
                selectedScanGenerator = renderSegmentedControl(scanGenerator, matlab, previousGenerator);
            } else {
                scanGeneratorFacetsRow.style.display = '';
                // Only carry the previous generator's facet selections into the new
                // render when we're staying within the SAME family; switching families
                // should default to that family's first combination instead.
                const carryPrevious = !forcedFamilyKey || forcedFamilyKey === (parseGeneratorFacets(previousGenerator) || {}).family;
                renderGeneratorFacetSelects(families.get(selectedFamilyKey), carryPrevious ? previousGenerator : null, selectedFamilyKey);
                selectedScanGenerator = controlValue(scanGenerator);
            }
        }

        // The selection resolved to a generator whose data bootstrap.js never fetched
        // (it only loaded the initially-selected generator's family — see
        // updateScanSignalControls' scanGeneratorItems comment above). Reload scoped to
        // the new one instead of rendering from an empty/wrong scanPlots slice.
        if (selectedScanGenerator && window.nvisionNeedsWiderLoad && window.nvisionNeedsWiderLoad(selectedScanGenerator)) {
            window.nvisionNavigateToGenerator(selectedScanGenerator);
            return;
        }

        refreshScanNoiseControlForSelectedGenerators();
        updateSignalEquationPanel(selectedScanGenerator);
    }

    // Returns the signal-model equation (as HTML, using the PARAM_LETTERS symbols
    // from format-utils.js) matching the generator variant encoded in its name, or
    // null when the generator isn't a recognized NV-center model. Variant detection
    // is a simple substring match on the generator name (lorentzian / voigt /
    // saturation_voigt, plus a zeeman flag) — see nvision/sim/gen/nv_center_generator.py
    // for the authoritative variant switch these formulas are transcribed from
    // (numba_kernels.py / nv_center.py / voigt_zeeman.py).
    // Stacked numerator/denominator span for a "num/den" term, instead of an inline
    // slash — see .eq-frac in styles.css. Args are already-HTML-safe fragments
    // (built from escapeHtml'd param letters and literal symbols), not raw user text.
    function frac(num, den) {
        return `<span class="eq-frac"><span class="eq-num">${num}</span><span class="eq-den">${den}</span></span>`;
    }

    // Square brackets that stretch to the full height of their content (stacked
    // fractions included) instead of text "[ ]" glyphs — see .eq-brackets in styles.css.
    function bracket(inner) {
        return `<span class="eq-brackets">${inner}</span>`;
    }

    function getSignalEquationInfo(generatorName) {
        if (!generatorName) return null;
        const n = generatorName.toLowerCase();
        const L = (p) => escapeHtml(paramLetter(p) || p);

        let title, formula, params;
        if (n.includes('saturation_voigt')) {
            title = 'Saturation-Voigt dip';
            const g = 'γ', s = L('sigma_inhom');
            formula =
                `γ = γ₀·√(1+${L('saturation')}), &nbsp; ${L('contrast_total')} = ${L('c_max')}·${frac(L('saturation'), `1+${L('saturation')}`)} ` +
                `&nbsp; (γ₀, ${L('c_max')} fixed constants, not fitted)<br>` +
                `S(f) = 1 − hyperfine multiplet of V(f; ${g},${s},c) terms centered at ` +
                `${L('zero_field_freq')}±${L('hyperfine_shift')}, ${L('zero_field_freq')}`;
            params = ['saturation', 'sigma_inhom', 'zero_field_freq'];
        } else if (n.includes('voigt')) {
            title = 'Voigt NV dip';
            const g = L('hwhm_lorentz'), s = L('sigma_inhom');
            formula =
                `Σ = ${frac('1', L('k_np'))} + w + ${L('k_np')}<br>` +
                `S(f) = 1 − ${frac(L('contrast_total'), 'Σ')} · ` +
                bracket(
                    `${frac('1', L('k_np'))}·V(f; ${g},${s},${L('zero_field_freq')}−${L('hyperfine_shift')}) + w·V(f; ${g},${s},${L('zero_field_freq')}) ` +
                    `+ ${L('k_np')}·V(f; ${g},${s},${L('zero_field_freq')}+${L('hyperfine_shift')})`
                );
            params = ['zero_field_freq', 'hwhm_lorentz', 'sigma_inhom', 'hyperfine_shift', 'k_np', 'contrast_total'];
        } else if (n.includes('lorentzian')) {
            title = 'Lorentzian NV dip';
            formula =
                `f' = ${frac(`f−${L('zero_field_freq')}`, L('hwhm'))}, &nbsp; α = ${frac(L('hyperfine_shift'), L('hwhm'))}, ` +
                `&nbsp; Σ = ${frac('1', L('k_np'))} + w + ${L('k_np')}<br>` +
                `S(f) = 1 − ${frac(L('contrast_total'), 'Σ')} · ` +
                bracket(
                    `${frac('1', `${L('k_np')}·((f'+α)²+1)`)} + ${frac('w', "f'²+1")} + ${frac(L('k_np'), "(f'−α)²+1")}`
                );
            params = ['zero_field_freq', 'hwhm', 'hyperfine_shift', 'k_np', 'contrast_total'];
        } else {
            return null;
        }

        // w is the centre-line weight that selects the nitrogen hyperfine structure.
        // It is a model setting, not a fitted parameter, so it is explained rather
        // than listed among the parameters below. Laid out as a label + bullet list
        // (not one run-on sentence) so it can be scanned instead of read word-by-word.
        let hyperfineNote = '';
        if (n.includes('lorentzian') || n.includes('voigt')) {
            hyperfineNote = `<div class="signal-equation-note signal-eq-note-block">` +
                `<div class="signal-eq-note-label">w — centre-line weight, set by the nitrogen isotope (not fitted)</div>` +
                `<ul class="signal-eq-note-list">` +
                `<li><b>w = 1</b>: ¹⁴N triplet — 3 lines, ${L('hyperfine_shift')} apart</li>` +
                `<li><b>w = 0</b>: ¹⁵N doublet — 2 lines, no centre line</li>` +
                `<li><b>${L('hyperfine_shift')} = 0</b>: all lines merge into one dip of the same total contrast ` +
                `— the default, for hwhm values too large to resolve the hyperfine lines</li>` +
                `</ul></div>`;
        }

        // V's definition lives ONLY here -- the formula above just calls it, it
        // doesn't restate it, so there's exactly one place a reader needs to look.
        // Written as an actual equation (not a prose description) per feedback:
        // the pseudo-Voigt kernel approximates this convolution with a cheaper
        // weighted sum -- see sbed_and_smc.md Sec 7.2 for that implementation.
        let voigtNote = '';
        if (n.includes('voigt')) {
            voigtNote = `<div class="signal-equation-note signal-eq-note-block">` +
                `<div class="signal-eq-note-label">V(f; γ,σ,c) = (L<sub>γ</sub> ∗ G<sub>σ</sub>)(f−c)</div>` +
                `<ul class="signal-eq-note-list">` +
                `<li>γ: Lorentzian HWHM (hwhm_lorentz: T2 floor + power broadening) &nbsp;·&nbsp; ${L('sigma_inhom')}: inhomogeneous std (Gaussian)</li>` +
                `<li>γ ≫ σ: pure Lorentzian &nbsp;→&nbsp; σ ≫ γ: pure Gaussian</li>` +
                `</ul></div>`;
        }

        let zeemanNote = '';
        if (n.includes('zeeman')) {
            zeemanNote = `<div class="signal-equation-note">With Zeeman splitting: this pattern appears twice, ` +
                `centered at ${L('zero_field_freq')} − ${L('zeeman_shift')} and ${L('zero_field_freq')} + ${L('zeeman_shift')} ` +
                `(one hyperfine group each).</div>`;
            params = params.concat(['zeeman_shift']);
        }

        const paramsHtml = params.map((p) =>
            `<span class="signal-eq-param"><b>${L(p)}</b> = ${escapeHtml(p.replace(/_/g, ' '))}</span>`
        ).join('');

        return {
            title: title,
            formula: formula,
            hyperfineNote: hyperfineNote,
            voigtNote: voigtNote,
            zeemanNote: zeemanNote,
            paramsHtml: paramsHtml,
            html: `<div class="signal-equation-title">${escapeHtml(title)}</div>` +
                  `<div class="signal-equation-formula">${formula}</div>` +
                  hyperfineNote +
                  voigtNote +
                  zeemanNote +
                  `<div class="signal-equation-params">${paramsHtml}</div>`,
        };
    }

    function updateSignalEquationPanel(generatorName) {
        const el = document.getElementById('signal-equation-panel');
        if (!el) return;
        const info = getSignalEquationInfo(generatorName);
        if (!info) {
            el.style.display = 'none';
            el.innerHTML = '';
            return;
        }
        const sectionId = 'signal-equation';
        const isCollapsed = isSectionCollapsed(sectionId);
        el.className = 'signal-equation-panel' + (isCollapsed ? ' is-collapsed' : '');
        el.innerHTML =
            `<div class="signal-equation-header section-collapsible-header${isCollapsed ? ' is-collapsed' : ''}" role="button" tabindex="0" aria-expanded="${!isCollapsed}" data-section-id="${sectionId}" title="${isCollapsed ? 'Click to expand' : 'Click to collapse'}">` +
                `<span class="section-collapse-arrow" aria-hidden="true">${COLLAPSE_ARROW_SVG}</span>` +
                `<span class="signal-equation-title">${escapeHtml(info.title)}</span>` +
            `</div>` +
            `<div class="signal-equation-body"${isCollapsed ? ' style="display:none;"' : ''}>` +
                `<div class="signal-equation-formula">${info.formula}</div>` +
                info.hyperfineNote +
                info.voigtNote +
                info.zeemanNote +
                `<div class="signal-equation-params">${info.paramsHtml}</div>` +
            `</div>`;
        el.style.display = '';

        const headerEl = el.querySelector('.signal-equation-header');
        const bodyEl = el.querySelector('.signal-equation-body');
        if (headerEl && bodyEl) {
            const toggle = () => {
                toggleCollapsibleSection(sectionId, headerEl, bodyEl);
                if (headerEl.classList.contains('is-collapsed')) {
                    el.classList.add('is-collapsed');
                } else {
                    el.classList.remove('is-collapsed');
                }
            };
            headerEl.addEventListener('click', toggle);
            headerEl.addEventListener('keydown', (e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    toggle();
                }
            });
        }
    }

    // Rebuilds the noise multi-select from whichever generators are currently
    // selected (single generator, or the full Width/Contrast facet match set).
    // Pulled out of updateScanSignalControls so a facet-only change can refresh
    // just the noise list without rebuilding the facet buttons themselves (see
    // the facet 'controlchange' handler in renderGeneratorFacetSelects).
    function refreshScanNoiseControlForSelectedGenerators() {
        const selectedGenSet = new Set(getSelectedScanGenerators());
        const noiseItems = [...new Set(
            scanPlots
                .filter((p) => selectedGenSet.has(p.generator))
                .map((p) => p.noise)
        )];

        const prev = getSelectedScanNoises();
        renderMultiSelectNoiseControl(scanNoise, noiseItems, prev.length ? prev : null);
    }

    function updateScanStrategyControl() {
        const selectedScanGenerator = controlValue(scanGenerator);
        const selectedScanNoise = getEffectiveScanNoise();
        const availableFromPlots = new Set(
            scanPlots
                .filter((p) => p.generator === selectedScanGenerator && p.noise === selectedScanNoise)
                .map((p) => p.strategy),
        );
        const gridStrategies =
            (window.STRATEGY_GRID && window.STRATEGY_GRID[selectedScanGenerator]) || [];
        const scanStrategyItems = [
            ...new Set([...gridStrategies, ...availableFromPlots]),
        ];
        const disabledItems = new Set(
            scanStrategyItems.filter((strategy) => !availableFromPlots.has(strategy)),
        );
        renderSegmentedControl(scanStrategy, scanStrategyItems, controlValue(scanStrategy), {
            disabledItems,
        });
    }

    function updateScanRepeatControl() {
        const selectedScanGenerator = controlValue(scanGenerator);
        const selectedScanNoise = getEffectiveScanNoise();
        const selectedScanStrategy = controlValue(scanStrategy);

        updateFailedRunsButton(compareGeneratorsArg(), compareNoisesArg());

        const scanRepeatItems = scanPlots
            .filter(
                (p) =>
                    p.generator === selectedScanGenerator &&
                    p.noise === selectedScanNoise &&
                    p.strategy === selectedScanStrategy &&
                    isSuccessRun(p)
            )
            .map((p) => String(p.repeat ?? p.attempt ?? 1));
        const { value: selectedRepeat, items: repeatItems } = renderSelectControl(
            scanRepeat,
            scanRepeatItems,
            controlValue(scanRepeat) || scanRepeat.dataset.value || '',
        );
        currentRepeatItems = repeatItems;
        if (selectedRepeat) {
            scanRepeat.dataset.value = selectedRepeat;
        }
        updateRepeatNavButtons();

        const viewToggleContainer = document.getElementById('scan-view-toggle-container');
        if (viewToggleContainer) {
            if (repeatItems.length > 0) {
                viewToggleContainer.style.display = 'flex';
            } else {
                viewToggleContainer.style.display = 'none';
                const singleBtn = document.querySelector('#scan-view-mode button[data-value="single"]');
                if (singleBtn) singleBtn.click();
            }
        }
    }

    function updateAllScanControls() {
        updateScanSignalControls();
        updateNoiseViewMode();
        updateScanStrategyControl();
        updateScanRepeatControl();
    }

    // /api/manifest strips series/true_params/metrics from every entry (they're
    // large — the single biggest driver of manifest size at real cache scale) and
    // serves them per-repeat instead via /api/repeat-meta. The per-plot metrics
    // panel only ever needs them for the one currently-selected repeat, so fetch
    // and merge them into the manifest entry in place (cached on the object itself
    // so re-selecting the same plot doesn't refetch) before rendering.
    function ensureRepeatMeta(plot) {
        if (!plot || plot._metaFetched) return Promise.resolve(plot);
        const m = /\/api\/graph\/([^/]+)\/(\d+)\//.exec(plot.path || '');
        if (!m) return Promise.resolve(plot); // static/legacy path — nothing to fetch
        return fetch(`${window.NVISION_ASSET_PREFIX || ''}api/repeat-meta/${m[1]}/${m[2]}`, { cache: 'no-store' })
            .then((r) => (r.ok ? r.json() : null))
            .then((data) => {
                if (data) {
                    if (data.metrics != null) plot.metrics = data.metrics;
                    if (data.true_params != null) plot.true_params = data.true_params;
                    if (data.series != null) plot.series = data.series;
                }
                plot._metaFetched = true;
                return plot;
            })
            .catch(() => {
                plot._metaFetched = true; // don't retry forever on a persistent error
                return plot;
            });
    }

    function findAndDisplayPlot() {
        syncHashFromState();
        const scanGeneratorValue = controlValue(scanGenerator);
        const scanNoiseValue = getEffectiveScanNoise();
        const scanStrategyValue = controlValue(scanStrategy);
        const scanRepeatValue = controlValue(scanRepeat);

        // In range mode the single-scan display is suppressed; view mode handles everything
        if (isNoiseRangeMode() || isGeneratorRangeMode()) {
            currentPlot = null;
            setPlotSrc(scanIframe, document.getElementById('scan-plot-div'), null);
            if (scanMetrics) scanMetrics.innerHTML = '';
            if (scanSweepMetrics) scanSweepMetrics.hidden = true;
            const activeBtn = document.querySelector('#scan-view-mode button.is-active');
            if (activeBtn) showScanViewPanels(activeBtn.dataset.value);
            updateBayesTabs();
            return;
        }

        if (
            scanGeneratorValue &&
            scanNoiseValue &&
            scanStrategyValue &&
            scanRepeatValue
        ) {
            const repeatNumber = parseInt(scanRepeatValue, 10);
            const plot = scanPlots.find(
                (p) =>
                    p.generator === scanGeneratorValue &&
                    p.noise === scanNoiseValue &&
                    p.strategy === scanStrategyValue &&
                    (p.repeat === repeatNumber || String(p.repeat ?? p.attempt) === String(scanRepeatValue))
            );
            currentPlot = plot;
            updateScanCompareSweepControl(plot, null);
            setPlotSrc(scanIframe, document.getElementById('scan-plot-div'), plot ? plot.path : null);
            if (plot) {
              ensureRepeatMeta(plot).then(() => {
                function buildScanItems(phaseData, isOverall, totalMeasurements) {
                    const repeatTotal = plot.repeat_total ?? null;
                    const attemptLabel = repeatTotal
                        ? plot.repeat + '/' + repeatTotal
                        : String(plot.repeat);
                    // For sweep-only runs, phaseData.measurements is the authoritative total.
                    const fullMeasurements = phaseData.measurements != null ? phaseData.measurements : totalMeasurements;
                    const primaryConvergedStep = phaseData.primary_converged_step != null ? phaseData.primary_converged_step : (phaseData.metrics && phaseData.metrics.primary_converged_step != null ? phaseData.metrics.primary_converged_step : null);
                    const allConvergedStep = phaseData.all_converged_step != null ? phaseData.all_converged_step : (phaseData.metrics && phaseData.metrics.all_converged_step != null ? phaseData.metrics.all_converged_step : null);
                    const primaryConvResolved = primaryConvergedStep != null ? primaryConvergedStep : phaseData.steps_to_primary;

                    let phaseMeasurements = fullMeasurements;
                    if (currentStoppingCriteria === 'primary_converged' && primaryConvergedStep != null) {
                        phaseMeasurements = primaryConvergedStep;
                    } else if (currentStoppingCriteria === 'all_converged' && allConvergedStep != null) {
                        phaseMeasurements = allConvergedStep;
                    }

                    const primaryParamLabel = phaseData.stage_primary_param || (plot && plot.stage_primary_param) || 'zeeman_shift';
                    const items = [
                        { label: 'Attempt', val: attemptLabel, tip: 'Which repeat attempt this scan corresponds to (current/total).' },
                    ];
                    if (primaryConvResolved != null || allConvergedStep != null || fullMeasurements != null) {
                        items.push({
                            label: 'Converged',
                            tip: 'Measurements at which primary converged / all tracked parameters converged / the full run ended.',
                            table: [
                                { label: primaryParamLabel, val: primaryConvResolved != null ? formatCount(primaryConvResolved) : '–' },
                                { label: 'all', val: allConvergedStep != null ? formatCount(allConvergedStep) : '–' },
                                { label: 'full', val: fullMeasurements != null ? formatCount(fullMeasurements) : '–' },
                            ]
                        });
                    }
                    // Show total sweep steps (if any)
                    const sweepSteps = phaseData.sweep_steps;
                    if (sweepSteps != null && sweepSteps > 0) {
                        const sweepStr = phaseMeasurements != null && phaseMeasurements > 0
                            ? sweepSteps + '/' + phaseMeasurements
                            : String(sweepSteps);
                        items.push({ label: 'Sweep steps', val: sweepStr, tip: 'Measurements spent in the initial coarse/focused sweep phase.' });
                    }
                    if (phaseData.duration_ms != null) {
                        items.push({ label: 'Duration', val: formatDuration(phaseData.duration_ms), tip: 'Wall-clock time for this repeat.' });
                    }
                    if (phaseData.last_run != null) {
                        items.push({ label: 'Last run', val: formatTimestamp(phaseData.last_run), tip: 'Timestamp when this repeat was executed.' });
                    }

                    const phaseAbsErr = _mv(phaseData, 'abs_err_x', 'final_err_shift', 'pair_rmse');
                    const errPrimaryAtMilestone = phaseData.err_primary_at_milestone;
                    const uncertPrimaryAtMilestone = phaseData.uncert_primary_at_milestone;
                    const errPrimaryAtAll = _mv(phaseData, 'err_primary_at_all_converged');
                    const uncertPrimaryAtAll = _mv(phaseData, 'uncert_primary_at_all_converged');
                    const errRows = [];
                    // Red when |error| > uncert, deep red when |error| > 2·uncert.
                    const errRow = (label, err, unc) => {
                        let rowClass = '';
                        if (err != null && unc != null) {
                            const absErr = Math.abs(err);
                            if (absErr > 2 * unc) rowClass = 'err-high-row';
                            else if (absErr > unc) rowClass = 'err-medium-row';
                        }
                        return { label: label, rowClass: rowClass, vals: [
                            err != null ? formatHz(err) : '–',
                            unc != null ? formatHz(unc) : '–',
                        ] };
                    };
                    if (errPrimaryAtMilestone != null || uncertPrimaryAtMilestone != null) {
                        errRows.push(errRow(primaryParamLabel, errPrimaryAtMilestone, uncertPrimaryAtMilestone));
                    }
                    if (errPrimaryAtAll != null || uncertPrimaryAtAll != null) {
                        errRows.push(errRow('all', errPrimaryAtAll, uncertPrimaryAtAll));
                    }
                    if (phaseAbsErr != null || phaseData.uncert != null) {
                        errRows.push(errRow('full', phaseAbsErr, phaseData.uncert));
                    }
                    if (errRows.length > 0) {
                        items.push({
                            label: 'Error / uncertainty at each checkpoint',
                            tip: 'Error and uncertainty of the primary-parameter estimate at the moment primary converged / at the moment all tracked parameters converged / at the end of the full run. Lower is better. Rows turn red when |error| > uncert, deep red when |error| > 2·uncert.',
                            table: { columns: ['error', 'uncert'], rows: errRows }
                        });
                    }
                    return items;
                }



                function buildEarlyStopComparisonRows(phaseData) {
                    if (!phaseData) return [];
                    const metrics = phaseData.metrics || {};
                    
                    const measurements = phaseData.measurements != null ? phaseData.measurements : metrics.measurements;
                    const stepsToPrimary = phaseData.steps_to_primary != null ? phaseData.steps_to_primary : metrics.steps_to_primary;
                    
                    const uncert = phaseData.uncert != null ? phaseData.uncert : metrics.uncert;
                    const uncertPrimary = phaseData.uncert_primary_at_milestone != null ? phaseData.uncert_primary_at_milestone : metrics.uncert_primary_at_milestone;
                    
                    const absErr = _mv(phaseData, 'abs_err_x', 'final_err_shift', 'pair_rmse');
                    const errPrimary = phaseData.err_primary_at_milestone != null ? phaseData.err_primary_at_milestone : metrics.err_primary_at_milestone;

                    const earlyStopStepsExpected = (measurements != null && stepsToPrimary != null && stepsToPrimary < measurements);
                    const earlyStopUncertExpected = (uncert != null && uncertPrimary != null && uncert < uncertPrimary);
                    const earlyStopErrExpected = (absErr != null && errPrimary != null && absErr < errPrimary);

                    return [
                        // Row 1: Steps
                        [
                            { label: 'Sbed overall steps', val: measurements != null ? formatCount(measurements) : 'N/A', tip: 'Total measurements taken during Sbed active locator run.', cardClass: earlyStopStepsExpected ? 'expected-card' : '' },
                            { label: 'Sbed primary-parameter convergence', val: stepsToPrimary != null ? formatCount(stepsToPrimary) : 'N/A', tip: 'Steps needed for Sbed primary-parameter uncertainty to drop below threshold.', cardClass: earlyStopStepsExpected ? 'expected-card' : '' },
                            { label: 'Early stopping savings', val: (measurements != null && stepsToPrimary != null) ? formatCount(measurements - stepsToPrimary) : 'N/A', tip: 'Measurements saved by stopping active locator immediately after primary converges.', cardClass: earlyStopStepsExpected ? 'expected-card' : '' }
                        ],
                        // Row 2: Uncertainty
                        [
                            { label: 'Sbed final uncertainty', val: uncert != null ? formatHz(uncert) : 'N/A', tip: 'Final primary-parameter estimate uncertainty (standard deviation) at locator termination.', cardClass: earlyStopUncertExpected ? 'expected-card' : '' },
                            { label: 'Sbed primary-parameter uncertainty', val: uncertPrimary != null ? formatHz(uncertPrimary) : 'N/A', tip: 'Primary-parameter estimate uncertainty (standard deviation) at the moment primary converged.', cardClass: earlyStopUncertExpected ? 'expected-card' : '' },
                            { label: 'Milestone to final uncert diff', val: (uncert != null && uncertPrimary != null) ? formatHz(uncertPrimary - uncert) : 'N/A', tip: 'Uncertainty reduction achieved by continuing to run from the primary-parameter convergence milestone until locator termination.', cardClass: earlyStopUncertExpected ? 'expected-card' : '' }
                        ],
                        // Row 3: Absolute Error
                        [
                            { label: 'Sbed final error', val: absErr != null ? formatHz(absErr) : 'N/A', tip: 'Final absolute primary-parameter error vs ground truth at locator termination.', cardClass: earlyStopErrExpected ? 'expected-card' : '' },
                            { label: 'Sbed primary-parameter error', val: errPrimary != null ? formatHz(errPrimary) : 'N/A', tip: 'Absolute primary-parameter error vs ground truth at the moment primary converged.', cardClass: earlyStopErrExpected ? 'expected-card' : '' },
                            { label: 'Milestone to final error diff', val: (absErr != null && errPrimary != null) ? formatHz(errPrimary - absErr) : 'N/A', tip: 'Absolute error reduction achieved by continuing to run from the primary-parameter convergence milestone until locator termination.', cardClass: earlyStopErrExpected ? 'expected-card' : '' }
                        ]
                    ];
                }

                function renderRowsToHtml(rows) {
                    if (!rows || rows.length === 0) return '';
                    let html = '';
                    for (const row of rows) {
                        if (row && row.length > 0) {
                            html += '<div class="scan-metrics-panel" style="margin-bottom:0.5em;">' + renderItemsToHtml(row) + '</div>';
                        }
                    }
                    return html;
                }

                if (plot.coarse && plot.fine) {
                    const totalMeasurements = plot.measurements || (plot.coarse.measurements + plot.fine.measurements);
                    scanMetrics.className = 'scan-metrics-wrapper';
                    const coarseContent = '<div class="scan-metrics-panel">' + renderItemsToHtml(buildScanItems(plot.coarse, false, totalMeasurements)) + '</div>';
                    const fineContent = '<div class="scan-metrics-panel">' + renderItemsToHtml(buildScanItems(plot.fine, true, totalMeasurements)) + '</div>';
                    let html =
                        renderCollapsibleSectionHtml('scan-stage-coarse', plot.coarse.label, coarseContent) +
                        renderCollapsibleSectionHtml('scan-stage-fine', plot.fine.label, fineContent, 'margin-top:0.75em;');

                    if (plot.true_params && _hasKnownTrueParams(plot.true_params)) {
                        const trueParamsContent = '<div class="scan-metrics-panel">' + renderItemsToHtml(buildTrueParamItems(plot.true_params, plot), true) + '</div>';
                        html += renderCollapsibleSectionHtml('scan-true-params', plot.true_params.label, trueParamsContent, 'margin-top:0.75em;');
                    }
                    scanMetrics.innerHTML = html;
                    attachCollapsibleSectionListeners(scanMetrics);
                    updateStoppingCriteriaVisibility(plot);
                    setupRepeatComparisonUI(plot);
                } else {
                    scanMetrics.className = 'scan-metrics-wrapper';
                    let html = '<div class="scan-metrics-panel">' + renderItemsToHtml(buildScanItems(plot, true)) + '</div>';
                    // Slim manifest: show phase breakdown from flat fields when available
                    if (plot.coarse_measurements != null && plot.fine_measurements != null) {
                        html += '<div class="scan-metrics-panel" style="margin-top:0.5em;font-size:0.85em;color:#64748b;">' +
                            '<span style="margin-right:1em;">Sweep: ' + formatCount(plot.coarse_measurements) + ' meas.</span>' +
                            '<span>Inference: ' + formatCount(plot.fine_measurements) + ' meas.</span></div>';
                    }

                    if (plot.true_params && _hasKnownTrueParams(plot.true_params)) {
                        const trueParamsContent = '<div class="scan-metrics-panel">' + renderItemsToHtml(buildTrueParamItems(plot.true_params, plot), true) + '</div>';
                        html += renderCollapsibleSectionHtml('scan-true-params', plot.true_params.label, trueParamsContent, 'margin-top:0.75em;');
                    }
                    scanMetrics.innerHTML = html;
                    attachCollapsibleSectionListeners(scanMetrics);
                    updateStoppingCriteriaVisibility(plot);
                    setupRepeatComparisonUI(plot);
                }
                renderSweepMetricsPanel(scanSweepMetrics, plot.metrics || {});
                updateBayesView(plot);
                updateBayesStatsView(plot);
                updateBayesInteractiveView(plot);
                updateBayesTabs();
                // metrics just arrived — re-apply now that plot.metrics is actually populated.
                applyStoppingFrameLimit();
                refreshScanStepCapFromCriteria();
                updateScanViewAtCaption(plot);
              });
            } else {
                setPlotSrc(scanIframe, document.getElementById('scan-plot-div'), null);
                scanMetrics.className = '';
                scanMetrics.innerHTML = '';
                const scanCmpSel = document.getElementById('scan-comparison-selector');
                if (scanCmpSel) scanCmpSel.innerHTML = '';
                const scanCmpCards = document.getElementById('scan-comparison-cards');
                if (scanCmpCards) scanCmpCards.innerHTML = '';
                if (scanSweepMetrics) { scanSweepMetrics.hidden = true; scanSweepMetrics.innerHTML = ''; }
                updateBayesView(null);
                updateBayesStatsView(null);
                updateBayesInteractiveView(null);
                updateBayesTabs();
                updateScanViewAtCaption(null);
            }
        } else {
            setPlotSrc(scanIframe, document.getElementById('scan-plot-div'), null);
            scanMetrics.textContent = '';
            const scanCmpSel2 = document.getElementById('scan-comparison-selector');
            if (scanCmpSel2) scanCmpSel2.innerHTML = '';
            const scanCmpCards2 = document.getElementById('scan-comparison-cards');
            if (scanCmpCards2) scanCmpCards2.innerHTML = '';
            if (scanSweepMetrics) { scanSweepMetrics.hidden = true; scanSweepMetrics.innerHTML = ''; }
            updateBayesView(null);
            updateBayesStatsView(null);
            updateBayesInteractiveView(null);
            updateBayesTabs();
            updateScanViewAtCaption(null);
        }

        // Re-render the active Compare axis (if any) for the new selection.
        const activeViewModeBtn = document.querySelector('#scan-view-mode button.is-active');
        if (activeViewModeBtn && activeViewModeBtn.dataset.value !== 'single') {
            showScanViewPanels(activeViewModeBtn.dataset.value);
        }
        // Apply stopping-criteria cap to posterior animation after plot change
        applyStoppingFrameLimit();
    }

    // Real (e.g. MATLAB) runs carry a true_params object with no known ground
    // truth (all params null/NaN, since there's nothing to compare against).
    // Showing "True Signal Parameters: N/A" in that case reads as a broken
    // computation rather than "no ground truth" — skip the panel entirely.
    function _hasKnownTrueParams(trueData) {
        const params = (trueData && trueData.params) || {};
        return Object.values(params).some((v) => typeof v === 'number' && Number.isFinite(v));
    }

    function buildTrueParamItems(trueData, plot) {
        const items = [];
        const params = trueData.params || {};
        const bounds = trueData.bounds || {};
        // Preferred order for common parameters
        const preferred = ['zero_field_freq', 'hwhm', 'hwhm_lorentz', 'sigma_inhom', 'fwhm_total', 'hyperfine_shift', 'contrast_total', 'contrast', 'k_np', 'lorentz_frac'];
        const keys = Object.keys(params).sort((a, b) => {
            const ia = preferred.indexOf(a);
            const ib = preferred.indexOf(b);
            if (ia !== -1 && ib !== -1) return ia - ib;
            if (ia !== -1) return -1;
            if (ib !== -1) return 1;
            return a.localeCompare(b);
        });

        for (const name of keys) {
            const val = params[name];
            const b = bounds[name];
            let label = name.replace(/_/g, ' ');
            // Capitalize first letter
            label = label.charAt(0).toUpperCase() + label.slice(1);
            label += paramLetterSuffix(name);

            let formatted = val;
            let fmtLo = b ? b[0] : null;
            let fmtHi = b ? b[1] : null;

            const lowName = name.toLowerCase();
            const isHzParam = lowName.includes('freq') || lowName.includes('hwhm') || lowName.includes('hyperfine_shift') || lowName === 'fwhm_total' || lowName === 'sigma_inhom';

            if (typeof val === 'number') {
                if (isHzParam) {
                    formatted = formatHz(val);
                    if (b) {
                        fmtLo = formatHz(b[0]);
                        fmtHi = formatHz(b[1]);
                    }
                } else if (lowName === 'contrast' || lowName === 'k_np' || lowName === 'lorentz_frac') {
                    formatted = val.toFixed(3);
                    if (b) {
                        fmtLo = b[0].toFixed(3);
                        fmtHi = b[1].toFixed(3);
                    }
                } else {
                    formatted = formatMetricValue(val);
                    if (b) {
                        fmtLo = formatMetricValue(b[0]);
                        fmtHi = formatMetricValue(b[1]);
                    }
                }
            }

            // Extract final estimate and primary-parameter milestone if available
            let finalEst = null;
            if (plot && plot.metrics) {
                finalEst = plot.metrics["final_est_" + name];
            }

            let primaryAtMilestone = null;
            if (plot && plot.metrics && name === 'zero_field_freq') {
                primaryAtMilestone = plot.metrics["primary_at_milestone"];
            }

            items.push({
                label: label,
                val: formatted,
                bounds: b,
                rawVal: val,
                fmtLo: fmtLo,
                fmtHi: fmtHi,
                name: name,
                finalEst: finalEst,
                primaryAtMilestone: primaryAtMilestone
            });

            // Derived magnetic field, shown right after zeeman_shift (zeeman_shift is
            // the Zeeman-group half-separation, i.e. gamma * B for the NV electron spin).
            if (name === 'zeeman_shift' && typeof val === 'number' && Number.isFinite(val)) {
                const bTesla = zeemanShiftToMagneticFieldTesla(val);
                items.push({
                    label: 'Magnetic field',
                    val: formatMagneticField(bTesla),
                    bounds: null,
                    rawVal: bTesla,
                    fmtLo: null,
                    fmtHi: null,
                    name: 'magnetic_field',
                    finalEst: null,
                    primaryAtMilestone: null
                });
            }
        }
        return items;
    }

    // ---- Covariance ellipse renderer (JS-native, from JSON data) ----

    function registerTimelineAdapter(adapter) {
        if (!adapter || !adapter.contentWindow) return;
        activeIframes.add(adapter);
        updateGlobalTimelineMetadata();
    }

    /**
     * Compute 2σ covariance ellipse points for a 2×2 sub-covariance,
     * centered at (cx, cy). Replicates the Python eigensystem approach exactly.
     */
    function computeEllipse(cov2d, cx, cy) {
        const std_i = Math.sqrt(Math.max(cov2d[0][0], 1e-30));
        const std_j = Math.sqrt(Math.max(cov2d[1][1], 1e-30));
        let rho = cov2d[0][1] / (std_i * std_j);
        if (!isFinite(rho)) rho = 0;
        rho = Math.max(-0.9999, Math.min(0.9999, rho));
        // Eigensystem of [[1, ρ], [ρ, 1]] — eigh returns ascending eigenvalues.
        // For ρ≥0:  λ_a=1-ρ (v_a=[1,-1]/√2),  λ_b=1+ρ (v_b=[1,1]/√2)
        // For ρ<0:  λ_a=1+ρ (v_a=[1, 1]/√2),   λ_b=1-ρ (v_b=[1,-1]/√2)
        const va = rho >= 0 ? [1 / Math.SQRT2, -1 / Math.SQRT2] : [1 / Math.SQRT2, 1 / Math.SQRT2];
        const vb = rho >= 0 ? [1 / Math.SQRT2,  1 / Math.SQRT2] : [1 / Math.SQRT2, -1 / Math.SQRT2];
        const a_half = 2 * Math.sqrt(Math.max(1 - Math.abs(rho), 0));
        const b_half = 2 * Math.sqrt(Math.max(1 + Math.abs(rho), 0));
        const N = 100;
        const xs = new Array(N + 1), ys = new Array(N + 1);
        for (let k = 0; k <= N; k++) {
            const theta = (2 * Math.PI * k) / N;
            const ex = a_half * Math.cos(theta);
            const ey = b_half * Math.sin(theta);
            // Rotate by eigenvector matrix (rot.T in Python notation)
            xs[k] = cx + (ex * va[0] + ey * vb[0]) * std_i;
            ys[k] = cy + (ex * va[1] + ey * vb[1]) * std_j;
        }
        return { x: xs, y: ys };
    }

    /**
     * Render covariance ellipses from a JSON data file.
     * Creates one independent Plotly chart per parameter pair, side by side.
     * Calls onReady(adapter) once rendering is done so the caller can register
     * the adapter with the global timeline.
     */
    async function renderCovarianceEllipses(container, jsonPath, onReady) {
        container.innerHTML = '<div style="padding:2em;color:#64748b;text-align:center;">Loading covariance data…</div>';

        let data;
        try {
            data = await _fetchJson(jsonPath);
        } catch (e) {
            container.innerHTML = `<div style="padding:2em;color:#ef4444;">Failed to load covariance data: ${escapeHtml(String(e.message))}</div>`;
            return;
        }

        if (data.schema !== 'covariance_ellipses_v1' || !data.steps || !data.pairs) {
            container.innerHTML = '<div style="padding:2em;color:#64748b;">No covariance data available.</div>';
            return;
        }

        if (!container.isConnected) return;

        const { param_names, param_units, pairs, steps, true_params } = data;
        const nSteps = steps.length;

        await ensurePlotly();
        if (!container.isConnected) return;

        container.innerHTML = '';
        container.style.cssText = 'display:flex; gap:8px; flex-wrap:wrap; margin-top:8px;';

        const plotDivs = [];
        for (const [i, j] of pairs) {
            const pi = param_names[i];
            const pj = param_names[j];
            const piLabel = pi + (param_units[pi] || '');
            const pjLabel = pj + (param_units[pj] || '');

            const wrapper = document.createElement('div');
            wrapper.style.cssText = 'flex:1; min-width:220px; max-width:480px;';

            const titleEl = document.createElement('div');
            titleEl.style.cssText = 'text-align:center; font-size:0.78em; color:#64748b; font-weight:600; margin-bottom:2px;';
            titleEl.textContent = `${piLabel} vs ${pjLabel}`;
            wrapper.appendChild(titleEl);

            const plotDiv = document.createElement('div');
            wrapper.appendChild(plotDiv);
            container.appendChild(wrapper);
            plotDivs.push({ div: plotDiv, i, j, piLabel, pjLabel, pi, pj });
        }

        function updateJitterAndCorrelations(stepIdx) {
            const jitterContent = document.getElementById('bayes-jitter-content');
            if (!jitterContent) return;

            const idx = Math.max(0, Math.min(stepIdx, nSteps - 1));
            const step = steps[idx];
            const cov = step.covariance;

            const jitter = {};
            param_names.forEach(p => {
                const vals = [];
                for (let k = Math.max(0, idx - 19); k <= idx; k++) {
                    const m = steps[k].means[p];
                    if (m != null) vals.push(m);
                }
                if (vals.length > 0) {
                    const mean = vals.reduce((a, b) => a + b, 0) / vals.length;
                    const sqDiffSum = vals.reduce((sum, v) => sum + (v - mean) * (v - mean), 0);
                    jitter[p] = Math.sqrt(sqDiffSum / vals.length);
                } else {
                    jitter[p] = 0;
                }
            });

            const variances = {};
            param_names.forEach((p, pIdx) => {
                variances[p] = cov[pIdx][pIdx];
            });

            const correlations = {};
            param_names.forEach((p1, idx1) => {
                correlations[p1] = {};
                param_names.forEach((p2, idx2) => {
                    const std1 = Math.sqrt(cov[idx1][idx1]);
                    const std2 = Math.sqrt(cov[idx2][idx2]);
                    const corr = (std1 * std2 > 0) ? cov[idx1][idx2] / (std1 * std2) : 0;
                    correlations[p1][p2] = Math.max(-1.0, Math.min(1.0, corr));
                });
            });

            const jitterItems = param_names.map(name => ({
                label: name,
                val: formatMetricValue(jitter[name]),
                tip: 'Standard deviation of estimates over last 20 steps (physical units).',
                rawVal: jitter[name]
            }));

            const varItems = param_names.map(name => ({
                label: name,
                val: formatMetricValue(variances[name]),
                rawVal: variances[name]
            }));

            let html = '<h4>Jitter (last 20 steps)</h4>';
            html += '<div class="jitter-cards" style="display:flex; gap:8px; flex-wrap:wrap; margin-bottom:1.5em;">' + renderItemsToHtml(jitterItems) + '</div>';

            html += '<h4>Variances (diag Σ)</h4>';
            html += '<div class="jitter-cards" style="display:flex; gap:8px; flex-wrap:wrap; margin-bottom:1.5em;">' + renderItemsToHtml(varItems) + '</div>';

            html += '<h4>Correlation Matrix <span class="help-icon" tabindex="0" title="Measures how tightly parameters are coupled. +1/-1 = perfect correlation; 0 = independent.">?</span></h4>';
            html += '<div class="correlation-table-wrapper"><table class="correlation-table">';
            html += '<thead><tr><th></th>' + param_names.map(n => `<th>${escapeHtml(n)}</th>`).join('') + '</tr></thead>';
            html += '<tbody>';
            for (const ni of param_names) {
                html += `<tr><th>${escapeHtml(ni)}</th>`;
                for (const nj of param_names) {
                    const val = (correlations[ni] && correlations[ni][nj] !== undefined) ? correlations[ni][nj] : 0;
                    let color, textColor;
                    if (ni === nj) {
                        color = 'rgba(71, 85, 105, 0.15)';
                        textColor = '#1e293b';
                    } else if (val > 0) {
                        color = `rgba(30, 144, 255, ${0.1 + 0.9 * val})`;
                        textColor = val > 0.4 ? '#ffffff' : '#1e3a8a';
                    } else {
                        color = `rgba(239, 68, 68, ${0.1 + 0.9 * Math.abs(val)})`;
                        textColor = Math.abs(val) > 0.4 ? '#ffffff' : '#7f1d1d';
                    }
                    html += `<td class="corr-cell" style="background-color:${color}; color:${textColor};">${val.toFixed(2)}</td>`;
                }
                html += '</tr>';
            }
            html += '</tbody></table></div>';

            jitterContent.innerHTML = html;
        }

        function updateEllipseStep(stepIdx) {
            const step = steps[Math.max(0, Math.min(stepIdx, nSteps - 1))];
            const cov = step.covariance;
            const means = step.means || {};
            const progress = stepIdx / Math.max(1, nSteps - 1);
            const alpha = 0.25 + 0.55 * progress;
            const fillColor = `rgba(0, 100, 200, ${(alpha * 0.6).toFixed(2)})`;
            const lineColor = `rgba(0, 100, 200, ${alpha.toFixed(2)})`;

            for (const { div, i, j, piLabel, pjLabel, pi, pj } of plotDivs) {
                const cov2d = [[cov[i][i], cov[i][j]], [cov[j][i], cov[j][j]]];
                const cx = (means[pi] != null) ? means[pi] : 0;
                const cy = (means[pj] != null) ? means[pj] : 0;
                const { x, y } = computeEllipse(cov2d, cx, cy);

                const traces = [{
                    type: 'scatter', x, y,
                    mode: 'lines',
                    line: { color: lineColor, width: 2 },
                    fill: 'toself',
                    fillcolor: fillColor,
                    hoverinfo: 'skip',
                    showlegend: false,
                }];

                if (true_params) {
                    const ti = true_params[pi], tj = true_params[pj];
                    if (ti != null && tj != null) {
                        traces.push({
                            type: 'scatter', x: [ti], y: [tj],
                            mode: 'markers',
                            marker: { symbol: 'x', color: 'red', size: 10, line: { color: 'red', width: 2 } },
                            name: 'True', showlegend: false,
                        });
                    }
                }

                const layout = {
                    template: 'plotly_white',
                    margin: { l: 55, r: 10, t: 10, b: 50 },
                    xaxis: { title: { text: piLabel, font: { size: 11 } }, autorange: true },
                    yaxis: { title: { text: pjLabel, font: { size: 11 } }, autorange: true },
                    height: 260,
                    hovermode: false,
                };

                Plotly.react(div, traces, layout, { displayModeBar: false });
            }

            // Dynamically update the tables cell states
            updateJitterAndCorrelations(stepIdx);
        }

        updateEllipseStep(0);

        const adapter = {
            contentWindow: {
                showFrame: updateEllipseStep,
                totalFrames: nSteps,
                stepValues: steps.map((_, k) => k),
            },
            addEventListener: () => {},
        };

        if (onReady) onReady(adapter);
    }

    // ---- End covariance ellipse renderer ----

    // ---- JSON-based render functions (posterior, convergence, Fisher) ----

    /** Weighted Gaussian KDE at nGrid evenly-spaced points over [lo, hi]. */
    function _weightedKDE(values, weights, lo, hi, nGrid) {
        const n = values.length;
        let wSum = 0;
        for (let i = 0; i < n; i++) wSum += weights[i];
        if (wSum <= 0 || n === 0) return { grid: [], kde: [] };

        let mean = 0;
        for (let i = 0; i < n; i++) mean += (weights[i] / wSum) * values[i];
        let variance = 0;
        for (let i = 0; i < n; i++) {
            const d = values[i] - mean;
            variance += (weights[i] / wSum) * d * d;
        }
        const sigma = Math.sqrt(Math.max(variance, 1e-30));
        // Silverman's rule of thumb (the standard bandwidth for a KDE of a
        // roughly-unimodal distribution). A prior commit shrank the 1.06
        // constant to 0.12 (~9x narrower) with no recorded reason; combined
        // with the display subsample capped at 60 particles (_MAX_VIZ_PARTICLES
        // in nvision/runner/plots.py), that under-smoothing turns ordinary
        // sampling noise from the 60-particle draw into spurious bumps/lobes --
        // so even a true single Gaussian prior/posterior renders jagged and
        // multi-modal-looking here. Silverman's constant is calibrated to stay
        // reasonable at small n, unlike an arbitrarily small fixed fraction.
        const bw = Math.max(1.06 * sigma * Math.pow(n, -0.2), (hi - lo) * 1e-4);

        const grid = [], kde = [];
        const step = (hi - lo) / (nGrid - 1);
        const inv_bw_sqrt2pi = 1.0 / (bw * Math.sqrt(2 * Math.PI));
        const inv_bw = 1.0 / bw;
        for (let g = 0; g < nGrid; g++) {
            const x = lo + g * step;
            grid.push(x);
            let density = 0;
            for (let i = 0; i < n; i++) {
                const z = (x - values[i]) * inv_bw;
                density += (weights[i] / wSum) * Math.exp(-0.5 * z * z);
            }
            kde.push(density * inv_bw_sqrt2pi);
        }
        return { grid, kde };
    }

    async function renderPosterior(container, jsonPath, onReady, crlbJsonPath) {
        container.innerHTML = '<div style="padding:2em;color:#64748b;text-align:center;">Loading posterior data…</div>';

        let data;
        try {
            data = await _fetchJson(jsonPath);
        } catch (e) {
            container.innerHTML = `<div style="padding:2em;color:#ef4444;">Failed to load posterior data: ${escapeHtml(String(e.message))}</div>`;
            return;
        }

        // CRLB overlay (optional — older runs / non-SMC beliefs have no fisher data).
        let fisherData = null;
        if (crlbJsonPath) {
            try {
                const fd = await _fetchJson(crlbJsonPath);
                if (fd && fd.schema === 'fisher_v1' && fd.steps) fisherData = fd;
            } catch (e) { /* CRLB overlay is optional — ignore load failures */ }
        }

        if (data.schema !== 'posterior_v1' || !data.steps || !data.param_names) {
            container.innerHTML = '<div style="padding:2em;color:#64748b;">No posterior data available.</div>';
            return;
        }
        if (!container.isConnected) return;

        const { param_names, param_units, physical_bounds, true_params, resampled_steps, steps } = data;
        const nSteps = steps.length;
        const nParams = param_names.length;

        // Vertical markers at every SMC resample+jitter step, for the uncertainty
        // and ESS mini-charts below. A sharp uncertainty jump exactly *on* one of
        // these is expected, and is an artifact: the resample redraws a decaying
        // fraction of particles from the prior, and since sigma is quadratic in
        // distance a couple of them dominate it for one step, until the next
        // likelihood update kills them. The dashed robust trace omits them. The
        // step *before* a resample is an ordinary step -- measured across the
        // matlab runs, u[r-1]/u[r-2] matches the run-wide median.
        // resampled_steps decodes as a Float32Array (compact numeric encoding) —
        // TypedArray.prototype.map() coerces a returned object to NaN instead of
        // collecting it, so _resampleMarkerShapes converts to a plain array first.
        function resampleMarkerShapes(yref) {
            return _resampleMarkerShapes(resampled_steps, yref);
        }

        await ensurePlotly();
        if (!container.isConnected) return;

        container.innerHTML = '';

        // Independent of the Convergence/Fisher tabs' own log-scale toggles — each
        // view remembers its own choice rather than sharing one flag.
        let logScale = false;
        const overlayState = {
            uncertainty: true,
            crlb: true,
            oracleCrlb: true,
            threshold: true,
            resamples: true,
        };
        container.appendChild(_uncertaintyControlsRow(
            logScale,
            (v) => { logScale = v; updateStep(lastStepIdx); },
            overlayState,
            () => {
                plotDivs.forEach((pdEntry) => { pdEntry.zoomRange = null; });
                updateStep(lastStepIdx);
            }
        ));

        // Setup Grid Wrapper Container (max 4 columns)
        const gridWrapper = document.createElement('div');
        gridWrapper.className = 'posterior-card-grid';
        container.appendChild(gridWrapper);

        const COLORS = ['#1e90ff', '#e05c00', '#00a878', '#9b59b6', '#e74c3c', '#2ecc71', '#f39c12'];
        const plotDivs = [];
        param_names.forEach((param, ci) => {
            const unit = param_units[param] ? ` (${param_units[param]})` : '';
            const wrapper = document.createElement('div');
            wrapper.className = 'posterior-card';
            
            const title = document.createElement('div');
            title.style.cssText = 'text-align:center; font-size:0.78em; color:#64748b; font-weight:600; margin-bottom:4px;';
            title.textContent = param + unit + paramLetterSuffix(param);
            wrapper.appendChild(title);
            
            const rowWrapper = document.createElement('div');
            rowWrapper.style.cssText = 'display: flex; gap: 8px; align-items: center; width: 100%;';
            
            const plotDiv = document.createElement('div');
            plotDiv.style.cssText = 'flex: 6.5; min-width: 0;';
            
            const uncDiv = document.createElement('div');
            uncDiv.style.cssText = 'flex: 3.5; min-width: 0;';
            
            rowWrapper.appendChild(plotDiv);
            rowWrapper.appendChild(uncDiv);
            wrapper.appendChild(rowWrapper);
            
            gridWrapper.appendChild(wrapper);
            
            // Calculate parameter uncertainty history across all steps
            const uncHistory = steps.map(s => (s[param] && s[param].uncertainty != null) ? s[param].uncertainty : null);
            // Outlier-insensitive spread (weighted IQR/1.349). The reported sigma
            // spikes on every resample because a handful of particles are redrawn
            // from the prior; this curve shows what the bulk of the cloud did.
            const robustHistory = steps.map(s => (s[param] && s[param].uncertainty_robust != null) ? s[param].uncertainty_robust : null);
            // CRLB history, index-aligned with `steps` (both derive from the same
            // per-step bayesian_snapshots list when fisherData is present).
            const crlbHistory = fisherData
                ? steps.map((_, i) => {
                    const fs = fisherData.steps[i];
                    return (fs && fs.fisher_bounds && fs.fisher_bounds[param] != null) ? fs.fisher_bounds[param] : null;
                })
                : null;
            // Oracle CRLB: the hard information limit for an ideal, uniformly-sampled
            // design at the *true* parameters -- distinct from crlbHistory above, which
            // is derived from this run's own actual measurements (and reflects how well
            // THIS acquisition did, not what's fundamentally achievable).
            const oracleCrlbHistory = fisherData
                ? steps.map((_, i) => {
                    const fs = fisherData.steps[i];
                    return (fs && fs.oracle_crlb && fs.oracle_crlb[param] != null) ? fs.oracle_crlb[param] : null;
                })
                : null;
            const color = COLORS[ci % COLORS.length];

            plotDivs.push({ div: plotDiv, uncDiv: uncDiv, param, uncHistory, robustHistory, crlbHistory, oracleCrlbHistory, color, zoomRange: null, zoomBound: false });
        });

        // SMC Diagnostics plotting setup
        const diagnosticsContainer = document.getElementById('smc-diagnostics-container');
        const firstParam = param_names[0];
        const hasParticles = steps[0] && steps[0][firstParam] && steps[0][firstParam].type === 'particles';
        
        let essHistory = [];
        let thresholdVal = 0;
        let nParticles = 0;
        
        if (hasParticles && diagnosticsContainer) {
            diagnosticsContainer.style.display = 'block';
            const thresholdPct = data.ess_threshold != null ? data.ess_threshold : 0.2;

            // Prefer the ESS the filter itself recorded: it covers the full particle
            // cloud and is captured *before* the resample resets the weights. Deriving
            // it from the stored weights gets both of those wrong -- they are a
            // 60-particle subsample, and uniform on every resampled step -- so the
            // fallback curve is capped at the subsample size and can never reach the
            // threshold that actually fired. Only pre-fix runs take that path.
            const recordedEss = Array.from(data.ess_history || []);
            const haveRecordedEss = recordedEss.length === nSteps
                && recordedEss.some(v => v != null && isFinite(v));

            if (haveRecordedEss) {
                nParticles = data.num_particles || Math.max(...recordedEss.filter(v => v != null && isFinite(v)));
                essHistory = recordedEss.map(v => (v != null && isFinite(v)) ? v : null);
            } else {
                nParticles = steps[0][firstParam].weights.length;
                for (let s = 0; s < nSteps; s++) {
                    const stepEntry = steps[s][firstParam];
                    if (stepEntry && stepEntry.weights) {
                        const w = stepEntry.weights;
                        const wSum = w.reduce((a, b) => a + b, 0);
                        const normW = wSum > 0 ? w.map(x => x / wSum) : w;
                        const sumSq = normW.reduce((a, b) => a + b * b, 0);
                        const ess = sumSq > 0 ? 1 / sumSq : 0;
                        essHistory.push(ess);
                    } else {
                        essHistory.push(null);
                    }
                }
            }
            thresholdVal = thresholdPct * nParticles;
        } else if (diagnosticsContainer) {
            diagnosticsContainer.style.display = 'none';
        }

        // Setup Slider Ticks Overlay
        const ticksContainer = document.getElementById('timeline-ticks-container');
        if (ticksContainer) {
            ticksContainer.innerHTML = '';
            if (resampled_steps && resampled_steps.length > 0 && nSteps > 1) {
                resampled_steps.forEach(idx => {
                    const pct = (idx / (nSteps - 1)) * 100;
                    const tick = document.createElement('div');
                    tick.className = 'timeline-tick';
                    tick.style.left = `calc(${pct}% - 1px)`;
                    ticksContainer.appendChild(tick);
                });
            }
        }

        // Auto-scale toggle button
        const autoscaleBtn = document.getElementById('posterior-autoscale-btn');
        window.POSTERIOR_AUTOSCALE = true; // default true
        if (autoscaleBtn) {
            autoscaleBtn.textContent = 'Disable Autoscale';
            autoscaleBtn.classList.remove('is-active');
            
            const newBtn = autoscaleBtn.cloneNode(true);
            autoscaleBtn.parentNode.replaceChild(newBtn, autoscaleBtn);
            newBtn.addEventListener('click', () => {
                window.POSTERIOR_AUTOSCALE = !window.POSTERIOR_AUTOSCALE;
                newBtn.textContent = window.POSTERIOR_AUTOSCALE ? 'Disable Autoscale' : 'Enable Autoscale';
                newBtn.classList.toggle('is-active', !window.POSTERIOR_AUTOSCALE);
                const currentIdx = parseInt(globalSlider.value, 10);
                if (!isNaN(currentIdx)) {
                    syncFrames(currentIdx);
                }
            });
        }

        let lastStepIdx = 0;
        // Manual drag-zoom tracking for the uncDiv mini-charts (see the zoomRange
        // field on each plotDivs entry): Plotly's uirevision mechanism does *not*
        // preserve a user's zoom here, because every step re-render supplies its
        // own explicit computed range (needed so the threshold/CRLB stay in view —
        // see logRange below) rather than autorange, which is what uirevision
        // actually needs to have something to defer to. So the zoom is tracked and
        // re-applied by hand instead, and cleared when the scale mode flips (a
        // linear-space zoom window isn't meaningful once re-interpreted as log10).
        let lastScaleModeForZoom = logScale;
        function updateStep(stepIdx) {
            lastStepIdx = stepIdx;
            const step = steps[Math.max(0, Math.min(stepIdx, nSteps - 1))];
            const isResampled = resampled_steps && resampled_steps.includes(stepIdx);

            if (lastScaleModeForZoom !== logScale) {
                lastScaleModeForZoom = logScale;
                plotDivs.forEach((pdEntry) => { pdEntry.zoomRange = null; });
            }

            for (const pdEntry of plotDivs) {
                const { div, uncDiv, param, uncHistory, robustHistory, crlbHistory, oracleCrlbHistory, color } = pdEntry;
                const entry = step[param];
                if (!entry) continue;

                const unit = param_units[param] ? ` (${param_units[param]})` : '';
                const bounds = physical_bounds[param];
                const traces = [];
                let lo = bounds ? bounds[0] : 0;
                let hi = bounds ? bounds[1] : 1;

                if (entry.type === 'particles') {
                    const values = entry.values;
                    const weights = entry.weights;
                    const n = values.length;

                    let wSum = 0;
                    for (let i = 0; i < n; i++) wSum += weights[i];

                    let mean = 0;
                    for (let i = 0; i < n; i++) mean += (weights[i] / wSum) * values[i];
                    let variance = 0;
                    for (let i = 0; i < n; i++) {
                        const d = values[i] - mean;
                        variance += (weights[i] / wSum) * d * d;
                    }
                    const sigma = Math.sqrt(Math.max(variance, 1e-30));
                    // Kept identical to _weightedKDE's own bandwidth (Silverman's rule)
                    // so the padding this pads by actually matches the curve it pads.
                    const bw_est = 1.06 * sigma * Math.pow(n, -0.2);

                    if (window.POSTERIOR_AUTOSCALE !== false) {
                        if (n > 0) {
                            const minVal = Math.min(...values);
                            const maxVal = Math.max(...values);
                            // Add 3 bandwidths padding to prevent cutoff
                            lo = minVal - 3 * bw_est;
                            hi = maxVal + 3 * bw_est;
                            // Clamp to physical bounds
                            if (bounds) {
                                lo = Math.max(lo, bounds[0]);
                                hi = Math.min(hi, bounds[1]);
                            }
                        }
                    } else {
                        lo = bounds ? bounds[0] : (n > 0 ? Math.min(...values) : 0);
                        hi = bounds ? bounds[1] : (n > 0 ? Math.max(...values) : 1);
                    }

                    const { grid, kde } = _weightedKDE(values, weights, lo, hi, 800);
                    traces.push({
                        type: 'scatter', x: grid, y: kde,
                        mode: 'lines',
                        fill: 'tozeroy',
                        fillcolor: isResampled ? 'rgba(255,140,0,0.18)' : 'rgba(0,100,200,0.18)',
                        line: { color: isResampled ? 'rgba(255,140,0,0.8)' : 'rgba(0,100,200,0.8)', width: 1.5 },
                        hoverinfo: 'skip', showlegend: false,
                    });
                } else if (entry.type === 'grid') {
                    traces.push({
                        type: 'bar', x: entry.axis, y: entry.posterior,
                        marker: { color: 'rgba(0,100,200,0.5)' },
                        hoverinfo: 'skip', showlegend: false,
                    });
                }

                // Ground truth line using layout shape (stretching full height)
                const shapes = [];
                if (true_params && true_params[param] != null) {
                    const tv = true_params[param];
                    shapes.push({
                        type: 'line',
                        xref: 'x',
                        yref: 'paper',
                        x0: tv,
                        x1: tv,
                        y0: 0,
                        y1: 1,
                        line: {
                            color: 'rgba(200,30,30,0.8)',
                            width: 1.5,
                            dash: 'dash'
                        }
                    });
                }

                let xrange;
                if (window.POSTERIOR_AUTOSCALE !== false) {
                    if (entry.type === 'particles') {
                        xrange = [lo, hi];
                    } else if (entry.type === 'grid' && entry.axis && entry.axis.length > 0) {
                        xrange = [Math.min(...entry.axis), Math.max(...entry.axis)];
                    } else {
                        xrange = bounds ? [bounds[0], bounds[1]] : undefined;
                    }
                } else {
                    xrange = bounds ? [bounds[0], bounds[1]] : undefined;
                }

                const layout = {
                    template: 'plotly_white',
                    margin: { l: 10, r: 10, t: 4, b: 36 },
                    xaxis: {
                        title: { text: param + unit, font: { size: 11 } },
                        tickfont: { size: 10 },
                        range: xrange,
                        autorange: xrange === undefined
                    },
                    yaxis: { visible: false },
                    height: 240,
                    hovermode: false,
                    shapes: shapes,
                };
                Plotly.react(div, traces, layout, { responsive: true, displayModeBar: false });

                // Render the small uncertainty line chart
                if (uncDiv && uncHistory && uncHistory.some(v => v !== null)) {
                    // A single uncertainty line, not two: raw sigma spikes on every SMC
                    // resample (a decaying fraction of particles is redrawn from the
                    // prior, and sigma is quadratic in distance, so a couple of them
                    // dominate it for exactly one step) which reads as the belief
                    // repeatedly widening and re-narrowing when it didn't. That's a
                    // rendering artifact, not new information, and the resample steps
                    // are already marked separately by the vertical orange lines below
                    // -- so prefer the outlier-insensitive robust (IQR-based) value
                    // per step where it's available, falling back to raw sigma only for
                    // steps too early to have 4+ particles for an IQR (robustHistory[i]
                    // is null there).
                    const displayHistory = steps.map((_, idx) =>
                        (robustHistory && robustHistory[idx] != null) ? robustHistory[idx] : uncHistory[idx]
                    );
                    const uncTraces = [];
                    if (overlayState.uncertainty) {
                        uncTraces.push({
                            type: 'scatter',
                            x: steps.map((_, idx) => idx),
                            y: displayHistory,
                            mode: 'lines',
                            line: { color: color, width: 1.5 },
                            hoverinfo: 'skip',
                            showlegend: false,
                            name: 'Uncertainty (σ)',
                        });
                    }

                    if (overlayState.crlb && crlbHistory && crlbHistory.some(v => v !== null)) {
                        uncTraces.push({
                            type: 'scatter',
                            x: steps.map((_, idx) => idx),
                            y: crlbHistory,
                            mode: 'lines',
                            line: { color: '#9333ea', width: 1.2, dash: 'dot' },
                            hoverinfo: 'skip',
                            showlegend: false,
                            name: 'CRLB (achieved)',
                        });
                    }

                    // Oracle CRLB: absolute best any acquisition could do with the same
                    // number of measurements (ideal placement, true parameters) -- a hard
                    // floor, plotted distinctly from the achieved (data-driven) CRLB above.
                    if (overlayState.oracleCrlb && oracleCrlbHistory && oracleCrlbHistory.some(v => v !== null)) {
                        uncTraces.push({
                            type: 'scatter',
                            x: steps.map((_, idx) => idx),
                            y: oracleCrlbHistory,
                            mode: 'lines',
                            line: { color: '#059669', width: 1.2, dash: 'dashdot' },
                            hoverinfo: 'skip',
                            showlegend: false,
                            name: 'CRLB (oracle)',
                        });
                    }

                    const uncShapes = [];
                    // Resample+jitter markers, drawn first so the current-step line
                    // layers on top when they coincide.
                    if (overlayState.resamples) {
                        uncShapes.push(...resampleMarkerShapes());
                    }
                    // Current step vertical indicator line
                    uncShapes.push({
                        type: 'line',
                        x0: stepIdx,
                        x1: stepIdx,
                        y0: 0,
                        y1: 1,
                        yref: 'paper',
                        line: { color: 'rgba(59, 130, 246, 0.8)', width: 2 }
                    });

                    // Add red dashed line for the threshold if available
                    let threshVal = null;
                    if (data.absolute_thresholds && data.absolute_thresholds[param] != null) {
                        threshVal = data.absolute_thresholds[param];
                    } else if (param === 'zero_field_freq') {
                        threshVal = 100000.0 / 1e9; // 100 KHz in GHz
                    } else if (data.convergence_threshold != null && bounds) {
                        threshVal = data.convergence_threshold * (bounds[1] - bounds[0]);
                    } else if (bounds) {
                        threshVal = 0.01 * (bounds[1] - bounds[0]);
                    }

                    if (uncTraces.length === 0) {
                        uncTraces.push({
                            type: 'scatter',
                            x: [0, Math.max(0, nSteps - 1)],
                            y: [threshVal || 1, threshVal || 1],
                            mode: 'markers',
                            marker: { opacity: 0 },
                            hoverinfo: 'skip',
                            showlegend: false,
                        });
                    }

                    // Text labels so a solid/dashed/dotted line doesn't have to be
                    // decoded from color alone — same convention (and same left/right
                    // anchoring, to keep the two labels apart) as the bigger Convergence
                    // tab cards below.
                    const uncAnnotations = [];

                    if (overlayState.threshold && threshVal !== null) {
                        uncShapes.push({
                            type: 'line',
                            x0: 0,
                            x1: nSteps - 1,
                            y0: threshVal,
                            y1: threshVal,
                            line: { color: '#ef4444', width: 1.2, dash: 'dash' }
                        });
                        uncAnnotations.push({
                            x: nSteps - 1, y: threshVal, xref: 'x', yref: 'y',
                            text: 'threshold', showarrow: false,
                            xanchor: 'right', yanchor: 'bottom',
                            font: { size: 8, color: '#b91c1c' },
                        });
                    }

                    if (overlayState.crlb && crlbHistory) {
                        const firstIdx = crlbHistory.findIndex((v) => v != null);
                        if (firstIdx !== -1) {
                            uncAnnotations.push({
                                x: firstIdx, y: crlbHistory[firstIdx], xref: 'x', yref: 'y',
                                text: 'CRLB (achieved)', showarrow: false,
                                xanchor: 'left', yanchor: 'top',
                                font: { size: 8, color: '#9333ea' },
                            });
                        }
                    }

                    if (overlayState.oracleCrlb && oracleCrlbHistory) {
                        const firstIdx = oracleCrlbHistory.findIndex((v) => v != null);
                        if (firstIdx !== -1) {
                            uncAnnotations.push({
                                x: firstIdx, y: oracleCrlbHistory[firstIdx], xref: 'x', yref: 'y',
                                text: 'CRLB (oracle)', showarrow: false,
                                xanchor: 'left', yanchor: 'bottom',
                                font: { size: 8, color: '#059669' },
                            });
                        }
                    }

                    // Plotly's log-axis autorange only looks at trace *data* — it ignores
                    // shapes entirely, so the threshold line (and, on an unconverged run,
                    // the whole point of showing it) silently falls outside the view
                    // whenever it sits below every uncertainty value plotted so far. Fold
                    // the threshold (and the CRLB overlay, if drawn) into an explicit range
                    // so both stay visible instead of relying on autorange.
                    let logRange = null;
                    // The actual (achieved) uncertainty is the primary quantity this chart
                    // exists to show; CRLB/oracle-CRLB are reference lines. A CRLB well above
                    // the actual uncertainty is common and expected (see the informative-prior
                    // discussion), but letting it set the axis max flattens the actual line to
                    // an invisible flat 0 — so the range is sized off the primary data
                    // (+threshold), and a CRLB line that exceeds it is simply clipped at the
                    // top rather than compressing everything else. Applied in both scale
                    // modes -- linear mode had no explicit range at all before (pure
                    // autorange), which is the more severe case since one large CRLB point
                    // rescales the *entire* axis, not just a couple of log decades.
                    let linRange = null;
                    if (pdEntry.zoomRange) {
                        // A manual drag-zoom is active for this chart — keep it across
                        // step-scrubbing instead of snapping back to the full range
                        // (see the plotly_relayout listener bound below).
                        if (logScale) logRange = pdEntry.zoomRange;
                        else linRange = pdEntry.zoomRange;
                    } else {
                        const priorityVals = overlayState.uncertainty ? displayHistory.filter((v) => v != null && v >= 0) : [];
                        if (overlayState.threshold && threshVal !== null && threshVal >= 0) priorityVals.push(threshVal);
                        const referenceVals = [];
                        if (overlayState.crlb && crlbHistory) referenceVals.push(...crlbHistory.filter((v) => v != null && v > 0));
                        if (overlayState.oracleCrlb && oracleCrlbHistory) referenceVals.push(...oracleCrlbHistory.filter((v) => v != null && v > 0));

                        if (logScale) {
                            const positiveVals = priorityVals.filter((v) => v > 0).concat(referenceVals);
                            if (positiveVals.length > 0) {
                                const lo = Math.log10(Math.min(...positiveVals));
                                const hi = Math.log10(Math.max(...positiveVals));
                                const pad = Math.max((hi - lo) * 0.08, 0.05);
                                logRange = [lo - pad, hi + pad];
                            }
                        } else if (priorityVals.length > 0) {
                            const dataMax = Math.max(...priorityVals);
                            // 30% headroom above the primary data; reference (CRLB) lines
                            // above that are allowed to run off the top of the view.
                            linRange = [0, dataMax > 0 ? dataMax * 1.3 : 1];
                        } else if (referenceVals.length > 0) {
                            // No actual/threshold data yet -- fall back to fitting the
                            // reference lines so the chart isn't a blank 0-1 box.
                            linRange = [0, Math.max(...referenceVals) * 1.1];
                        }
                    }

                    const uncLayout = {
                        template: 'plotly_white',
                        margin: { l: 24, r: 5, t: 5, b: 20 },
                        xaxis: {
                            visible: true,
                            tickfont: { size: 8 },
                            title: { text: 'Step', font: { size: 8 } }
                        },
                        yaxis: logScale
                            ? { visible: true, tickfont: { size: 9 }, type: 'log', range: logRange, autorange: logRange ? false : true }
                            : { visible: true, tickfont: { size: 9 }, range: linRange, autorange: linRange ? false : true, rangemode: 'tozero' },
                        height: 240,
                        hovermode: false,
                        shapes: uncShapes,
                        annotations: uncAnnotations,
                    };

                    Plotly.react(uncDiv, uncTraces, uncLayout, { responsive: true, displayModeBar: false });

                    // Capture a manual drag-zoom (e.g. into the converged tail, to compare
                    // against the threshold/CRLB) so the *next* step's Plotly.react call
                    // above can re-apply it via pdEntry.zoomRange instead of the computed
                    // logRange. Plotly's own uirevision doesn't help here since this chart
                    // always supplies an explicit range/rangemode rather than autorange.
                    if (!pdEntry.zoomBound) {
                        pdEntry.zoomBound = true;
                        uncDiv.on('plotly_relayout', (ev) => {
                            if (ev['yaxis.range']) {
                                pdEntry.zoomRange = ev['yaxis.range'].slice();
                            } else if (ev['yaxis.range[0]'] !== undefined && ev['yaxis.range[1]'] !== undefined) {
                                pdEntry.zoomRange = [ev['yaxis.range[0]'], ev['yaxis.range[1]']];
                            } else if (ev['yaxis.autorange']) {
                                pdEntry.zoomRange = null;
                            }
                        });
                    }
                }
            }

            // Redraw SMC diagnostics plots
            if (hasParticles && diagnosticsContainer) {
                // Update ESS chart
                const essDiv = document.getElementById('smc-ess-chart');
                const essTraces = [
                    {
                        type: 'scatter',
                        x: steps.map((_, i) => i),
                        y: essHistory,
                        mode: 'lines',
                        name: 'ESS',
                        line: { color: '#0ea5e9', width: 2 }
                    }
                ];
                const essLayout = {
                    template: 'plotly_white',
                    margin: { l: 40, r: 15, t: 15, b: 35 },
                    xaxis: { title: 'Step' },
                    yaxis: { title: 'ESS', range: [0, nParticles * 1.05] },
                    height: 180,
                    showlegend: false,
                    shapes: [
                        // Resample+jitter markers. These line up with threshold
                        // crossings only when ess_history is the belief-recorded
                        // one; on pre-fix runs the curve comes from post-resample
                        // subsample weights and sits far above a threshold scaled
                        // to that subsample.
                        ...resampleMarkerShapes(),
                        {
                            type: 'line',
                            x0: 0,
                            x1: nSteps - 1,
                            y0: thresholdVal,
                            y1: thresholdVal,
                            line: { color: '#f43f5e', width: 1.5, dash: 'dash' }
                        },
                        {
                            type: 'line',
                            x0: stepIdx,
                            x1: stepIdx,
                            y0: 0,
                            y1: 1,
                            yref: 'paper',
                            line: { color: 'rgba(59, 130, 246, 0.8)', width: 2 }
                        }
                    ]
                };
                Plotly.react(essDiv, essTraces, essLayout, { responsive: true, displayModeBar: false });

                // Update Sorted Weights chart
                const weightsDiv = document.getElementById('smc-weights-chart');
                const currentStep = steps[stepIdx];
                if (currentStep && currentStep[firstParam]) {
                    const w = currentStep[firstParam].weights;
                    const sortedW = [...w].sort((a, b) => b - a);
                    const weightsTraces = [
                        {
                            type: 'bar',
                            x: sortedW.map((_, idx) => idx),
                            y: sortedW,
                            marker: { color: '#6366f1' }
                        }
                    ];
                    const weightsLayout = {
                        template: 'plotly_white',
                        margin: { l: 40, r: 15, t: 15, b: 35 },
                        xaxis: { title: 'Sorted Particle Index' },
                        yaxis: { title: 'Weight', range: [0, Math.max(...sortedW) * 1.1] },
                        height: 180,
                        showlegend: false
                    };
                    Plotly.react(weightsDiv, weightsTraces, weightsLayout, { responsive: true, displayModeBar: false });
                }
            }
        }

        updateStep(0);
        setTimeout(() => {
            window.dispatchEvent(new Event('resize'));
        }, 50);

        const adapter = {
            contentWindow: {
                showFrame: updateStep,
                totalFrames: nSteps,
                stepValues: steps.map((_, k) => k),
            },
            addEventListener: () => {},
        };
        if (onReady) onReady(adapter);
    }

    // Each tab (Posterior Evolution, Convergence, Fisher) keeps its *own* independent
    // log-scale flag — this just builds the switch UI for whichever one the caller
    // owns. `initialValue` seeds the switch's starting position; `onToggle(checked)`
    // fires on change so the caller can update its own local flag and re-render only
    // its own chart(s). Flipping one tab's switch deliberately does not touch any
    // other tab's.
    function _logScaleToggle(initialValue, onToggle) {
        const wrapper = document.createElement('label');
        wrapper.className = 'ios-switch';
        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.checked = initialValue;
        checkbox.addEventListener('change', () => onToggle(checkbox.checked));
        const track = document.createElement('span');
        track.className = 'ios-switch-track';
        track.setAttribute('aria-hidden', 'true');
        const label = document.createElement('span');
        label.className = 'ios-switch-label';
        label.textContent = 'Log scale (show small uncertainties)';
        wrapper.appendChild(checkbox);
        wrapper.appendChild(track);
        wrapper.appendChild(label);
        return wrapper;
    }

    function _uncertaintyControlsRow(logScale, onLogToggle, overlayState, onOverlayChange) {
        const row = document.createElement('div');
        row.className = 'uncertainty-controls-row';
        row.appendChild(_logScaleToggle(logScale, onLogToggle));

        const legendBar = document.createElement('div');
        legendBar.className = 'uncertainty-legend-bar';
        legendBar.setAttribute('role', 'group');
        legendBar.setAttribute('aria-label', 'Chart overlay legend (click to toggle, double-click to isolate)');

        const title = document.createElement('span');
        title.className = 'uncertainty-legend-title';
        title.textContent = 'Legend:';
        legendBar.appendChild(title);

        const items = [
            {
                key: 'uncertainty',
                label: 'Uncertainty (σ)',
                svg: '<svg class="uncertainty-legend-swatch" width="22" height="10" viewBox="0 0 22 10" aria-hidden="true"><line x1="1" y1="5" x2="21" y2="5" stroke="#00a878" stroke-width="2"/></svg>',
            },
            {
                key: 'crlb',
                label: 'CRLB (achieved)',
                svg: '<svg class="uncertainty-legend-swatch" width="22" height="10" viewBox="0 0 22 10" aria-hidden="true"><line x1="1" y1="5" x2="21" y2="5" stroke="#9333ea" stroke-width="1.8" stroke-dasharray="2,2"/></svg>',
            },
            {
                key: 'oracleCrlb',
                label: 'CRLB (oracle)',
                svg: '<svg class="uncertainty-legend-swatch" width="22" height="10" viewBox="0 0 22 10" aria-hidden="true"><line x1="1" y1="5" x2="21" y2="5" stroke="#059669" stroke-width="1.8" stroke-dasharray="5,2,1.5,2"/></svg>',
            },
            {
                key: 'threshold',
                label: 'Threshold',
                svg: '<svg class="uncertainty-legend-swatch" width="22" height="10" viewBox="0 0 22 10" aria-hidden="true"><line x1="1" y1="5" x2="21" y2="5" stroke="#ef4444" stroke-width="1.8" stroke-dasharray="4,2.5"/></svg>',
            },
            {
                key: 'resamples',
                label: 'Resample markers',
                svg: '<svg class="uncertainty-legend-swatch" width="14" height="12" viewBox="0 0 14 12" aria-hidden="true"><line x1="5" y1="1" x2="5" y2="11" stroke="rgba(249, 115, 22, 0.85)" stroke-width="1.6" stroke-dasharray="2,2"/><line x1="10" y1="1" x2="10" y2="11" stroke="rgba(249, 115, 22, 0.85)" stroke-width="1.6" stroke-dasharray="2,2"/></svg>',
            },
        ];

        const buttons = new Map();
        function syncButtons() {
            items.forEach(({ key }) => {
                const btn = buttons.get(key);
                if (!btn) return;
                const active = Boolean(overlayState[key]);
                btn.classList.toggle('is-hidden', !active);
                btn.setAttribute('aria-pressed', active ? 'true' : 'false');
            });
        }

        items.forEach((item) => {
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'uncertainty-legend-item';
            btn.title = 'Click to toggle across all cards; double-click to isolate';
            btn.innerHTML = `${item.svg}<span>${item.label}</span>`;
            btn.addEventListener('click', () => {
                overlayState[item.key] = !overlayState[item.key];
                syncButtons();
                onOverlayChange();
            });
            btn.addEventListener('dblclick', (ev) => {
                ev.preventDefault();
                const activeKeys = items.filter((it) => overlayState[it.key]).map((it) => it.key);
                const onlyThisActive = activeKeys.length === 1 && activeKeys[0] === item.key;
                items.forEach((it) => {
                    overlayState[it.key] = onlyThisActive ? true : (it.key === item.key);
                });
                syncButtons();
                onOverlayChange();
            });
            buttons.set(item.key, btn);
            legendBar.appendChild(btn);
        });

        syncButtons();
        row.appendChild(legendBar);
        return row;
    }

    // Vertical markers at every SMC resample+jitter step, shared by every chart that
    // plots per-step uncertainty (Posterior Evolution's mini-charts and the
    // Convergence tab's per-parameter cards) so a sharp uncertainty jump reads the
    // same way everywhere: it lands *on* a resample (a decaying fraction of particles
    // redrawn from the prior briefly dominates sigma), not before it.
    function _resampleMarkerShapes(resampledSteps, yref) {
        return Array.from(resampledSteps || []).map((s) => ({
            type: 'line',
            x0: s, x1: s,
            y0: 0, y1: 1,
            yref: yref || 'paper',
            line: { color: 'rgba(249, 115, 22, 0.6)', width: 1.5, dash: 'dot' },
        }));
    }

    async function renderParameterConvergence(container, jsonPath, onReady, crlbJsonPath, posteriorJsonPath) {
        container.innerHTML = '<div style="padding:1em;color:#64748b;text-align:center;">Loading…</div>';

        let data;
        try {
            data = await _fetchJson(jsonPath);
        } catch (e) {
            container.innerHTML = `<div style="padding:1em;color:#ef4444;">Failed to load convergence data: ${escapeHtml(String(e.message))}</div>`;
            return;
        }

        if (data.schema !== 'parameter_convergence_v1' || !data.steps) {
            container.innerHTML = '<div style="padding:1em;color:#64748b;">No convergence data.</div>';
            return;
        }
        if (!container.isConnected) return;

        // CRLB overlay (optional — older runs / non-SMC beliefs have no fisher data).
        let fisherData = null;
        if (crlbJsonPath) {
            try {
                const fd = await _fetchJson(crlbJsonPath);
                if (fd && fd.schema === 'fisher_v1' && fd.steps) fisherData = fd;
            } catch (e) { /* CRLB overlay is optional — ignore load failures */ }
        }

        // Resample+jitter markers (optional — same posterior_v1 payload Posterior
        // Evolution uses, so the two tabs agree on exactly which steps resampled).
        let resampledSteps = null;
        if (posteriorJsonPath) {
            try {
                const pd = await _fetchJson(posteriorJsonPath);
                if (pd && pd.schema === 'posterior_v1' && pd.resampled_steps) resampledSteps = pd.resampled_steps;
            } catch (e) { /* optional overlay — ignore load failures */ }
        }

        await ensurePlotly();
        if (!container.isConnected) return;

        const { param_names, param_units, true_params, steps, convergence_threshold, absolute_thresholds } = data;
        const xs = steps.map((_, i) => i);
        const COLORS = ['#1e90ff', '#e05c00', '#00a878', '#9b59b6', '#e74c3c', '#2ecc71', '#f39c12'];

        const traces = [];
        param_names.forEach((param, ci) => {
            const color = COLORS[ci % COLORS.length];
            const unit = param_units[param] ? ` (${param_units[param]})` : '';
            const uncerts = steps.map((s) => s.uncertainties[param] ?? null);
            traces.push({
                type: 'scatter', x: xs, y: uncerts,
                mode: 'lines', name: `${param}${unit}${paramLetterSuffix(param)} σ`,
                line: { color, width: 2 },
            });
            if (true_params && true_params[param] != null) {
                traces.push({
                    type: 'scatter', x: [xs[0], xs[xs.length - 1]], y: [true_params[param], true_params[param]],
                    mode: 'lines', name: `${param} true`,
                    line: { color, width: 1, dash: 'dot' },
                    showlegend: false,
                });
            }
            // Convergence-limit threshold — this schema (unlike convergence_metrics_v1)
            // has no physical bounds, so only the absolute-threshold case (plus the
            // long-standing frequency special-case) can be drawn accurately; a fractional
            // threshold would need bound width, which isn't available here.
            let threshVal = absolute_thresholds ? absolute_thresholds[param] : null;
            if (threshVal == null && param === 'zero_field_freq') threshVal = 100000.0;
            if (threshVal != null) {
                traces.push({
                    type: 'scatter', x: [xs[0], xs[xs.length - 1]], y: [threshVal, threshVal],
                    mode: 'lines', name: `${param} convergence limit`,
                    line: { color: '#ef4444', width: 1.2, dash: 'dash' },
                    showlegend: false,
                });
            }
            // Cramér-Rao lower bound overlay, when Fisher data is available for this run.
            if (fisherData) {
                const crlbVals = steps.map((_, i) => {
                    const fs = fisherData.steps[i];
                    return (fs && fs.fisher_bounds && fs.fisher_bounds[param] != null) ? fs.fisher_bounds[param] : null;
                });
                if (crlbVals.some((v) => v !== null)) {
                    traces.push({
                        type: 'scatter', x: xs, y: crlbVals,
                        mode: 'lines', name: `${param} CRLB (achieved)`,
                        line: { color, width: 1.2, dash: 'dot' },
                        // Unlike the true-value/threshold reference traces above, CRLB
                        // isn't self-explanatory from a dotted line alone — show it in
                        // the legend so "what's the dotted line" doesn't need asking.
                    });
                }
                // Oracle CRLB: the hard information limit for an ideal, uniformly-sampled
                // design at the true parameters -- distinct from crlbVals above, which is
                // derived from this run's own actual measurements and estimates.
                const oracleCrlbVals = steps.map((_, i) => {
                    const fs = fisherData.steps[i];
                    return (fs && fs.oracle_crlb && fs.oracle_crlb[param] != null) ? fs.oracle_crlb[param] : null;
                });
                if (oracleCrlbVals.some((v) => v !== null)) {
                    traces.push({
                        type: 'scatter', x: xs, y: oracleCrlbVals,
                        mode: 'lines', name: `${param} CRLB (oracle)`,
                        line: { color, width: 1.2, dash: 'dashdot' },
                    });
                }
            }
        });

        // Independent of the Posterior Evolution/Fisher tabs' own log-scale toggles.
        let logScale = false;
        // Manual drag-zoom tracking (Plotly's uirevision doesn't preserve it here
        // either, since every step supplies its own explicit yaxis directive rather
        // than pure autorange — see the fuller explanation in renderPosterior).
        let zoomRange = null;
        let zoomBound = false;
        let lastScaleModeForZoom = logScale;

        function buildLayout() {
            return {
                template: 'plotly_white',
                margin: { l: 60, r: 20, t: 20, b: 50 },
                xaxis: { title: 'Step' },
                yaxis: logScale
                    ? { title: 'Uncertainty (log)', type: 'log', range: zoomRange, autorange: zoomRange ? false : true }
                    : { title: 'Uncertainty' },
                legend: { orientation: 'h', y: -0.25 },
                height: 320,
            };
        }

        container.innerHTML = '';
        container.appendChild(_logScaleToggle(logScale, (v) => { logScale = v; updateStep(lastStepIdx); }));
        const plotDiv = document.createElement('div');
        container.appendChild(plotDiv);

        let lastStepIdx = 0;
        function updateStep(stepIdx) {
            lastStepIdx = stepIdx;
            if (lastScaleModeForZoom !== logScale) {
                lastScaleModeForZoom = logScale;
                zoomRange = null;
            }
            const activeStep = xs[Math.max(0, Math.min(stepIdx, xs.length - 1))];
            const updatedLayout = {
                ...buildLayout(),
                shapes: [
                    ..._resampleMarkerShapes(resampledSteps),
                    {
                        type: 'line',
                        x0: activeStep,
                        x1: activeStep,
                        y0: 0,
                        y1: 1,
                        yref: 'paper',
                        line: {
                            color: 'rgba(59, 130, 246, 0.8)',
                            width: 2,
                            dash: 'solid'
                        }
                    }
                ]
            };
            Plotly.react(plotDiv, traces, updatedLayout, { responsive: true, displayModeBar: false });

            if (!zoomBound) {
                zoomBound = true;
                plotDiv.on('plotly_relayout', (ev) => {
                    if (ev['yaxis.range']) {
                        zoomRange = ev['yaxis.range'].slice();
                    } else if (ev['yaxis.range[0]'] !== undefined && ev['yaxis.range[1]'] !== undefined) {
                        zoomRange = [ev['yaxis.range[0]'], ev['yaxis.range[1]']];
                    } else if (ev['yaxis.autorange']) {
                        zoomRange = null;
                    }
                });
            }
        }

        updateStep(0);

        const adapter = {
            contentWindow: {
                showFrame: updateStep,
                totalFrames: xs.length,
                stepValues: xs,
            },
            addEventListener: () => {},
        };
        if (onReady) onReady(adapter);
    }

    async function renderConvergenceMetrics(container, jsonPath, onReady, crlbJsonPath, posteriorJsonPath) {
        container.innerHTML = '<div style="padding:1em;color:#64748b;text-align:center;">Loading…</div>';

        let data;
        try {
            data = await _fetchJson(jsonPath);
        } catch (e) {
            container.innerHTML = `<div style="padding:1em;color:#ef4444;">Failed to load metrics: ${escapeHtml(String(e.message))}</div>`;
            return;
        }

        if (data.schema !== 'convergence_metrics_v1' || !data.steps) {
            container.innerHTML = '<div style="padding:1em;color:#64748b;">No convergence metrics.</div>';
            return;
        }

        // CRLB overlay (optional — older runs / non-SMC beliefs have no fisher data).
        // fisher_v1's actual_uncertainty is the same per-step uncertainty quantity as
        // convergence_metrics_v1's uncertainties, so fisher_bounds needs no unit conversion.
        let fisherData = null;
        if (crlbJsonPath) {
            try {
                const fd = await _fetchJson(crlbJsonPath);
                if (fd && fd.schema === 'fisher_v1' && fd.steps) fisherData = fd;
            } catch (e) { /* CRLB overlay is optional — ignore load failures */ }
        }

        // Resample+jitter markers (optional — same posterior_v1 payload Posterior
        // Evolution uses, so both tabs mark exactly the same steps).
        let resampledSteps = null;
        if (posteriorJsonPath) {
            try {
                const pd = await _fetchJson(posteriorJsonPath);
                if (pd && pd.schema === 'posterior_v1' && pd.resampled_steps) resampledSteps = pd.resampled_steps;
            } catch (e) { /* optional overlay — ignore load failures */ }
        }
        if (!container.isConnected) return;

        await ensurePlotly();
        if (!container.isConnected) return;

        const { param_names, param_units, convergence_threshold, steps, param_bounds } = data;
        const xs = steps.map((s) => s.step);
        const COLORS = ['#1e90ff', '#e05c00', '#00a878', '#9b59b6', '#e74c3c', '#2ecc71', '#f39c12'];

        // Helper to format float numbers cleanly
        function formatNum(val) {
            if (val === null || val === undefined) return '';
            if (Math.abs(val - Math.round(val)) < 1e-4) {
                return Math.round(val).toString();
            }
            return parseFloat(val.toFixed(3)).toString();
        }

        // Compute per-parameter streaks dynamically
        const paramStreaks = {};
        param_names.forEach(p => {
            paramStreaks[p] = [];
            let currentStreak = 0;
            for (let s = 0; s < steps.length; s++) {
                const isConv = steps[s].converged_params[p];
                if (isConv) {
                    currentStreak++;
                } else {
                    currentStreak = 0;
                }
                paramStreaks[p].push(currentStreak);
            }
        });

        container.innerHTML = '';
        // Independent of the Posterior Evolution/Fisher tabs' own log-scale toggles.
        let logScale = false;
        const overlayState = {
            uncertainty: true,
            crlb: true,
            oracleCrlb: true,
            threshold: true,
            resamples: true,
        };
        container.appendChild(_uncertaintyControlsRow(
            logScale,
            (v) => { logScale = v; updateStep(lastStepIdx); },
            overlayState,
            () => {
                paramPlotContexts.forEach((entry) => { entry.zoomRange = null; });
                updateStep(lastStepIdx);
            }
        ));

        // Build cards stack for parameters
        const paramPlotContexts = [];
        param_names.forEach((param, ci) => {
            const wrapper = document.createElement('div');
            wrapper.className = 'convergence-card';
            wrapper.style.cssText = 'background:#ffffff; border:1px solid #e2e8f0; border-radius:8px; padding:12px; margin-bottom:12px; box-shadow:0 1px 2px rgba(0,0,0,0.05); display:flex; flex-direction:column; width:100%; box-sizing:border-box;';
            
            // Header
            const header = document.createElement('div');
            header.style.cssText = 'display:flex; justify-content:space-between; align-items:center; margin-bottom:8px; flex-wrap:wrap; gap:8px;';
            
            // Title Info (Left)
            const infoDiv = document.createElement('div');
            infoDiv.style.cssText = 'display:flex; flex-direction:column;';
            
            const titleSpan = document.createElement('span');
            titleSpan.style.cssText = 'font-weight:600; font-size:0.9em; color:#1e293b;';
            const isAbs = data.absolute_thresholds && data.absolute_thresholds[param] != null;
            const uncTypeStr = isAbs ? 'absolute uncertainty, KHz' : 'relative uncertainty';
            titleSpan.textContent = `${param}${paramLetterSuffix(param)} (${uncTypeStr})`;
            
            const subtitleSpan = document.createElement('span');
            subtitleSpan.style.cssText = 'font-size:0.75em; color:#64748b; margin-top:2px;';
            
            // Calculate bounds and width text
            let boundsText = '';
            if (param_bounds && param_bounds[param]) {
                const [lo, hi] = param_bounds[param];
                const width = hi - lo;
                const bUnit = param_units[param] || '';
                boundsText = `bounds: [${formatNum(lo)}, ${formatNum(hi)}] ${bUnit} (width=${formatNum(width)} ${bUnit})`;
            }
            subtitleSpan.textContent = boundsText;
            
            infoDiv.appendChild(titleSpan);
            infoDiv.appendChild(subtitleSpan);
            header.appendChild(infoDiv);
            
            // Badge (Right)
            const badgeSpan = document.createElement('span');
            header.appendChild(badgeSpan);
            
            wrapper.appendChild(header);
            
            // Plot div
            const plotDiv = document.createElement('div');
            plotDiv.style.cssText = 'width:100%; height:180px;';
            wrapper.appendChild(plotDiv);
            
            container.appendChild(wrapper);
            
            // Calculate raw histories
            const vals = steps.map(s => s.uncertainties[param] ?? null);
            const color = COLORS[ci % COLORS.length];
            
            // Pre-calculate contiguous converged ranges for shaded rects
            const convergedRanges = [];
            let rangeStart = null;
            for (let s = 0; s < steps.length; s++) {
                const isConv = steps[s].converged_params[param];
                if (isConv) {
                    if (rangeStart === null) rangeStart = s;
                } else {
                    if (rangeStart !== null) {
                        convergedRanges.push([rangeStart, s - 1]);
                        rangeStart = null;
                    }
                }
            }
            if (rangeStart !== null) {
                convergedRanges.push([rangeStart, steps.length - 1]);
            }
            
            const crlbVals = fisherData
                ? steps.map((_, i) => {
                    const fs = fisherData.steps[i];
                    return (fs && fs.fisher_bounds && fs.fisher_bounds[param] != null) ? fs.fisher_bounds[param] : null;
                })
                : null;
            // Oracle CRLB: the hard information limit for an ideal, uniformly-sampled
            // design at the true parameters -- distinct from crlbVals above, which is
            // derived from this run's own actual measurements and estimates.
            const oracleCrlbVals = fisherData
                ? steps.map((_, i) => {
                    const fs = fisherData.steps[i];
                    return (fs && fs.oracle_crlb && fs.oracle_crlb[param] != null) ? fs.oracle_crlb[param] : null;
                })
                : null;

            paramPlotContexts.push({
                param,
                plotDiv,
                badgeSpan,
                vals,
                crlbVals,
                oracleCrlbVals,
                color,
                convergedRanges,
                isAbs,
                bounds: param_bounds ? param_bounds[param] : null,
                zoomRange: null,
                zoomBound: false,
            });
        });

        // Overall Convergence Streak Card at the bottom
        const streakWrapper = document.createElement('div');
        streakWrapper.className = 'convergence-card';
        streakWrapper.style.cssText = 'background:#ffffff; border:1px solid #e2e8f0; border-radius:8px; padding:12px; margin-bottom:12px; box-shadow:0 1px 2px rgba(0,0,0,0.05); display:flex; flex-direction:column; width:100%; box-sizing:border-box;';
        
        const streakHeader = document.createElement('div');
        streakHeader.style.cssText = 'display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;';
        
        const streakTitle = document.createElement('span');
        streakTitle.style.cssText = 'font-weight:600; font-size:0.9em; color:#1e293b;';
        streakTitle.textContent = 'Overall Convergence Streak';
        streakHeader.appendChild(streakTitle);
        
        const streakBadge = document.createElement('span');
        streakHeader.appendChild(streakBadge);
        
        streakWrapper.appendChild(streakHeader);
        
        const streakPlotDiv = document.createElement('div');
        streakPlotDiv.style.cssText = 'width:100%; height:180px;';
        streakWrapper.appendChild(streakPlotDiv);
        
        container.appendChild(streakWrapper);
        
        const streakHistory = steps.map(s => s.convergence_streak ?? 0);

        let lastStepIdx = 0;
        // See the matching comment in renderPosterior: Plotly's uirevision doesn't
        // preserve a manual drag-zoom here either, since every step supplies its own
        // explicit range, so it's tracked by hand via zoomRange/zoomBound on each
        // paramPlotContexts entry instead.
        let lastScaleModeForZoom = logScale;
        function updateStep(stepIdx) {
            lastStepIdx = stepIdx;
            const idx = Math.max(0, Math.min(stepIdx, steps.length - 1));
            const activeStepVal = xs[idx];
            const patience = data.convergence_patience || 8;

            if (lastScaleModeForZoom !== logScale) {
                lastScaleModeForZoom = logScale;
                paramPlotContexts.forEach((entry) => { entry.zoomRange = null; });
            }

            // 1. Update individual parameter cards
            paramPlotContexts.forEach((ctx) => {
                const { param, plotDiv, badgeSpan, vals, crlbVals, oracleCrlbVals, color, convergedRanges, isAbs, bounds } = ctx;
                const isConvEnd = steps[steps.length - 1].converged_params[param];
                const isConvCurrent = steps[idx].converged_params[param];
                const streak = paramStreaks[param][idx];
                
                const endBg = isConvEnd ? '#dcfce7' : '#fee2e2';
                const endColor = isConvEnd ? '#15803d' : '#b91c1c';
                const endBorder = isConvEnd ? '1px solid #bbf7d0' : '1px solid #fca5a5';
                const endLabel = isConvEnd ? 'CONVERGED (FINAL)' : 'NOT CONVERGED (FINAL)';

                const currBg = isConvCurrent ? '#dcfce7' : '#fee2e2';
                const currColor = isConvCurrent ? '#15803d' : '#b91c1c';
                const currBorder = isConvCurrent ? '1px solid #bbf7d0' : '1px solid #fca5a5';
                const currLabel = isConvCurrent ? 'CONVERGED (NOW)' : 'NOT CONVERGED (NOW)';

                badgeSpan.innerHTML = `
                    <span style="background-color:${endBg}; color:${endColor}; padding:3px 8px; border-radius:4px; font-weight:600; font-size:0.75em; border: ${endBorder}; margin-right:6px;">${endLabel}</span>
                    <span style="background-color:${currBg}; color:${currColor}; padding:3px 8px; border-radius:4px; font-weight:600; font-size:0.75em; border: ${currBorder}; margin-right:6px;">${currLabel}</span>
                    <span style="font-size:0.85em; color:#475569;">Streak: <strong>${streak}</strong> / ${patience} steps</span>
                `;

                const traces = [];
                if (overlayState.uncertainty) {
                    traces.push({
                        type: 'scatter',
                        x: xs,
                        y: vals,
                        mode: 'lines',
                        name: 'Uncertainty (σ)',
                        line: { color: color, width: 2 },
                        hoverinfo: 'skip',
                        showlegend: false,
                    });
                }

                // Cramér-Rao lower bound overlay, when Fisher data is available for this run.
                if (overlayState.crlb && crlbVals && crlbVals.some(v => v !== null)) {
                    traces.push({
                        type: 'scatter',
                        x: xs,
                        y: crlbVals,
                        mode: 'lines',
                        name: 'CRLB (achieved)',
                        line: { color: '#9333ea', width: 1.5, dash: 'dot' },
                        hoverinfo: 'skip',
                        showlegend: false,
                    });
                }

                // Oracle CRLB: absolute best any acquisition could do with the same
                // number of measurements (ideal placement, true parameters) -- a hard
                // floor, distinct from the achieved (data-driven) CRLB above.
                if (overlayState.oracleCrlb && oracleCrlbVals && oracleCrlbVals.some(v => v !== null)) {
                    traces.push({
                        type: 'scatter',
                        x: xs,
                        y: oracleCrlbVals,
                        mode: 'lines',
                        name: 'CRLB (oracle)',
                        line: { color: '#059669', width: 1.5, dash: 'dashdot' },
                        hoverinfo: 'skip',
                        showlegend: false,
                    });
                }

                // Resample+jitter markers, drawn first so the converged-range shading
                // and current-step line layer on top when they coincide — same
                // convention as Posterior Evolution's mini-charts.
                const shapes = overlayState.resamples ? [..._resampleMarkerShapes(resampledSteps)] : [];

                // Shaded green rects for converged ranges
                convergedRanges.forEach(([start, end]) => {
                    shapes.push({
                        type: 'rect',
                        xref: 'x',
                        yref: 'paper',
                        x0: start,
                        x1: end,
                        y0: 0,
                        y1: 1,
                        fillcolor: 'rgba(34, 197, 94, 0.35)',
                        line: { width: 0 }
                    });
                });

                // Vertical active step indicator
                shapes.push({
                    type: 'line',
                    x0: activeStepVal,
                    x1: activeStepVal,
                    y0: 0,
                    y1: 1,
                    yref: 'paper',
                    line: { color: 'rgba(59, 130, 246, 0.8)', width: 2 }
                });

                // Red dashed line for the threshold
                let threshVal = null;
                let thresholdLabel = '';

                if (isAbs) {
                    threshVal = data.absolute_thresholds ? data.absolute_thresholds[param] : null;
                    if (threshVal === null && param === 'zero_field_freq') {
                        threshVal = 100000.0;
                    }
                    thresholdLabel = `${formatNum(threshVal / 1000)} KHz threshold`;
                } else {
                    threshVal = data.convergence_threshold != null ? data.convergence_threshold : 0.01;
                    thresholdLabel = `threshold (${formatNum(threshVal)})`;
                    
                    // 100% bound line
                    if (overlayState.threshold) {
                        shapes.push({
                            type: 'line',
                            x0: xs[0],
                            x1: xs[xs.length - 1],
                            y0: 1.0,
                            y1: 1.0,
                            line: { color: 'rgba(100,100,100,0.65)', width: 1.2, dash: 'dash' }
                        });
                    }
                }

                if (traces.length === 0) {
                    traces.push({
                        type: 'scatter',
                        x: [xs[0], xs[xs.length - 1]],
                        y: [threshVal || 1, threshVal || 1],
                        mode: 'markers',
                        marker: { opacity: 0 },
                        hoverinfo: 'skip',
                        showlegend: false,
                    });
                }

                if (overlayState.threshold && threshVal !== null) {
                    shapes.push({
                        type: 'line',
                        x0: xs[0],
                        x1: xs[xs.length - 1],
                        y0: threshVal,
                        y1: threshVal,
                        line: { color: '#ef4444', width: 1.5, dash: 'dash' }
                    });
                }

                const annotations = [];
                if (overlayState.threshold && threshVal !== null) {
                    annotations.push({
                        x: xs[xs.length - 1],
                        y: threshVal,
                        xref: 'x',
                        yref: 'y',
                        text: thresholdLabel,
                        showarrow: false,
                        xanchor: 'right',
                        yanchor: 'bottom',
                        font: { size: 9, color: '#b91c1c' }
                    });
                }

                if (overlayState.threshold && !isAbs) {
                    annotations.push({
                        x: xs[xs.length - 1],
                        y: 1.0,
                        xref: 'x',
                        yref: 'y',
                        text: '100% of bound',
                        showarrow: false,
                        xanchor: 'right',
                        yanchor: 'bottom',
                        font: { size: 9, color: 'rgba(71,85,105,0.85)' }
                    });
                }

                if (overlayState.crlb && crlbVals) {
                    const firstIdx = crlbVals.findIndex((v) => v != null);
                    if (firstIdx !== -1) {
                        annotations.push({
                            x: xs[firstIdx],
                            y: crlbVals[firstIdx],
                            xref: 'x',
                            yref: 'y',
                            text: 'CRLB (achieved)',
                            showarrow: false,
                            xanchor: 'left',
                            yanchor: 'top',
                            font: { size: 9, color: '#9333ea' }
                        });
                    }
                }

                if (overlayState.oracleCrlb && oracleCrlbVals) {
                    const firstIdx = oracleCrlbVals.findIndex((v) => v != null);
                    if (firstIdx !== -1) {
                        annotations.push({
                            x: xs[firstIdx],
                            y: oracleCrlbVals[firstIdx],
                            xref: 'x',
                            yref: 'y',
                            text: 'CRLB (oracle)',
                            showarrow: false,
                            xanchor: 'left',
                            yanchor: 'bottom',
                            font: { size: 9, color: '#059669' }
                        });
                    }
                }

                // Add Plotly CONVERGED badge if converged at the active step
                const activeLinearVals = [];
                if (overlayState.uncertainty) activeLinearVals.push(...vals.filter(v => v !== null));
                if (overlayState.threshold && threshVal !== null) activeLinearVals.push(isAbs ? threshVal : 1.0);
                if (activeLinearVals.length === 0) {
                    if (overlayState.crlb && crlbVals) activeLinearVals.push(...crlbVals.filter(v => v !== null));
                    if (overlayState.oracleCrlb && oracleCrlbVals) activeLinearVals.push(...oracleCrlbVals.filter(v => v !== null));
                }
                const maxVal = activeLinearVals.length > 0 ? Math.max(...activeLinearVals) : 1.0;
                const yMax = maxVal > 0 ? maxVal * 1.05 : 1.1;

                if (isConvCurrent) {
                    annotations.push({
                        x: xs[xs.length - 1],
                        y: yMax * 0.9,
                        xref: 'x',
                        yref: 'y',
                        text: 'CONVERGED',
                        showarrow: false,
                        xanchor: 'right',
                        yanchor: 'top',
                        font: { size: 10, color: '#15803d', weight: 'bold' },
                        bgcolor: '#dcfce7',
                        bordercolor: '#bbf7d0',
                        borderwidth: 1,
                        borderpad: 4,
                        opacity: 0.95
                    });
                }

                // Plain autorange only looks at trace data, so — same fix as
                // renderPosterior's mini-charts — fold the threshold and CRLB into an
                // explicit range too, or they can silently fall outside the view (most
                // easily seen on a run that hasn't converged yet, since then every
                // plotted uncertainty sits above the threshold).
                let logRange = null;
                if (logScale) {
                    if (ctx.zoomRange) {
                        logRange = ctx.zoomRange;
                    } else {
                        const positiveVals = overlayState.uncertainty ? vals.filter((v) => v != null && v > 0) : [];
                        if (overlayState.crlb && crlbVals) positiveVals.push(...crlbVals.filter((v) => v != null && v > 0));
                        if (overlayState.oracleCrlb && oracleCrlbVals) positiveVals.push(...oracleCrlbVals.filter((v) => v != null && v > 0));
                        if (overlayState.threshold && threshVal !== null && threshVal > 0) positiveVals.push(threshVal);
                        if (positiveVals.length > 0) {
                            const lo = Math.log10(Math.min(...positiveVals));
                            const hi = Math.log10(Math.max(...positiveVals));
                            const pad = Math.max((hi - lo) * 0.08, 0.05);
                            logRange = [lo - pad, hi + pad];
                        }
                    }
                }

                const yTitle = `${isAbs ? 'Absolute' : 'Relative'} uncertainty${logScale ? ' (log)' : ''}`;
                const layout = {
                    template: 'plotly_white',
                    margin: { l: 45, r: 15, t: 15, b: 35 },
                    xaxis: { title: { text: 'Step', font: { size: 10 } }, tickfont: { size: 9 } },
                    yaxis: logScale
                        ? { title: { text: yTitle, font: { size: 10 } }, tickfont: { size: 9 }, type: 'log', range: logRange, autorange: logRange ? false : true }
                        : { title: { text: yTitle, font: { size: 10 } }, tickfont: { size: 9 }, range: [0, yMax], rangemode: 'tozero' },
                    height: 180,
                    hovermode: false,
                    shapes: shapes,
                    annotations: annotations,
                };

                Plotly.react(plotDiv, traces, layout, { responsive: true, displayModeBar: false });

                // Capture a manual drag-zoom so the next step's Plotly.react call above
                // re-applies it via ctx.zoomRange instead of the computed logRange (see
                // the matching note in renderPosterior).
                if (!ctx.zoomBound) {
                    ctx.zoomBound = true;
                    plotDiv.on('plotly_relayout', (ev) => {
                        if (ev['yaxis.range']) {
                            ctx.zoomRange = ev['yaxis.range'].slice();
                        } else if (ev['yaxis.range[0]'] !== undefined && ev['yaxis.range[1]'] !== undefined) {
                            ctx.zoomRange = [ev['yaxis.range[0]'], ev['yaxis.range[1]']];
                        } else if (ev['yaxis.autorange']) {
                            ctx.zoomRange = null;
                        }
                    });
                }
            });

            // 2. Update Streak Plot
            const currentStreak = streakHistory[idx];
            const isAchieved = currentStreak >= patience;
            
            const streakBg = isAchieved ? '#dcfce7' : '#f1f5f9';
            const streakTextColor = isAchieved ? '#15803d' : '#475569';
            const streakLabel = isAchieved ? 'ACHIEVED' : 'IN PROGRESS';
            const streakBorder = isAchieved ? '1px solid #bbf7d0' : '1px solid #cbd5e1';
            
            streakBadge.innerHTML = `<span style="background-color:${streakBg}; color:${streakTextColor}; padding:3px 8px; border-radius:4px; font-weight:600; font-size:0.75em; border: ${streakBorder};">${streakLabel}</span> <span style="font-size:0.85em; color:#475569; margin-left:6px;">Current Streak: <strong>${currentStreak}</strong> / ${patience} steps</span>`;

            const streakTraces = [{
                type: 'scatter',
                x: xs,
                y: streakHistory,
                mode: 'lines',
                line: { color: '#6366f1', width: 2 },
                hoverinfo: 'skip',
                showlegend: false
            }];

            const streakShapes = [
                {
                    type: 'line',
                    x0: xs[0],
                    x1: xs[xs.length - 1],
                    y0: patience,
                    y1: patience,
                    line: { color: '#ef4444', width: 1.5, dash: 'dash' }
                },
                {
                    type: 'line',
                    x0: activeStepVal,
                    x1: activeStepVal,
                    y0: 0,
                    y1: 1,
                    yref: 'paper',
                    line: { color: 'rgba(59, 130, 246, 0.8)', width: 2 }
                }
            ];

            const streakAnnotations = [{
                x: xs[xs.length - 1],
                y: patience,
                xref: 'x',
                yref: 'y',
                text: `patience (${patience} steps)`,
                showarrow: false,
                xanchor: 'right',
                yanchor: 'bottom',
                font: { size: 9, color: '#b91c1c' }
            }];

            const streakLayout = {
                template: 'plotly_white',
                margin: { l: 45, r: 15, t: 15, b: 35 },
                xaxis: { title: { text: 'Step', font: { size: 10 } }, tickfont: { size: 9 } },
                yaxis: {
                    title: { text: 'Consecutive converged steps', font: { size: 10 } },
                    tickfont: { size: 9 },
                    range: [0, Math.max(...streakHistory, patience) * 1.15],
                    rangemode: 'tozero'
                },
                height: 180,
                hovermode: false,
                shapes: streakShapes,
                annotations: streakAnnotations
            };

            Plotly.react(streakPlotDiv, streakTraces, streakLayout, { responsive: true, displayModeBar: false });
        }

        updateStep(0);
        setTimeout(() => {
            window.dispatchEvent(new Event('resize'));
        }, 50);

        const adapter = {
            contentWindow: {
                showFrame: updateStep,
                totalFrames: xs.length,
                stepValues: xs,
            },
            addEventListener: () => {},
        };
        if (onReady) onReady(adapter);
    }

    async function renderFisher(container, jsonPath) {
        container.innerHTML = '<div style="padding:1em;color:#64748b;text-align:center;">Loading…</div>';

        let data;
        try {
            data = await _fetchJson(jsonPath);
        } catch (e) {
            container.innerHTML = `<div style="padding:1em;color:#ef4444;">Failed to load Fisher data: ${escapeHtml(String(e.message))}</div>`;
            return;
        }

        if (data.schema !== 'fisher_v1' || !data.steps) {
            container.innerHTML = '<div style="padding:1em;color:#64748b;">No Fisher information data.</div>';
            return;
        }
        if (!container.isConnected) return;

        await ensurePlotly();
        if (!container.isConnected) return;

        const { param_names, param_units, steps } = data;
        const xs = steps.map((_, i) => i);
        const COLORS = ['#1e90ff', '#e05c00', '#00a878', '#9b59b6', '#e74c3c', '#2ecc71', '#f39c12'];

        // Independent of the Posterior Evolution/Convergence tabs' own log-scale
        // toggles. Declared outside draw() (rather than inside renderFisher's top,
        // which would re-fetch on every toggle) so it survives the toggle's redraw.
        let logScale = false;
        draw();

        function draw() {
        // One subplot per parameter: CRLB (lower bound) vs actual uncertainty
        container.innerHTML = '';
        const outer = document.createElement('div');
        outer.appendChild(_logScaleToggle(logScale, (v) => { logScale = v; draw(); }));
        const grid = document.createElement('div');
        grid.style.cssText = 'display:flex; flex-wrap:wrap; gap:8px; margin-top:8px;';
        outer.appendChild(grid);
        container.appendChild(outer);

        for (const [ci, param] of param_names.entries()) {
            const unit = param_units[param] ? ` (${param_units[param]})` : '';
            const color = COLORS[ci % COLORS.length];

            const crlb = steps.map((s) => s.fisher_bounds[param] ?? null);
            const actual = steps.map((s) => s.actual_uncertainty[param] ?? null);
            // Oracle CRLB: the hard information limit for an ideal, uniformly-sampled
            // design at the true parameters -- distinct from `crlb` above, which is
            // derived from this run's own actual measurements and estimates.
            const oracleCrlb = steps.map((s) => (s.oracle_crlb ? (s.oracle_crlb[param] ?? null) : null));

            const traces = [
                {
                    type: 'scatter', x: xs, y: actual,
                    mode: 'lines', name: 'Actual σ',
                    line: { color, width: 2 },
                },
                {
                    type: 'scatter', x: xs, y: crlb,
                    mode: 'lines', name: 'CRLB (achieved)',
                    line: { color, width: 1.5, dash: 'dash' },
                    fill: 'tonexty', fillcolor: `${color}22`,
                },
            ];
            if (oracleCrlb.some((v) => v != null)) {
                traces.push({
                    type: 'scatter', x: xs, y: oracleCrlb,
                    mode: 'lines', name: 'CRLB (oracle)',
                    line: { color: '#059669', width: 1.5, dash: 'dashdot' },
                });
            }

            const layout = {
                template: 'plotly_white',
                margin: { l: 55, r: 10, t: 28, b: 40 },
                title: { text: param + unit + paramLetterSuffix(param), font: { size: 11 }, y: 0.96 },
                xaxis: { title: { text: 'Step', font: { size: 10 } } },
                yaxis: logScale
                    ? { title: { text: 'Uncertainty (log)', font: { size: 10 } }, type: 'log', autorange: true }
                    : { title: { text: 'Uncertainty', font: { size: 10 } }, rangemode: 'tozero' },
                showlegend: ci === 0,
                legend: { orientation: 'h', y: -0.3 },
                height: 240,
            };

            const wrapper = document.createElement('div');
            wrapper.style.cssText = 'flex:1; min-width:200px; max-width:420px;';
            grid.appendChild(wrapper);
            Plotly.react(wrapper, traces, layout, { displayModeBar: false, responsive: true });
        }
        }
    }

    // ---- End JSON-based render functions ----

    function renderJitterView(container, jitterPlot) {
        if (!container || !jitterPlot) return;

        const jitter = jitterPlot.jitter || {};
        const variances = jitterPlot.variances || {};
        const correlations = jitterPlot.correlations || {};
        const paramNames = Object.keys(jitter);

        const jitterItems = paramNames.map(name => ({
            label: name,
            val: formatMetricValue(jitter[name]),
            tip: 'Standard deviation of estimates over last 20 steps (physical units).',
            rawVal: jitter[name]
        }));

        const varItems = Object.keys(variances).length > 0
            ? paramNames.map(name => ({ label: name, val: formatMetricValue(variances[name]), rawVal: variances[name] }))
            : [];

        // Jitter cards row
        let html = '<h4>Jitter (last 20 steps)</h4>';
        html += '<div class="jitter-cards">' + renderItemsToHtml(jitterItems) + '</div>';

        // Variance cards row
        if (varItems.length > 0) {
            html += '<h4>Final Variances (diag Σ)</h4>';
            html += '<div class="jitter-cards">' + renderItemsToHtml(varItems) + '</div>';
        }

        // Correlation matrix — full-width block, not inside the card grid
        if (Object.keys(correlations).length > 0) {
            html += '<h4>Correlation Matrix <span class="help-icon" tabindex="0" title="Measures how tightly parameters are coupled. +1/-1 = perfect correlation; 0 = independent.">?</span></h4>';
            html += '<div class="correlation-table-wrapper"><table class="correlation-table">';
            html += '<thead><tr><th></th>' + paramNames.map(n => `<th>${escapeHtml(n)}</th>`).join('') + '</tr></thead>';
            html += '<tbody>';
            for (const ni of paramNames) {
                html += `<tr><th>${escapeHtml(ni)}</th>`;
                for (const nj of paramNames) {
                    const val = (correlations[ni] && correlations[ni][nj] !== undefined) ? correlations[ni][nj] : 0;
                    let color, textColor;
                    if (ni === nj) {
                        color = 'rgba(71, 85, 105, 0.15)';
                        textColor = '#1e293b';
                    } else if (val > 0) {
                        color = `rgba(30, 144, 255, ${0.1 + 0.9 * val})`;
                        textColor = val > 0.4 ? '#ffffff' : '#1e3a8a';
                    } else {
                        color = `rgba(239, 68, 68, ${0.1 + 0.9 * Math.abs(val)})`;
                        textColor = Math.abs(val) > 0.4 ? '#ffffff' : '#7f1d1d';
                    }
                    html += `<td class="corr-cell" style="background-color:${color}; color:${textColor};">${val.toFixed(2)}</td>`;
                }
                html += '</tr>';
            }
            html += '</tbody></table></div>';
        }

        container.innerHTML = html;
    }

    function renderItemsToHtml(items, useSliders = false) {
        return items.map(it => {
            const tipAttr = it.tip ? ' title="' + it.tip.replace(/"/g, '&quot;') + '"' : '';
            const icon = it.tip ? '<span class="help-icon" tabindex="0"' + tipAttr + '>?</span>' : '';

            let valueHtml;
            if (Array.isArray(it.table)) {
                valueHtml = '<table class="metric-mini-table"><thead><tr>' +
                    it.table.map(c => '<th>' + escapeHtml(c.label) + '</th>').join('') +
                    '</tr></thead><tbody><tr>' +
                    it.table.map(c => '<td>' + c.val + '</td>').join('') +
                    '</tr></tbody></table>';
            } else if (it.table && Array.isArray(it.table.rows)) {
                const cols = it.table.columns || [];
                valueHtml = '<table class="metric-mini-table metric-mini-table-multirow"><thead><tr><th></th>' +
                    cols.map(c => '<th>' + escapeHtml(c) + '</th>').join('') +
                    '</tr></thead><tbody>' +
                    it.table.rows.map(r => '<tr' + (r.rowClass ? ' class="' + r.rowClass + '"' : '') + '><th>' + escapeHtml(r.label) + '</th>' +
                        r.vals.map(v => '<td>' + v + '</td>').join('') + '</tr>').join('') +
                    '</tbody></table>';
            } else {
                valueHtml = '<div class="metric-value">' + it.val + '</div>';
            }

            if (useSliders && it.bounds && typeof it.rawVal === 'number') {
                const lo = it.bounds[0];
                const hi = it.bounds[1];
                const percent = Math.min(100, Math.max(0, (it.rawVal - lo) / (hi - lo) * 100));

                let markersHtml = '<div class="param-range-marker" title="True Value: ' + it.val + '" style="left: ' + percent + '%; background-color: #2563eb; z-index: 10;"></div>';

                if (typeof it.finalEst === 'number' && Number.isFinite(it.finalEst)) {
                    const finalPct = Math.min(100, Math.max(0, (it.finalEst - lo) / (hi - lo) * 100));
                    const formattedFinal = it.name && (it.name.toLowerCase().includes('freq') || it.name.toLowerCase().includes('hwhm') || it.name.toLowerCase().includes('hyperfine_shift') || it.name === 'fwhm_total' || it.name === 'sigma_inhom') ? formatHz(it.finalEst) : it.finalEst.toFixed(3);
                    markersHtml += '<div class="param-range-marker" title="Final Inferred: ' + formattedFinal + '" style="left: ' + finalPct + '%; background-color: #ef4444; width: 8px; height: 8px; z-index: 9;"></div>';
                }

                if (typeof it.primaryAtMilestone === 'number' && Number.isFinite(it.primaryAtMilestone)) {
                    const fbPct = Math.min(100, Math.max(0, (it.primaryAtMilestone - lo) / (hi - lo) * 100));
                    const formattedPrimary = formatHz(it.primaryAtMilestone);
                    markersHtml += '<div class="param-range-marker" title="Milestone (primary) estimate: ' + formattedPrimary + '" style="left: ' + fbPct + '%; background-color: #f59e0b; width: 8px; height: 8px; z-index: 8;"></div>';
                }

                valueHtml =
                    '<div class="metric-value">' + it.val + '</div>' +
                    '<div class="param-range-container">' +
                    '<div class="param-range-track">' +
                    markersHtml +
                    '</div>' +
                    '<div class="param-range-bounds">' +
                    '<span>' + it.fmtLo + '</span>' +
                    '<span>' + it.fmtHi + '</span>' +
                    '</div>' +
                    '</div>';
            }

            const extraClass = it.cardClass ? ' ' + it.cardClass : '';
            return '<div class="metric-item' + extraClass + '">' +
                '<div class="metric-label">' + it.label + icon + '</div>' +
                valueHtml +
                '</div>';
        }).join('');
    }

    function findOtherStrategyPlots(plot) {
        if (!window.MANIFEST || !plot) return [];
        return window.MANIFEST.filter(p =>
            p.type === 'scan' &&
            p.generator === plot.generator &&
            p.noise === plot.noise &&
            p.repeat === plot.repeat &&
            p.strategy !== plot.strategy
        );
    }

    // Reverse-lookup: entity id (lowercase+underscores) → original strategy string
    const strategyIdMap = new Map(
        [...new Set(scanPlots.map(p => p.strategy))].map(s =>
            [s.toLowerCase().replace(/[^a-z0-9]/g, '_'), s])
    );

    // Overlay B's measurement traces on the primary scan plot (single-repeat view).
    // Uses Plotly.deleteTraces + Plotly.addTraces; traces are tagged with meta.isComparison.
    async function applyComparisonOverlay(entityB) {
        const scanPlotDiv = document.getElementById('scan-plot-div');
        if (!scanPlotDiv || !window.Plotly || scanPlotDiv.style.display === 'none') return;

        // Remove previous comparison traces
        if (Array.isArray(scanPlotDiv.data)) {
            const compIdx = scanPlotDiv.data
                .map((t, i) => (t.meta && t.meta.isComparison) ? i : -1)
                .filter(i => i >= 0);
            if (compIdx.length) await Plotly.deleteTraces(scanPlotDiv, compIdx).catch(() => {});
        }

        if (!entityB || !currentPlot) return;
        const baseId = entityB.id.replace(/_primary$|_conv$/, '');
        const bStrategy = strategyIdMap.get(baseId);
        if (!bStrategy || bStrategy === currentPlot.strategy) return;

        const bPlot = scanPlots.find(p =>
            p.generator === currentPlot.generator &&
            p.noise === currentPlot.noise &&
            p.strategy === bStrategy &&
            p.repeat === currentPlot.repeat
        );
        if (!bPlot || !bPlot.path) return;

        try {
            const bFig = await _fetchJson(bPlot.path);
            if (!bFig || !Array.isArray(bFig.data)) return;

            const MEASUREMENT_NAMES = [
                'measurements (coarse)', 'measurements (inference)',
                'measurements (secondary)', 'measurements (tertiary)',
                'measurements (noisy)', 'locator most likely signal',
                'locator mode belief signal',
            ];
            const isCompTrace = name => name && MEASUREMENT_NAMES.some(n => name.includes(n));

            const toPlain = o => {
                if (o === null || o === undefined) return o;
                if (ArrayBuffer.isView(o)) return Array.from(o);
                if (Array.isArray(o)) return o.map(toPlain);
                if (typeof o === 'object') { const r = {}; for (const k of Object.keys(o)) r[k] = toPlain(o[k]); return r; }
                return o;
            };

            const compTraces = bFig.data
                .filter(t => isCompTrace(t.name))
                .map(t => {
                    const plain = toPlain(t);
                    return {
                        ...plain,
                        name: `${plain.name || ''} (${bStrategy})`,
                        meta: { isComparison: true },
                        opacity: 0.55,
                        marker: plain.marker ? { ...plain.marker, symbol: 'diamond', size: (plain.marker.size || 8) * 0.85 } : undefined,
                        line: plain.line ? { ...plain.line, dash: 'dot', width: (plain.line.width || 2) * 0.8 } : undefined,
                    };
                });

            if (compTraces.length) Plotly.addTraces(scanPlotDiv, compTraces);
        } catch (e) {
            console.warn('applyComparisonOverlay failed:', e);
        }
    }

    let lastSummaryKey = null;
    let lastComparePairIds = { a: null, b: null };
    // Single source of truth for the "savings baseline" strategy, shared across
    // the Highlights, Dashboard, and Noise-metrics views so the choice is set
    // once and stays consistent when switching between them.
    let sharedBaselineStrategy = null;

    // ── Entity helpers ────────────────────────────────────────────────────────
    function _phaseData(p) {
        // Legacy manifest format: nested coarse/fine dicts (pre-slim)
        if (p && p.coarse && p.fine) return p.fine;
        // Slim manifest format: flattened coarse_measurements/fine_measurements
        // For Bayesian 2-phase runs show fine-phase measurement count in comparisons
        if (p && p.fine_measurements != null) return { ...p, measurements: p.fine_measurements };
        return p;
    }
    function _mv(obj, ...keys) {
        if (!obj) return null;
        const m = obj.metrics || {};
        for (const k of keys) {
            if (obj[k] != null) return obj[k];
            if (m[k] != null) return m[k];
        }
        return null;
    }

    function _shortStratLabel(strategy) {
        return strategy
            .replace('Bayesian-', '')
            .replace('SimpleSweep', 'Sweep')
            .replace('GaussianMixture', 'GaussMix');
    }

    function _makeStrategyEntities(d, strategy, isArray, parentPlots) {
        const push = (arr, v) => { if (v != null) arr.push(v); };
        const label = _shortStratLabel(strategy);
        const id = strategy.toLowerCase().replace(/[^a-z0-9]/g, '_');

        if (isArray) {
            const base = {
                id, label,
                steps: [], uncert: [], err: [],
                steps_to_primary: [], uncert_at_primary: [], err_at_primary: [],
                f_spans: [], repeats: [],
                stepsType: 'measurements',
            };
            const primaryConv = {
                id: id + '_primary', label: label + ' primary converged',
                steps: [], uncert: [], err: [],
                steps_to_primary: [], uncert_at_primary: [], err_at_primary: [],
                f_spans: [], repeats: [],
                stepsType: 'steps',
            };
            const allConv = {
                id: id + '_conv', label: label + ' converged',
                steps: [], uncert: [], err: [],
                steps_to_primary: [], uncert_at_primary: [], err_at_primary: [],
                f_spans: [], repeats: [],
                stepsType: 'steps',
            };
            for (let i = 0; i < d.length; i++) {
                const item = d[i];
                const p = parentPlots ? parentPlots[i] : null;
                
                let f_span = null;
                if (p && p.true_params && p.true_params.params) {
                    const params = p.true_params.params;
                    const lw = params.hwhm;
                    const hyperfine_shift = params.hyperfine_shift || 0.0;
                    let domain_width = 5.0e8;
                    if (p.true_params.bounds && p.true_params.bounds.zero_field_freq) {
                        const zero_field_freq_bounds = p.true_params.bounds.zero_field_freq;
                        if (zero_field_freq_bounds.length === 2 && zero_field_freq_bounds[1] > zero_field_freq_bounds[0]) {
                            domain_width = zero_field_freq_bounds[1] - zero_field_freq_bounds[0];
                        }
                    }
                    if (lw && lw > 0) {
                        f_span = Math.max(2.0 * lw, hyperfine_shift + lw) / domain_width;
                    }
                }
                
                const rep = p ? p.repeat : null;

                const base_step = _mv(item, 'measurements');
                if (base_step != null) {
                    base.steps.push(base_step);
                    base.uncert.push(_mv(item, 'uncert'));
                    base.err.push(_mv(item, 'abs_err_x', 'final_err_shift', 'pair_rmse'));
                    base.steps_to_primary.push(_mv(item, 'steps_to_primary', 'primary_converged_step'));
                    base.uncert_at_primary.push(_mv(item, 'uncert_primary_at_milestone'));
                    base.err_at_primary.push(_mv(item, 'err_primary_at_milestone'));
                    base.f_spans.push(f_span);
                    base.repeats.push(rep);
                }

                const primary_step = _mv(item, 'primary_converged_step', 'steps_to_primary');
                if (primary_step != null) {
                    primaryConv.steps.push(primary_step);
                    primaryConv.uncert.push(_mv(item, 'uncert_primary_at_milestone'));
                    primaryConv.uncert_at_primary.push(_mv(item, 'uncert_primary_at_milestone'));
                    primaryConv.err.push(_mv(item, 'err_primary_at_milestone'));
                    primaryConv.f_spans.push(f_span);
                    primaryConv.repeats.push(rep);
                }

                const all_step = _mv(item, 'all_converged_step');
                if (all_step != null) {
                    allConv.steps.push(all_step);
                    allConv.uncert.push(_mv(item, 'uncert'));
                    allConv.err.push(_mv(item, 'abs_err_x', 'final_err_shift', 'pair_rmse'));
                    allConv.f_spans.push(f_span);
                    allConv.repeats.push(rep);
                }
            }
            const results = [];
            if (base.steps.length) results.push(base);
            if (primaryConv.steps.length) results.push(primaryConv);
            if (allConv.steps.length) results.push(allConv);
            return results;
        } else {
            const base = {
                id, label,
                steps:        _mv(d, 'measurements'),
                uncert:       _mv(d, 'uncert'),
                err:          _mv(d, 'abs_err_x', 'final_err_shift', 'pair_rmse'),
                steps_to_primary:  _mv(d, 'steps_to_primary', 'primary_converged_step'),
                uncert_at_primary: _mv(d, 'uncert_primary_at_milestone'),
                err_at_primary:    _mv(d, 'err_primary_at_milestone'),
                stepsType: 'measurements',
            };
            const primaryStep = _mv(d, 'primary_converged_step', 'steps_to_primary');
            const allStep  = _mv(d, 'all_converged_step');
            const results = [base];
            if (primaryStep != null) {
                results.push({
                    id: id + '_primary', label: label + ' primary converged',
                    steps: primaryStep,
                    uncert: _mv(d, 'uncert_primary_at_milestone'),
                    err:    _mv(d, 'err_primary_at_milestone'),
                    steps_to_primary: null, uncert_at_primary: null, err_at_primary: null,
                    stepsType: 'steps',
                });
            }
            if (allStep != null) {
                results.push({
                    id: id + '_conv', label: label + ' converged',
                    steps: allStep,
                    uncert: _mv(d, 'uncert'),
                    err:    _mv(d, 'abs_err_x', 'final_err_shift', 'pair_rmse'),
                    steps_to_primary: null, uncert_at_primary: null, err_at_primary: null,
                    stepsType: 'steps',
                });
            }
            return results;
        }
    }

    function buildRepeatEntities(plot) {
        if (!window.MANIFEST) return [];
        const group = window.MANIFEST.filter(p =>
            p.type === 'scan' &&
            p.generator === plot.generator &&
            p.noise === plot.noise &&
            p.repeat === plot.repeat
        );

        const strategies = [...new Set(group.map(p => p.strategy))].sort(hlStrategyCompare);
        const entities = [];
        for (const strategy of strategies) {
            const p = group.find(q => q.strategy === strategy);
            if (p) entities.push(..._makeStrategyEntities(_phaseData(p), strategy, false));
        }
        return entities;
    }

    // ── Pairwise metric rows ──────────────────────────────────────────────────
    function buildPairwiseRows(eA, eB) {
        const isArr = v => Array.isArray(v);
        const has = v => isArr(v) ? v.length > 0 : v != null;
        const sub = (a, b) => {
            if (!has(a) || !has(b)) return null;
            if (isArr(a) && isArr(b)) {
                const n = Math.min(a.length, b.length);
                return Array.from({length: n}, (_, i) => b[i] - a[i]);
            }
            return (!isArr(a) && !isArr(b)) ? b - a : null;
        };
        // Δ card header — use the full entity labels. CSS (text-overflow:
        // ellipsis) handles any overflow at render time based on the card's
        // actual width, instead of hard-clipping in JS.
        const deltaLabel = `Δ  ${eB.label} − ${eA.label}`;
        const rows = [];
        const addRow = (metric, aVal, bVal, cA, cB, cD, type) => {
            // Every metric should be present for every entity by construction
            // (the backend captures both "at convergence" and "final" snapshots).
            // If you see a row skipped here, it means the backend data-capture
            // gap has reappeared — investigate rather than hide.
            if (!has(aVal) || !has(bVal)) return;
            rows.push({ label: metric, cards: [
                { label: eA.label, sublabel: metric, data: aVal, color: cA, type },
                { label: eB.label, sublabel: metric, data: bVal, color: cB, type },
                { label: deltaLabel, data: sub(aVal, bVal), color: cD, type },
            ]});
        };
        addRow('Steps to completion',       eA.steps,        eB.steps,        '#f472b6','#60a5fa','#22c55e', eA.stepsType || 'measurements');
        addRow('Final primary-parameter uncertainty',eA.uncert,       eB.uncert,       '#a78bfa','#34d399','#f59e0b','frequency');
        addRow('Final primary-parameter error',      eA.err,          eB.err,          '#c084fc','#10b981','#6366f1','frequency');
        addRow('Steps to primary-parameter convergence', eA.steps_to_primary,  eB.steps_to_primary,  '#fb923c','#38bdf8','#a3e635','steps');
        addRow('Uncertainty @ primary conv.',  eA.uncert_at_primary, eB.uncert_at_primary, '#818cf8','#2dd4bf','#fbbf24','frequency');
        addRow('Error @ primary conv.',        eA.err_at_primary,    eB.err_at_primary,    '#d946ef','#4ade80','#f43f5e','frequency');
        return rows;
    }

    // ── Shared selector + card renderer ──────────────────────────────────────
    function entityCriterion(id) {
        // Entity ids end in '_primary' (primary parameter converged) or '_conv' (all converged);
        // no suffix means the full run.
        if (id.endsWith('_primary')) return 'primary';
        if (id.endsWith('_conv')) return 'conv';
        return 'full';
    }

    const SPEED_METRICS = [
        { key: 'steps',       label: 'Steps to completion',        type: 'measurements', color: '#f472b6', deltaColor: '#22c55e' },
        { key: 'steps_to_primary', label: 'Steps to primary-parameter convergence', type: 'steps',        color: '#fb923c', deltaColor: '#a3e635' },
    ];
    const ACCURACY_METRICS = [
        { key: 'uncert_at_primary', label: 'Claimed σ @ primary conv.', type: 'frequency', color: '#818cf8', deltaColor: '#fbbf24' },
        { key: 'uncert',       label: 'Claimed σ (final)',        type: 'frequency', color: '#a78bfa', deltaColor: '#f59e0b' },
    ];
    // Full set kept for backward compat (buildPairwiseRows single-scan view)
    const ENTITY_METRICS = [
        ...SPEED_METRICS,
        ...ACCURACY_METRICS,
        { key: 'err',      label: 'Final primary-parameter error',     type: 'frequency', color: '#c084fc', deltaColor: '#6366f1' },
        { key: 'err_at_primary', label: 'Error @ primary conv.',  type: 'frequency', color: '#d946ef', deltaColor: '#f43f5e' },
    ];

    // Plain sweeps run at several spacings (SimpleSweep-<k>perFWHM = k grid points per FWHM). The pickers list
    // "Sweep" once and offer the spacing in a second dropdown that appears after Sweep is chosen.
    function sweepParts(id) {
        const m = /^simplesweep_(\d+)perfwhm(.*)$/.exec(id || '');
        return m ? { k: Number(m[1]), rest: m[2] } : null;
    }
    function pickerFamilyKey(e) {
        const sp = sweepParts(e.id);
        return sp ? 'simplesweep' + sp.rest : e.id;
    }
    function pickerFamilyLabel(e) {
        return sweepParts(e.id) ? e.label.replace(/-\d+perFWHM/, '') : e.label;
    }

    // One entity picker: a family dropdown (+ a spacing dropdown for the sweep family). Calls onChange when the
    // selection changes by the user; setEntities() swaps the offered entities without notifying.
    function makeEntityPicker(onChange) {
        const box = document.createElement('span');
        box.style.cssText = 'display:inline-flex;gap:0.3em;align-items:center;';
        const fam = document.createElement('select');
        fam.className = 'control-select';
        const spc = document.createElement('select');
        spc.className = 'control-select';
        spc.title = 'Sweep spacing: grid points per FWHM of the dip';
        spc.hidden = true;
        box.appendChild(fam);
        box.appendChild(spc);
        let entities = [];

        const fillSpacing = (preferK) => {
            const key = fam.value;
            const ks = entities.filter(e => pickerFamilyKey(e) === key && sweepParts(e.id))
                .map(e => sweepParts(e.id).k).sort((x, y) => x - y);
            spc.innerHTML = '';
            for (const k of ks) {
                const opt = document.createElement('option');
                opt.value = String(k);
                opt.textContent = `${k} per FWHM`;
                spc.appendChild(opt);
            }
            spc.hidden = ks.length < 2;
            if (ks.length) spc.value = ks.includes(preferK) ? String(preferK) : String(ks[0]);
        };
        const current = () => {
            const key = fam.value;
            if (!spc.hidden || sweepParts((entities.find(e => pickerFamilyKey(e) === key) || {}).id)) {
                const k = Number(spc.value);
                return entities.find(e => pickerFamilyKey(e) === key && (sweepParts(e.id) || {}).k === k) || null;
            }
            return entities.find(e => pickerFamilyKey(e) === key) || null;
        };
        const setEntities = (list, preferId) => {
            entities = list;
            const prevKey = fam.value;
            const prefer = list.find(e => e.id === preferId);
            const wantKey = prefer ? pickerFamilyKey(prefer) : prevKey;
            const wantK = prefer && sweepParts(prefer.id) ? sweepParts(prefer.id).k : Number(spc.value);
            fam.innerHTML = '';
            const seen = new Set();
            for (const e of list) {
                const key = pickerFamilyKey(e);
                if (seen.has(key)) continue;
                seen.add(key);
                const opt = document.createElement('option');
                opt.value = key;
                opt.textContent = pickerFamilyLabel(e);
                fam.appendChild(opt);
            }
            if (seen.has(wantKey)) fam.value = wantKey;
            fillSpacing(wantK);
            fam.disabled = list.length === 0;
        };
        fam.addEventListener('change', () => { fillSpacing(Number(spc.value)); onChange(); });
        spc.addEventListener('change', onChange);
        return { el: box, setEntities, current };
    }

    function buildTwoDropdownSelector(entities, onPairChange, defaultAId, defaultBId) {
        const wrapper = document.createElement('div');
        wrapper.className = 'control-row';
        wrapper.style.cssText = 'gap:0.5em;margin:0.5em 0 0.75em;flex-wrap:wrap;align-items:center;';
        const lbl = document.createElement('span');
        lbl.className = 'control-label';
        lbl.textContent = 'Compare:';
        const vs = document.createElement('span');
        vs.style.cssText = 'padding:0 0.3em;color:#64748b;font-size:0.9em;';
        vs.textContent = 'with';
        const hint = document.createElement('span');
        hint.style.cssText = 'color:#94a3b8;font-size:0.78em;';
        hint.textContent = 'Only pairs with the same stopping criterion are comparable.';

        // B only ever offers entities with the same stopping criterion as A:
        // cross-criterion pairs vary both quality and cost at once and answer
        // neither question, so they are not offered at all.
        const refreshBOptions = (preferId) => {
            const eA = pickerA.current();
            const crit = entityCriterion(eA ? eA.id : '');
            pickerB.setEntities(
                entities.filter(e => (!eA || pickerFamilyKey(e) !== pickerFamilyKey(eA)) && entityCriterion(e.id) === crit
                    || (eA && pickerFamilyKey(e) === pickerFamilyKey(eA) && sweepParts(e.id) && e.id !== eA.id && entityCriterion(e.id) === crit)),
                preferId,
            );
        };
        const notify = () => {
            const eA = pickerA.current();
            const eB = pickerB.current();
            if (eA && eB && eA.id !== eB.id) onPairChange(eA, eB);
        };
        const pickerA = makeEntityPicker(() => { refreshBOptions(); notify(); });
        const pickerB = makeEntityPicker(notify);
        pickerA.setEntities(entities, defaultAId);
        refreshBOptions(defaultBId && defaultBId !== defaultAId ? defaultBId : undefined);
        wrapper.appendChild(lbl);
        wrapper.appendChild(pickerA.el);
        wrapper.appendChild(vs);
        wrapper.appendChild(pickerB.el);
        wrapper.appendChild(hint);
        return { wrapper, notify };
    }

    function renderPairwiseCards(rows, container, isSummary) {
        container.innerHTML = '';
        if (!rows || !rows.length) {
            const p = document.createElement('p');
            p.style.cssText = 'color:#94a3b8;padding:1em 0;font-size:0.9em;';
            p.textContent = 'No shared metrics for this pair.';
            container.appendChild(p);
            return;
        }
        for (const row of rows) {
            const sectionId = 'pairwise-' + row.label.toLowerCase().replace(/[^a-z0-9]/g, '-');
            const isCollapsed = isSectionCollapsed(sectionId);

            const hdr = document.createElement('div');
            hdr.className = 'section-collapsible-header' + (isCollapsed ? ' is-collapsed' : '');
            hdr.style.cssText = 'margin-top:1em;margin-bottom:0.4em;font-weight:600;color:#334155;font-size:0.85em;';
            hdr.setAttribute('role', 'button');
            hdr.setAttribute('tabindex', '0');
            hdr.setAttribute('aria-expanded', String(!isCollapsed));
            hdr.setAttribute('data-section-id', sectionId);
            hdr.setAttribute('title', isCollapsed ? 'Click to expand' : 'Click to collapse');
            hdr.innerHTML = `<span class="section-collapse-arrow" aria-hidden="true">${COLLAPSE_ARROW_SVG}</span><span>${escapeHtml(row.label)}</span>`;
            container.appendChild(hdr);

            const rowDiv = document.createElement('div');
            rowDiv.className = 'scan-metrics-panel' + (isSummary ? ' summary-grid' : '');
            rowDiv.style.marginBottom = '0.75em';
            if (isCollapsed) {
                rowDiv.style.display = 'none';
            }
            container.appendChild(rowDiv);

            const toggle = () => {
                toggleCollapsibleSection(sectionId, hdr, rowDiv);
                hdr.setAttribute('title', hdr.classList.contains('is-collapsed') ? 'Click to expand' : 'Click to collapse');
            };
            hdr.addEventListener('click', toggle);
            hdr.addEventListener('keydown', (e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    toggle();
                }
            });

            for (const card of row.cards) {
                const cardDiv = document.createElement('div');
                cardDiv.className = 'metric-item';
                rowDiv.appendChild(cardDiv);
                const lblDiv = document.createElement('div');
                lblDiv.className = 'metric-label';
                // For entity cards (not the Δ card) show the metric as secondary text
                // so it's always clear what's being shown even when scrolling past the heading
                if (card.sublabel) {
                    lblDiv.title = `${card.label} — ${card.sublabel}`;
                }
                lblDiv.textContent = card.label;
                cardDiv.appendChild(lblDiv);
                if (isSummary) {
                    createCardHistogram(cardDiv, card.data, card.label, card.color, card.type);
                } else {
                    const valEl = document.createElement('div');
                    valEl.className = 'metric-value';
                    const v = card.data;
                    if (v == null) { valEl.textContent = 'N/A'; valEl.style.color = '#94a3b8'; }
                    else if (card.type === 'frequency') valEl.textContent = formatHz(v);
                    else valEl.textContent = formatCount(v);
                    cardDiv.appendChild(valEl);
                }
            }
        }
    }

    function updateStoppingCriteriaVisibility(plot) {
        // "View at" is chosen by clicking a milestone marker on the global timeline
        // (see renderTimelineMilestoneMarkers), so the button row stays hidden.
        const row = document.getElementById('stopping-criteria-row');
        if (row) row.style.display = 'none';
    }

    // Shows, directly under the scan measurements plot, which step/measurement the
    // currently selected "View at" convergence criterion resolves to — the same
    // step the plot's own measurement points are now capped at.
    function updateScanViewAtCaption(plot) {
        const captionEl = document.getElementById('scan-view-at-caption');
        if (!captionEl) return;
        const d = plot ? _phaseData(plot) : null;
        if (!d || currentStoppingCriteria === 'full') {
            captionEl.style.display = 'none';
            captionEl.textContent = '';
            return;
        }
        let step = null;
        let label = '';
        if (currentStoppingCriteria === 'primary_converged') {
            step = _mv(d, 'primary_converged_step', 'steps_to_primary');
            label = 'Primary converged';
        } else if (currentStoppingCriteria === 'all_converged') {
            step = _mv(d, 'all_converged_step');
            label = 'Converged';
        }
        if (step == null) {
            captionEl.style.display = 'none';
            captionEl.textContent = '';
            return;
        }
        const total = _mv(d, 'measurements');
        let text = `Viewing at: ${label} — measurements through step ${formatCount(step)}`;
        if (total != null) text += ` of ${formatCount(total)} total`;
        captionEl.textContent = text;
        captionEl.style.display = '';
    }

    function setStoppingCriteria(value) {
        currentStoppingCriteria = value;
        const group = document.getElementById('scan-stopping-criteria');
        if (group) {
            group.querySelectorAll('button').forEach(b => {
                const active = b.dataset.value === value;
                b.classList.toggle('is-active', active);
                b.setAttribute('aria-checked', String(active));
                b.tabIndex = active ? 0 : -1;
            });
        }
        applyStoppingFrameLimit();
        // Refresh summary plots if the noise-sweep view is visible
        const noiseView = document.getElementById('noise-metrics-view');
        if (noiseView && !noiseView.hidden) {
            updateNoiseSweepPlots(controlValue(scanGenerator));
        }
    }

    function setupRepeatComparisonUI(plot) {
        const selContainer = document.getElementById('scan-comparison-selector');
        const cardContainer = document.getElementById('scan-comparison-cards');
        if (!selContainer || !cardContainer) return;
        selContainer.innerHTML = '';
        cardContainer.innerHTML = '';
        const entities = buildRepeatEntities(plot);
        if (entities.length < 2) return;

        // Determine which entity IDs to pre-select based on stopping criteria and current strategy
        const currentStrategy = plot ? plot.strategy : null;
        const currentId = currentStrategy
            ? currentStrategy.toLowerCase().replace(/[^a-z0-9]/g, '_')
            : null;
        let defaultAId = entities[0].id;
        let defaultBId = entities[1].id;
        if (currentId) {
            const suffix = currentStoppingCriteria === 'primary_converged' ? '_primary'
                         : currentStoppingCriteria === 'all_converged'  ? '_conv'
                         : '';
            const preferred = currentId + suffix;
            const found = entities.find(e => e.id === preferred) || entities.find(e => e.id === currentId);
            if (found) defaultAId = found.id;
            // Pick a different entity for B
            const bEntity = entities.find(e => e.id !== defaultAId);
            if (bEntity) defaultBId = bEntity.id;
        }

        // Also restore saved pair if nothing explicit was computed
        if (!currentId && lastComparePairIds.a) {
            const saved = entities.find(e => e.id === lastComparePairIds.a);
            if (saved) defaultAId = saved.id;
        }
        if (lastComparePairIds.b && entities.find(e => e.id === lastComparePairIds.b && e.id !== defaultAId)) {
            defaultBId = lastComparePairIds.b;
        }

        const { wrapper, notify } = buildTwoDropdownSelector(entities, (eA, eB) => {
            lastComparePairIds = { a: eA.id, b: eB.id };
            renderPairwiseCards(buildPairwiseRows(eA, eB), cardContainer, false);
            applyComparisonOverlay(eB);
        }, defaultAId, defaultBId);
        selContainer.appendChild(wrapper);
        notify();
    }

    function createCardHistogram(cardContainer, data, name, color, unitType = null, height = 140) {
        if (!data || data.length === 0) {
            const empty = document.createElement('div');
            empty.style.cssText = `height:${height}px;display:flex;align-items:center;justify-content:center;color:#94a3b8;font-size:0.9em;font-weight:500;`;
            empty.textContent = 'N/A';
            cardContainer.appendChild(empty);
            return;
        }
        const plotDiv = document.createElement('div');
        plotDiv.style.height = `${height}px`;
        plotDiv.style.width = '100%';
        cardContainer.appendChild(plotDiv);
        let scaledData = data;
        let unit = '';
        if (unitType === 'frequency') {
            let maxAbs = 0;
            for (let i = 0; i < data.length; i++) { const a = Math.abs(data[i]); if (a > maxAbs) maxAbs = a; }
            let factor = 1;
            unit = 'Hz';
            if (maxAbs >= 1e9) { factor = 1e9; unit = 'GHz'; }
            else if (maxAbs >= 1e6) { factor = 1e6; unit = 'MHz'; }
            else if (maxAbs >= 1e3) { factor = 1e3; unit = 'kHz'; }
            scaledData = data.map(v => v != null ? v / factor : null);
        } else if (unitType === 'steps') { unit = 'steps'; }
        else if (unitType === 'measurements') { unit = 'meas.'; }
        else if (unitType === 'ratio') { unit = 'adaptive / sweep'; }

        // Clip the long tail so the populated region fills the axis. These
        // distributions are heavily right-skewed: a fixed-percentile clip still
        // leaves a sparse tail that crushes all the real data into one bar.
        // Use Tukey upper fence (Q3 + 1.5·IQR), which adapts to the skew and
        // trims the tail hard, then bin the kept range into many bins.
        let plotData = scaledData.filter(v => v != null && isFinite(v));
        let binCfg = { autobinx: true };
        let tailNote = null;
        if (plotData.length >= 10) {
            const s = [...plotData].sort((a, b) => a - b);
            const q = f => s[Math.min(s.length - 1, Math.floor(s.length * f))];
            const q1 = q(0.25), q3 = q(0.75), iqr = q3 - q1;
            let lo = Math.max(s[0], q1 - 1.5 * iqr);
            let hi = q3 + 1.5 * iqr;
            // Degenerate skew: when the bulk is a single spike (IQR ≈ 0) the
            // Tukey fence collapses to a zero-width window and the old code fell
            // back to autobin — showing the full impossible tail with every real
            // value crushed into one bar. Fall back to a high percentile so the
            // dense region keeps a visible span; if >95% are identical, walk up
            // to the first strictly-greater value to guarantee non-zero width.
            if (!(hi > lo)) {
                lo = s[0];
                hi = q(0.95);
                if (!(hi > lo)) {
                    const firstBigger = s.find(v => v > lo);
                    hi = firstBigger != null ? firstBigger : lo + (Math.abs(lo) || 1) * 1e-6;
                }
            }
            if (hi > lo) {
                const clipped = plotData.filter(v => v > hi);
                plotData = plotData.filter(v => v >= lo && v <= hi);
                const nbins = 30;
                binCfg = { xbins: { start: lo, end: hi, size: (hi - lo) / nbins } };
                if (clipped.length) {
                    const maxTail = Math.max(...clipped);
                    const fmt = v => Math.abs(v) >= 100 ? v.toFixed(0)
                        : Math.abs(v) >= 1 ? v.toFixed(2) : Number(v.toPrecision(3)).toString();
                    tailNote = `▸ tail ${clipped.length} pt${clipped.length > 1 ? 's' : ''} · max ${fmt(maxTail)}`;
                }
            }
        }

        const histX = plotData;

        Plotly.newPlot(plotDiv, [{
            x: histX, type: 'histogram', name,
            marker: { color, line: { color: 'rgba(255,255,255,0.6)', width: 0.5 } },
            opacity: 0.85, ...binCfg,
        }], {
            margin: { l: 25, r: 10, t: 10, b: 25 },
            xaxis: {
                title: { text: unit, font: { size: 9, color: '#64748b', family: 'system-ui, sans-serif' } },
                tickfont: { size: 8, color: '#64748b' }, showgrid: true, gridcolor: '#f1f5f9', zeroline: true, zerolinecolor: '#cbd5e1',
            },
            yaxis: { tickfont: { size: 8, color: '#64748b' }, showgrid: true, gridcolor: '#f1f5f9' },
            showlegend: false, plot_bgcolor: 'transparent', paper_bgcolor: 'transparent',
            bargap: 0.05, dragmode: false, hovermode: 'x',
            annotations: tailNote ? [{
                xref: 'paper', yref: 'paper', x: 0.98, y: 0.96, xanchor: 'right', yanchor: 'top',
                text: tailNote, showarrow: false,
                font: { size: 8, color: '#94a3b8', family: 'system-ui, sans-serif' },
                bgcolor: 'rgba(255,255,255,0.75)', borderpad: 2,
            }] : [],
        }, { displayModeBar: false, responsive: true });
    }

    // ── Aggregate-view helpers (Step size, Stages, Accuracy) ──────────────────
    const HL_COLORS = ['#2563eb', '#f59e0b', '#10b981', '#8b5cf6', '#ec4899', '#ef4444', '#06b6d4', '#14b8a6'];
    let hlPaceBands = true;   // pale 1σ/2σ/3σ bands on the pace graph; off when strategies' bands overlap too much
    const hlPaceArgs = new Map();   // use-case suffix -> { byStrategy, strategies } of its pace chart

    // The plain (non-adaptive) sweeps: SimpleSweep and its SimpleSweep-d<k> spacings. Smart-Sweep is adaptive.
    function isSweepBaseline(strategy) {
        return /^SimpleSweep/.test(strategy || '');
    }

    // Display order of locators: the SBED family together (plain SBED, its drive variant, Smart-SBED), then
    // Smart-Sweep, then the plain sweeps at their spacings (coarsest first); anything else keeps alphabetical
    // order before them.
    function hlStrategyRank(strategy) {
        const s = strategy || '';
        if (s === 'Bayesian-SBED') return 0;
        if (s === 'Bayesian-SBED-Drive') return 1;
        if (s === 'Smart-SBED') return 2;
        if (s === 'Smart-Sweep') return 3;
        if (isSweepBaseline(s)) return 4;
        return -1;
    }
    function hlStrategyCompare(a, b) {
        const d = hlStrategyRank(a) - hlStrategyRank(b);
        if (d) return d;
        const ka = Number((/(\d+)perFWHM/.exec(a) || [])[1]) || 0;
        const kb = Number((/(\d+)perFWHM/.exec(b) || [])[1]) || 0;
        return ka - kb || a.localeCompare(b);
    }

    function hlSorted(values) {
        return values.filter(v => v != null && isFinite(v)).sort((a, b) => a - b);
    }
    function hlQuantileSorted(sorted, q) {
        if (!sorted.length) return null;
        const pos = (sorted.length - 1) * q;
        const lo = Math.floor(pos), hi = Math.ceil(pos);
        return sorted[lo] + (sorted[hi] - sorted[lo]) * (pos - lo);
    }
    function hlMedian(values) { return hlQuantileSorted(hlSorted(values), 0.5); }

    // Collapse a scatter (xs,ys) into per-bin median + IQR over log-spaced x bins.
    // Returns {cx, med, lo, hi, n} arrays (one entry per non-empty bin with >= minN
    // points), so a dense cloud reads as a trend line with a spread band.
    function hlLogBinMedian(xs, ys, nBins = 25, minN = 3) {
        const pts = [];
        for (let i = 0; i < xs.length; i++) {
            if (xs[i] > 0 && Number.isFinite(ys[i])) pts.push([xs[i], ys[i]]);
        }
        const out = { cx: [], med: [], lo: [], hi: [], n: [] };
        if (pts.length < minN) return out;
        let xmin = Infinity, xmax = -Infinity;
        for (const [x] of pts) { if (x < xmin) xmin = x; if (x > xmax) xmax = x; }
        const lmin = Math.log(xmin), lmax = Math.log(xmax);
        const span = lmax - lmin || 1;
        const bins = Array.from({ length: nBins }, () => []);
        for (const [x, y] of pts) {
            let b = Math.floor(((Math.log(x) - lmin) / span) * nBins);
            if (b >= nBins) b = nBins - 1;
            if (b < 0) b = 0;
            bins[b].push([x, y]);
        }
        for (const bin of bins) {
            if (bin.length < minN) continue;
            const bx = hlSorted(bin.map(p => p[0]));
            const by = hlSorted(bin.map(p => p[1]));
            out.cx.push(hlQuantileSorted(bx, 0.5));
            out.med.push(hlQuantileSorted(by, 0.5));
            out.lo.push(hlQuantileSorted(by, 0.25));
            out.hi.push(hlQuantileSorted(by, 0.75));
            out.n.push(bin.length);
        }
        return out;
    }

    function hlWilson(k, n) {
        if (!n) return null;
        const z = 1.96, p = k / n, z2 = z * z;
        const denom = 1 + z2 / n;
        const center = (p + z2 / (2 * n)) / denom;
        const half = (z * Math.sqrt((p * (1 - p)) / n + z2 / (4 * n * n))) / denom;
        return { p, lo: Math.max(0, center - half), hi: Math.min(1, center + half) };
    }

    // Series helpers — series is {s: steps[], e: errors[], u: uncertainties[], tau}
    function hlSeriesValueAt(series, key, step) {
        const s = series.s, arr = series[key];
        let v = null;
        for (let i = 0; i < s.length && s[i] <= step; i++) {
            if (arr[i] != null) v = arr[i];
        }
        return v;
    }
    function hlFSpan(p) {
        const tp = p.true_params;
        if (!tp || !tp.params) return null;
        const params = tp.params;
        // Lineshape-agnostic width: Lorentzian models use "hwhm", Voigt/
        // saturation-Voigt use "hwhm_lorentz" — mirrors the same
        // fallback chain server-side in nvision/viz/experiments.py's
        // _add_correct_f_span (final_est_hwhm / _hwhm_lorentz /
        // _effective_hwhm), just against ground truth instead of estimates.
        const lw = params.hwhm ?? params.hwhm_lorentz ?? params.effective_hwhm ?? null;
        // Total splitting extent: two Zeeman groups at +/- zeeman_shift, plus
        // any hyperfine shift component — same combination as the Python side.
        const zeeman = params.zeeman_shift || 0.0;
        const hyperfine_shift = (params.hyperfine_shift || 0.0) + zeeman * 2.0;
        let domainWidth = 5.0e8;
        const fb = tp.bounds && tp.bounds.zero_field_freq;
        if (fb && fb.length === 2 && fb[1] > fb[0]) domainWidth = fb[1] - fb[0];
        return (lw && lw > 0) ? Math.max(2.0 * lw, hyperfine_shift + lw) / domainWidth : null;
    }
    function hlRunSteps(p) {
        return p.measurements ?? (p.series && p.series.s.length ? p.series.s[p.series.s.length - 1] : null);
    }
    function sortNoiseLabels(noises) {
        return [...noises].sort((a, b) => {
            const sa = String(a).match(/^SNR\(([\d.e+-]+)\)/);
            const sb = String(b).match(/^SNR\(([\d.e+-]+)\)/);
            if (sa && sb) return parseFloat(sa[1]) - parseFloat(sb[1]);
            const ga = String(a).match(/Gauss\(([\d.]+)\)/);
            const gb = String(b).match(/Gauss\(([\d.]+)\)/);
            if (ga && gb) return parseFloat(ga[1]) - parseFloat(gb[1]);
            if (ga) return -1;
            if (gb) return 1;
            return String(a).localeCompare(String(b));
        });
    }
    function isSuccessRun(p) { return p.failure_reason == null; }

    // Normalizes the aggregate-view "generator" argument (single string in the
    // plain-generator case, array in Width/Contrast-style multi-select) into a
    // Set for membership checks, mirroring the noise-array handling above.
    function toGenSet(gen) {
        return new Set((Array.isArray(gen) ? gen : [gen]).filter(Boolean));
    }

    // series/true_params are stripped from /api/manifest (they're what made it
    // 653MB against a real large cache) and served instead via /api/scan-fields,
    // scoped to whatever generator/noise selection Stages/Accuracy is
    // currently showing. Fetch once per distinct selection and merge in place
    // (mutating the shared scanPlots entries), so hlCollect's existing filtering
    // logic runs completely unchanged against already-enriched data.
    const hlFetchedSelections = new Set();
    function ensureScanFieldsFor(generator, noises) {
        const genList = [...toGenSet(generator)].sort();
        const noiseList = [...new Set((Array.isArray(noises) ? noises : [noises]).filter(Boolean))].sort();
        if (!genList.length || !noiseList.length) return Promise.resolve();
        const key = genList.join(',') + '::' + noiseList.join(',');
        if (hlFetchedSelections.has(key)) return Promise.resolve();
        const params = new URLSearchParams({ generator: genList.join(','), noise: noiseList.join(',') });
        return fetch(`${window.NVISION_ASSET_PREFIX || ''}api/scan-fields?${params}`, { cache: 'no-store' })
            .then((r) => (r.ok ? r.json() : []))
            .then((rows) => {
                for (const row of rows) {
                    const p = scanPlots.find((sp) =>
                        sp.generator === row.generator && sp.noise === row.noise &&
                        sp.strategy === row.strategy && sp.repeat === row.repeat);
                    if (p) {
                        if (row.series != null) p.series = row.series;
                        if (row.true_params != null) p.true_params = row.true_params;
                        // Locator-comparison fields (final error, uncertainty, stage metrics).
                        if (row.compare) p.metrics = { ...(p.metrics || {}), ...row.compare };
                    }
                }
                hlFetchedSelections.add(key);
            })
            .catch(() => { hlFetchedSelections.add(key); });
    }

    function hlCollect(generator, noises) {
        const noiseSet = new Set((Array.isArray(noises) ? noises : [noises]).filter(Boolean));
        const genSet = toGenSet(generator);
        const byStrategy = new Map();
        for (const p of scanPlots) {
            if (!genSet.has(p.generator) || !noiseSet.has(p.noise) || !p.strategy) continue;
            if (p.generator === 'Dummy-Generator') continue;
            if (!isSuccessRun(p)) continue;
            if (!byStrategy.has(p.strategy)) byStrategy.set(p.strategy, []);
            byStrategy.get(p.strategy).push(p);
        }
        return byStrategy;
    }

    function hlStepGrid(maxStep, nPoints = 60) {
        const grid = [];
        const head = Math.min(10, maxStep);
        for (let i = 1; i <= head; i++) grid.push(i);
        if (maxStep > head) {
            const ratio = maxStep / head;
            const rem = Math.max(nPoints - head, 8);
            for (let k = 1; k <= rem; k++) {
                const v = Math.round(head * Math.pow(ratio, k / rem));
                if (v > grid[grid.length - 1]) grid.push(v);
            }
        }
        return grid;
    }

    function hlHslToHex(h, s, l) {
        const a = s * Math.min(l, 1 - l);
        const f = (n) => {
            const k = (n + h / 30) % 12;
            const c = l - a * Math.max(-1, Math.min(k - 3, 9 - k, 1));
            return Math.round(255 * c).toString(16).padStart(2, '0');
        };
        return `#${f(0)}${f(8)}${f(4)}`;
    }

    // The plain sweeps (SimpleSweep-<k>perFWHM) are one method at different spacings, so they share one hue
    // that darkens with k (light = coarsest spacing); every other locator gets its own palette color.
    function hlStratColor(strategies, strategy) {
        if (isSweepBaseline(strategy)) {
            const sweepK = (s) => Number((/(\d+)perFWHM/.exec(s) || [])[1]) || 0;
            const sweeps = strategies.filter(isSweepBaseline).sort((a, b) => sweepK(a) - sweepK(b));
            const frac = sweeps.length > 1 ? sweeps.indexOf(strategy) / (sweeps.length - 1) : 0.5;
            return hlHslToHex(215, 0.5, 0.78 - 0.5 * frac);
        }
        const others = strategies.filter((s) => !isSweepBaseline(s));
        return HL_COLORS[others.indexOf(strategy) % HL_COLORS.length];
    }
    function hlHexToRgba(hex, alpha) {
        const r = parseInt(hex.slice(1, 3), 16), g = parseInt(hex.slice(3, 5), 16), b = parseInt(hex.slice(5, 7), 16);
        return `rgba(${r},${g},${b},${alpha})`;
    }

    const hlBaseLayout = () => ({
        template: 'plotly_white',
        margin: { t: 30, b: 55, l: 65, r: 15 },
        hovermode: 'closest',
        legend: { orientation: 'h', yanchor: 'bottom', y: 1.02, xanchor: 'right', x: 1, font: { size: 10 } },
        xaxis: { gridcolor: '#f1f5f9' },
        yaxis: { gridcolor: '#f1f5f9' },
        plot_bgcolor: 'transparent',
        paper_bgcolor: 'transparent',
    });

    // ── Locators tab ─────────────────────────────────────────────────────────
    // Every locator's measured metrics side by side (each plain-sweep spacing k is its own locator), from
    // /api/run-rows: the per-repeat scalars of every run. A use case is one signal at one noise level (window x
    // line shape x SNR in the SNR x window study). The table has one block per use case of the current selection:
    // a cost, a capped share or a σ coverage is only meaningful within one use case, so nothing is pooled across
    // them. The charts read the whole family against SNR = contrast / noise σ and mark the selected use case.
    // The chips choose which locators are shown; nothing is ranked.
    let ssRowsCache = null;   // { key, promise } of the last /api/run-rows request
    const ssHidden = new Set();   // locators the user switched off (new locators are shown by default)
    const ssOpenCases = new Set();   // use-case blocks of the table the user expanded (they start collapsed)
    // SNR x window study (rows carrying grid_window_fwhm and grid_gaussian_share): one panel per window, ONE line
    // shape (Gaussian share) shown at a time, or with ssCompare one locator's lines for every shape.
    let ssShare = null;       // Gaussian share (rounded, see ssShareKey) the charts show; null = the middle share
    let ssCompare = false;    // "Compare shapes": the lines are the shapes of ssCompareLoc instead of the locators
    let ssCompareLoc = null;  // locator whose shapes are compared; null = the first shown one
    const SS_FWHM_PER_SIGMA = 2 * Math.sqrt(2 * Math.LN2);   // Gaussian FWHM = this x sigma_inhom

    function ssShareKey(row) {
        return row.grid_gaussian_share == null ? null : Math.round(row.grid_gaussian_share * 1e6) / 1e6;
    }

    // Total FWHM (Hz) of a study row: Lorentzian 2 x hwhm_lorentz + Gaussian 2.355 x sigma_inhom.
    function ssTotalFwhm(row) {
        if (row.grid_hwhm == null || row.grid_sigma_inhom == null) return null;
        return 2 * row.grid_hwhm + SS_FWHM_PER_SIGMA * row.grid_sigma_inhom;
    }

    // A shape is named by its Lorentzian share of the FWHM (= 1 - Gaussian share).
    const ssShapeLabel = (share) => `${Math.round(100 * (1 - share))}% Lorentzian`;
    let ssSigmaK = 'all';     // the σ chart counts runs with |error| <= k × claimed σ: 1, 2, 3 or 'all' together
    // Share of a Gaussian within k standard deviations: what a correct claimed σ gives at k = 1, 2, 3.
    const SS_GAUSS_WITHIN = { 1: 0.6827, 2: 0.9545, 3: 0.9973 };

    function ssSpacing(strategy) {
        const m = /^SimpleSweep-(\d+)perFWHM$/.exec(strategy || '');
        return m ? Number(m[1]) : null;
    }

    function ssLabel(strategy) {
        const k = ssSpacing(strategy);
        return k != null ? `Sweep k=${k}` : _shortStratLabel(strategy);
    }

    function ssFetchRows(strategies) {
        const key = [...strategies].sort().join(',');
        if (ssRowsCache && ssRowsCache.key === key) return ssRowsCache.promise;
        const params = new URLSearchParams({ strategies: key });
        const promise = fetch(`${window.NVISION_ASSET_PREFIX || ''}api/run-rows?${params}`, { cache: 'no-store' })
            .then((r) => {
                if (!r.ok) throw new Error(`/api/run-rows returned ${r.status} (the Locators view needs \`nv serve\`)`);
                return r.json();
            });
        ssRowsCache = { key, promise };
        promise.catch(() => { if (ssRowsCache && ssRowsCache.promise === promise) ssRowsCache = null; });
        return promise;
    }

    // A run that produced a cost: it ended by the stop rule or by its measurement budget.
    function ssUsable(row) {
        return (row.failure_reason == null || row.failure_reason === 'max_steps') && row.measurements > 0;
    }

    // A sweep that runs out of measurements still ends as a normal locator stop; what marks it is that the stop
    // rule never fired (no primary_converged_step).
    function ssCapped(row) {
        return row.primary_converged_step == null;
    }

    // SNR = dip contrast / noise σ; Infinity without noise, null when the run records no contrast or noise.
    function ssSnr(row) {
        if (row.snr != null) return row.snr;
        const c = row.grid_contrast_total;
        const s = row.noise_sigma;
        if (c == null || s == null) return null;
        return s > 0 ? c / s : Infinity;
    }

    // |z| = |reported estimate − truth| / claimed σ at the end of the run; null without a usable σ.
    function ssAbsZ(row) {
        const e = row.final_err_primary, u = row.uncert;
        return e != null && u > 0 && isFinite(u) && isFinite(e) ? e / u : null;
    }

    function ssQuantiles(values) {
        const sorted = hlSorted(values);
        return { n: sorted.length, med: hlQuantileSorted(sorted, 0.5), q75: hlQuantileSorted(sorted, 0.75) };
    }

    function ssSegmented(group, onPick) {
        if (!group || group._hasListener) return;
        group.addEventListener('click', (e) => {
            const btn = e.target.closest('button[data-value]');
            if (!btn) return;
            group.querySelectorAll('button').forEach((b) => {
                const active = b === btn;
                b.classList.toggle('is-active', active);
                b.setAttribute('aria-checked', active ? 'true' : 'false');
                b.tabIndex = active ? 0 : -1;
            });
            onPick(btn.dataset.value);
            renderStepSizeTab();
        });
        group._hasListener = true;
    }

    // Sweep spacings the current code studies (/api/sweep-spacings); older spacings in the cache come from older code.
    let ssSpacingsPromise = null;
    function ssCurrentSpacings() {
        if (!ssSpacingsPromise) {
            ssSpacingsPromise = fetch(`${window.NVISION_ASSET_PREFIX || ''}api/sweep-spacings`, { cache: 'no-store' })
                .then((r) => {
                    if (!r.ok) throw new Error(`/api/sweep-spacings returned ${r.status} (the Locators view needs \`nv serve\`)`);
                    return r.json();
                });
            ssSpacingsPromise.catch(() => { ssSpacingsPromise = null; });
        }
        return ssSpacingsPromise;
    }

    const SS_PANEL_IDS = ['ss-table', 'ss-cost-snr', 'ss-search-snr', 'ss-sigma-snr'];

    function renderStepSizeTab() {
        ssSegmented(document.getElementById('ss-sigma-k'), (v) => { ssSigmaK = v === 'all' ? 'all' : Number(v); });
        ssBindShapeControls();
        const notice = document.getElementById('ss-notice');
        const clear = () => SS_PANEL_IDS.forEach((id) => {
            const el = document.getElementById(id);
            if (el) el.innerHTML = '';
        });
        ssCurrentSpacings()
            .then((current) => renderStepSizeFor(new Set(current), notice, clear))
            .catch((err) => {
                clear();
                notice.innerHTML = `<div style="padding:1em;color:#721c24;background:#f8d7da;border-radius:6px;"><strong>Locators:</strong> ${escapeHtml(String(err.message || err))}</div>`;
            });
    }

    function renderStepSizeFor(currentSpacings, notice, clear) {
        const cached = [...new Set(scanPlots.map((p) => p.strategy))].filter(Boolean);
        const older = cached.filter((s) => ssSpacing(s) != null && !currentSpacings.has(s));
        const strategies = cached.filter((s) => !older.includes(s)).sort(hlStrategyCompare);
        if (!strategies.length) {
            clear();
            notice.innerHTML = '<div style="padding:2em;color:#64748b;text-align:center;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;">No runs in this family.</div>';
            return Promise.resolve();
        }
        // The charts read the whole family (their x axis is SNR, their panels the windows); the table is one block
        // per use case (generator x noise) of the selection made with the signal / noise pickers above.
        const familyGens = new Set(scanPlots.map((p) => p.generator));
        const selGens = toGenSet(compareGeneratorsArg());
        const selNoiseArg = compareNoisesArg();
        const selNoises = new Set((Array.isArray(selNoiseArg) ? selNoiseArg : [selNoiseArg]).filter(Boolean));
        notice.innerHTML = '<div style="color:#64748b;font-size:0.85em;">Loading runs…</div>';
        return ssFetchRows(strategies).then((rows) => {
            const inFamily = rows.filter((r) => familyGens.has(r.generator));
            const isSelected = (r) => selGens.has(r.generator) && selNoises.has(r.noise);
            return ensurePlotly().then(() => renderStepSizeContent(inFamily, isSelected, strategies, older));
        });
    }

    // One toggle chip per locator; clicking shows or hides it in the table and every chart.
    function ssRenderPicker(strategies, colorOf) {
        const box = document.getElementById('ss-pick');
        box.innerHTML = strategies.map((s) => {
            const on = !ssHidden.has(s);
            return `<button type="button" data-strategy="${escapeHtml(s)}" aria-pressed="${on}" title="${escapeHtml(s)}"
                style="border:1px solid ${on ? colorOf(s) : '#cbd5e1'}; background:${on ? hlHexToRgba(colorOf(s), 0.12) : '#fff'};
                color:${on ? '#0f172a' : '#94a3b8'}; border-radius:999px; padding:2px 10px; font-size:0.85em; cursor:pointer;">
                <span style="color:${on ? colorOf(s) : '#cbd5e1'}">●</span> ${escapeHtml(ssLabel(s))}</button>`;
        }).join('');
        if (!box._hasListener) {
            box.addEventListener('click', (e) => {
                const btn = e.target.closest('button[data-strategy]');
                if (!btn) return;
                const s = btn.dataset.strategy;
                if (ssHidden.has(s)) ssHidden.delete(s); else ssHidden.add(s);
                renderStepSizeTab();
            });
            box._hasListener = true;
        }
    }

    // Shape controls of the SNR x window study: a button per Gaussian share (reported as the Lorentzian share of the
    // FWHM), the "Compare shapes" toggle and, while comparing, the locator whose shapes are the lines. Hidden when
    // the runs carry no window / share (older caches).
    function ssBindShapeControls() {
        const box = document.getElementById('ss-shape-box');
        if (!box || box._hasListener) return;
        box.addEventListener('click', (e) => {
            const share = e.target.closest('button[data-share]');
            if (share) { ssShare = Number(share.dataset.share); renderStepSizeTab(); return; }
            if (e.target.closest('button[data-compare]')) { ssCompare = !ssCompare; renderStepSizeTab(); }
        });
        box.addEventListener('change', (e) => {
            if (e.target.id === 'ss-compare-loc') { ssCompareLoc = e.target.value; renderStepSizeTab(); }
        });
        box._hasListener = true;
    }

    // shapes: [{ share, tip }] ascending Gaussian share; selected: the share shown; cmpLoc: the compared locator.
    function ssRenderShapeControls(study, shapes, selected, strategies, cmpLoc) {
        const box = document.getElementById('ss-shape-box');
        if (!study) { box.style.display = 'none'; box.innerHTML = ''; return; }
        box.style.display = 'inline-flex';
        const btn = (s) => `<button type="button" role="radio" aria-checked="${s.share === selected}" data-share="${s.share}"
            class="${s.share === selected ? 'is-active' : ''}" tabindex="${s.share === selected ? 0 : -1}"
            title="${escapeHtml(s.tip)}">${escapeHtml(ssShapeLabel(s.share))}</button>`;
        const options = strategies.map((s) => `<option value="${escapeHtml(s)}"${s === cmpLoc ? ' selected' : ''}>${escapeHtml(ssLabel(s))}</option>`).join('');
        box.innerHTML = `<span class="control-label" style="font-size:0.85em; color:#334155;" title="Lorentzian share of the FWHM = fwhm_L / (fwhm_L + fwhm_G) = 1 − Gaussian share. The total FWHM is the same for every shape.">Line shape</span>
            <div class="segmented-control" role="radiogroup" aria-label="Line shape">${shapes.map(btn).join('')}</div>
            <button type="button" data-compare="1" aria-pressed="${ssCompare}" title="One locator, one line per shape" style="border:1px solid ${ssCompare ? '#2563eb' : '#cbd5e1'}; background:${ssCompare ? '#dbeafe' : '#fff'}; border-radius:999px; padding:2px 10px; font-size:0.85em; cursor:pointer;">Compare shapes</button>
            ${ssCompare ? `<select id="ss-compare-loc" aria-label="Locator whose shapes are compared" style="font-size:0.85em;">${options}</select>` : ''}`;
    }

    // Name of a use case from one of its runs: window, line shape and SNR in the SNR x window study, else the
    // generator and noise names.
    function ssUseCaseLabel(row) {
        const snr = ssSnr(row);
        const snrText = snr == null ? row.noise : `SNR ${snr === Infinity ? '∞' : Number(snr.toPrecision(3))}`;
        if (row.grid_window_fwhm == null || ssShareKey(row) == null) {
            return snr == null ? `${row.generator} · ${row.noise}` : `${row.generator} · ${snrText}`;
        }
        const fwhm = ssTotalFwhm(row);
        const mhz = fwhm == null ? '' : ` (${((row.grid_window_fwhm * fwhm) / 1e6).toFixed(0)} MHz)`;
        return `window ${row.grid_window_fwhm} × FWHM${mhz} · ${ssShapeLabel(ssShareKey(row))} · ${snrText}`;
    }

    // Use cases in reading order: window, line shape, then SNR ascending (older caches: by name).
    function ssUseCaseCompare(a, b) {
        const num = (x, y) => (x === y ? 0 : x == null ? 1 : y == null ? -1 : x - y);
        return num(a.grid_window_fwhm, b.grid_window_fwhm) || num(ssShareKey(a), ssShareKey(b))
            || num(ssSnr(a), ssSnr(b)) || a.generator.localeCompare(b.generator) || a.noise.localeCompare(b.noise);
    }

    function renderStepSizeContent(rows, isSelected, strategies, olderStrategies) {
        const notice = document.getElementById('ss-notice');
        const colorOf = (s) => hlStratColor(strategies, s);
        const config = { responsive: true, displaylogo: false };
        ssRenderPicker(strategies, colorOf);
        const shown = strategies.filter((s) => !ssHidden.has(s));

        const usableAll = rows.filter(ssUsable);
        // The SNR x window study: runs that carry both a window and a Gaussian share. Without them (older caches)
        // there is one panel and no shape controls.
        const windows = [...new Set(usableAll.map((r) => r.grid_window_fwhm).filter((v) => v != null))].sort((a, b) => a - b);
        const shares = [...new Set(usableAll.map(ssShareKey).filter((v) => v != null))].sort((a, b) => a - b);
        const study = windows.length > 0 && shares.length > 0;
        const usable = study ? usableAll.filter((r) => r.grid_window_fwhm != null && ssShareKey(r) != null) : usableAll;
        // The charts show one line shape: the one picked here, else the selected use case's, else the middle one.
        const selected = usable.filter(isSelected);
        const selShares = [...new Set(selected.map(ssShareKey).filter((v) => v != null))];
        const shareSel = shares.includes(ssShare) ? ssShare
            : (selShares.length === 1 ? selShares[0] : shares[Math.floor(shares.length / 2)]);
        const cmpLoc = strategies.includes(ssCompareLoc) ? ssCompareLoc : (shown[0] || strategies[0]);
        const shapeRow = (share) => usable.find((r) => ssShareKey(r) === share);
        const shapeTip = (share) => {
            const r = shapeRow(share);
            const fwhm = r && ssTotalFwhm(r);
            return `Gaussian share ${share}; hwhm_lorentz ${r && r.grid_hwhm != null ? (r.grid_hwhm / 1e6).toFixed(3) : '?'} MHz, `
                + `sigma_inhom ${r && r.grid_sigma_inhom != null ? (r.grid_sigma_inhom / 1e6).toFixed(3) : '?'} MHz`
                + (fwhm != null ? `, total FWHM ${(fwhm / 1e6).toFixed(2)} MHz` : '');
        };
        const windowMHz = (n) => {
            const fwhm = ssTotalFwhm(usable.find((r) => r.grid_window_fwhm === n));
            return fwhm == null ? null : (n * fwhm) / 1e6;
        };
        ssRenderShapeControls(study, shares.map((s) => ({ share: s, tip: shapeTip(s) })), shareSel, strategies, cmpLoc);

        // Every usable run per locator over the family (the charts pick a window / shape from it).
        const byAll = new Map(strategies.map((s) => [s, usable.filter((r) => r.strategy === s)]));
        const failed = rows.length - usableAll.length;
        const noWindow = usableAll.length - usable.length;
        const noSnr = usable.filter((r) => ssSnr(r) == null).length;
        const ended = (r) => !ssCapped(r);

        // Table: the measured metrics per shown locator, one block per use case (generator x noise) selected.
        const useCases = new Map();
        for (const r of selected) {
            const key = `${r.generator}\u0000${r.noise}`;
            if (!useCases.has(key)) useCases.set(key, { sample: r, runs: [] });
            useCases.get(key).runs.push(r);
        }
        const blocks = [...useCases.values()].sort((a, b) => ssUseCaseCompare(a.sample, b.sample));
        const fmtN = (v) => (v == null ? '–' : formatCount(Math.round(v)));
        const th = (text, tip) => `<th title="${tip}">${text}</th>`;
        const COLS = 10;
        // The table numbers of one locator over one use case's runs.
        const statsOf = (runs) => {
            const cost = ssQuantiles(runs.map((r) => r.measurements));
            const found = runs.filter((r) => r.focus_found_step != null);
            const z = runs.filter(ended).map(ssAbsZ).filter((v) => v != null);
            const within = (m) => (z.length ? z.filter((v) => v <= m).length / z.length : null);
            return {
                runs: runs.length, cost: cost.med, p75: cost.q75, capped: runs.filter(ssCapped).length / runs.length,
                found: found.length / runs.length, search: ssQuantiles(found.map((r) => r.focus_found_step)).med,
                w1: within(1), w2: within(2), w3: within(3),
            };
        };
        const pct = (v) => (v == null ? '–' : `${Math.round(100 * v)}%`);
        const rowHtml = (st, x) => `<tr>
                <td style="text-align:left;font-weight:600;" title="${escapeHtml(st)}"><span style="color:${colorOf(st)}">●</span> ${escapeHtml(ssLabel(st))}</td>
                <td>${fmtN(x.runs)}</td><td>${fmtN(x.cost)}</td><td>${fmtN(x.p75)}</td><td>${pct(x.capped)}</td>
                <td>${pct(x.found)}</td><td>${fmtN(x.search)}</td><td>${pct(x.w1)}</td><td>${pct(x.w2)}</td><td>${pct(x.w3)}</td>
            </tr>`;
        // A locator that was not run on a use case has no row there.
        const bodyOf = (block) => shown.map((st) => {
            const runs = block.runs.filter((r) => r.strategy === st);
            return runs.length ? rowHtml(st, statsOf(runs)) : '';
        }).join('');
        // Several use cases selected: a first block with each number the median over the use cases' own numbers.
        // Only use cases every shown locator has runs on, so the locators are summarised over the same use cases.
        const pairedBlocks = blocks.filter((b) => shown.every((st) => b.runs.some((r) => r.strategy === st)));
        const medianBodyOf = () => shown.map((st) => {
            const perCase = pairedBlocks.map((b) => b.runs.filter((r) => r.strategy === st)).map(statsOf);
            if (!perCase.length) return '';
            const x = {};
            for (const key of ['runs', 'cost', 'p75', 'capped', 'found', 'search', 'w1', 'w2', 'w3']) {
                x[key] = hlMedian(perCase.map((c) => c[key]));
            }
            return rowHtml(st, x);
        }).join('');
        const medianRow = `<tr><td colspan="${COLS}" style="text-align:left;font-weight:600;color:#1e3a8a;background:#eff6ff;border-top:1px solid #bfdbfe;">Median over ${formatCount(pairedBlocks.length)}${pairedBlocks.length < blocks.length ? ` of ${formatCount(blocks.length)}` : ''} use cases${pairedBlocks.length < blocks.length ? ' (those every shown locator has runs on)' : ''} (runs = per use case)</td></tr>`;
        const useCaseRow = (block) => `<tr><td colspan="${COLS}" style="text-align:left;font-weight:600;color:#334155;background:#f8fafc;border-top:1px solid #e2e8f0;" title="${escapeHtml(`${block.sample.generator} · ${block.sample.noise}`)}">${escapeHtml(ssUseCaseLabel(block.sample))}</td></tr>`;
        const tableDiv = document.getElementById('ss-table');
        tableDiv.innerHTML = shown.length && blocks.length ? `<table class="hl-stop-table" style="border-collapse:collapse;font-size:0.85em;text-align:right;">
            <thead><tr style="color:#64748b;border-bottom:1px solid #e2e8f0;">
                <th style="text-align:left;">Locator</th>
                ${th('Runs', 'Runs of this use case that ended by the stop rule or the budget')}
                ${th('Median cost', 'Median measurements per run')}
                ${th('p75 cost', '75th percentile of measurements per run')}
                ${th('Capped', 'Share of runs that hit the measurement budget before the stop rule fired')}
                ${th('Dip found', 'Share of runs whose data ever showed a dip')}
                ${th('Search', 'Median measurements until a dip was seen')}
                ${th('|error| ≤ 1σ', 'Share of runs the stop rule ended whose real error is within the claimed σ; a correct σ gives 68%')}
                ${th('|error| ≤ 2σ', 'Same within 2σ; a correct σ gives 95%')}
                ${th('|error| ≤ 3σ', 'Same within 3σ; a correct σ gives 99.7%')}
            </tr></thead>${blocks.length > 1 ? `<tbody>${medianRow}${medianBodyOf()}</tbody>` : ''}${blocks.map((b) => {
                // Several use cases: each block starts collapsed to its header (the median block above is the summary).
                const key = `${b.sample.generator}\u0000${b.sample.noise}`;
                const collapsed = blocks.length > 1 && !ssOpenCases.has(key);
                return `<tbody class="ss-case${collapsed ? ' collapsed' : ''}" data-case="${escapeHtml(key)}">${useCaseRow(b)}${bodyOf(b)}</tbody>`;
            }).join('')}</table>`
            : '<div style="padding:1em;color:#64748b;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;">No runs for the selected signal and noise.</div>';
        tableDiv.querySelectorAll('td, th').forEach((c) => { c.style.padding = '4px 12px'; });
        if (!tableDiv._hasListener) {
            // The header row of a use-case block expands / collapses it.
            tableDiv.addEventListener('click', (e) => {
                const header = e.target.closest('tbody.ss-case > tr:first-child');
                if (!header) return;
                const body = header.parentElement;
                const collapsed = body.classList.toggle('collapsed');
                if (collapsed) ssOpenCases.delete(body.dataset.case); else ssOpenCases.add(body.dataset.case);
            });
            tableDiv._hasListener = true;
        }

        const parts = [`${formatCount(usable.length)} runs in the family`];
        if (document.getElementById('stepsize-view').style.display !== 'none') parts.push(`table: ${blocks.length === 1 ? ssUseCaseLabel(blocks[0].sample) : `median over ${formatCount(blocks.length)} selected use cases, then each on its own`}`);
        if (failed) parts.push(`${formatCount(failed)} failed (left out)`);
        if (noWindow) parts.push(`${formatCount(noWindow)} without a window / line shape (left out)`);
        if (study) parts.push(`charts: ${ssShapeLabel(shareSel)}`);
        if (noSnr) parts.push(`${formatCount(noSnr)} without contrast/noise (left out of the SNR charts)`);
        const counts = (b) => strategies.map((s) => b.runs.filter((r) => r.strategy === s).length).filter((n) => n > 0);
        if (blocks.some((b) => new Set(counts(b)).size > 1)) parts.push('<b style="color:#b45309" title="The locators have different numbers of runs">run in progress</b>');
        if (olderStrategies.length) parts.push(`<span title="No longer a studied spacing: its cached results come from older code">hidden: ${olderStrategies.map(escapeHtml).join(', ')}</span>`);
        notice.innerHTML = `<div style="color:#64748b;font-size:0.85em;">${parts.join(' · ')}</div>`;

        // SNR axis shared by the charts: log scale, with the noise-free runs at 2× the largest finite SNR as "∞".
        const finiteSnrs = hlSorted([...new Set(usable.map(ssSnr).filter((v) => v != null && isFinite(v)))]);
        const xInf = finiteSnrs.length ? finiteSnrs[finiteSnrs.length - 1] * 2 : 1;
        const snrX = (s) => (s === Infinity ? xInf : s);
        const ticks = [];
        if (finiteSnrs.length) {
            const lo = finiteSnrs[0], hi = finiteSnrs[finiteSnrs.length - 1];
            for (let e = Math.floor(Math.log10(lo)); e <= Math.ceil(Math.log10(hi)); e++) {
                for (const m of [1, 2, 5]) {
                    const v = m * 10 ** e;
                    if (v >= lo / 1.5 && v <= hi * 1.2) ticks.push(v);
                }
            }
        }
        const hasInf = usable.some((r) => ssSnr(r) === Infinity);
        const xaxis = {
            title: 'SNR (contrast / noise σ)', type: 'log',
            tickvals: [...ticks, ...(hasInf ? [xInf] : [])],
            ticktext: [...ticks.map((v) => String(v)), ...(hasInf ? ['∞'] : [])],
        };
        // One panel per window (the SNR x window study; one panel otherwise). The lines are the shown locators at the
        // selected shape, or with "Compare shapes" one locator at every shape.
        const panelValues = study ? windows : [null];
        const shapeColors = new Map(shares.map((sh, i) => [sh, HL_COLORS[i % HL_COLORS.length]]));
        const lineSpecs = study && ssCompare
            ? shares.map((sh) => ({ st: cmpLoc, name: ssShapeLabel(sh), color: shapeColors.get(sh), group: `shape-${sh}`, share: sh, extra: shapeTip(sh) }))
            : shown.map((st) => ({ st, name: ssLabel(st), color: colorOf(st), group: st, share: study ? shareSel : null, extra: study ? shapeTip(shareSel) : '' }));

        // One panel per window; each series is { key, valueOf, filter, dash, agg } and gets one line per lineSpec
        // (agg = 'median' (default) or 'mean' of valueOf over the runs at each SNR value). With several series a
        // line's series share one legend entry. refLines: [{ y, label }] faint horizontal references.
        const snrPanels = (containerId, series, yaxis, refLines = []) => {
            const container = document.getElementById(containerId);
            container.innerHTML = '';
            if (!container.offsetParent) return;   // its view is not open: Plotly cannot size a hidden panel
            for (const sv of panelValues) {
                const div = document.createElement('div');
                div.style.cssText = panelValues.length > 1 ? 'flex:1 1 30%; min-width:320px; height:300px;' : 'flex:1 1 100%; height:380px;';
                container.appendChild(div);
                const traces = [];
                const mhz = sv == null ? null : windowMHz(sv);
                const windowTip = sv == null ? '' : `<br>window ${sv} × FWHM${mhz != null ? ` = ${mhz.toFixed(1)} MHz` : ''}`;
                for (const s of series) {
                    for (const spec of lineSpecs) {
                        const st = spec.st;
                        const bySnr = new Map();
                        for (const r of byAll.get(st)) {
                            if (sv != null && r.grid_window_fwhm !== sv) continue;
                            if (spec.share != null && ssShareKey(r) !== spec.share) continue;
                            if (s.filter && !s.filter(r)) continue;
                            const snr = ssSnr(r);
                            const v = s.valueOf(r);
                            if (snr == null || v == null) continue;
                            if (!bySnr.has(snr)) bySnr.set(snr, []);
                            bySnr.get(snr).push(v);
                        }
                        const xs = [...bySnr.keys()].sort((a, b) => a - b);
                        const name = series.length > 1 ? `${spec.name} ${s.key}` : spec.name;
                        const compareTip = study && ssCompare ? `<br>${ssLabel(st)}` : '';
                        const shapeHover = spec.extra ? `<br>${spec.extra.replace(/; /g, '<br>')}` : '';
                        traces.push({
                            type: 'scatter', mode: 'lines+markers', name: spec.name, legendgroup: spec.group,
                            showlegend: sv === panelValues[0] && s === series[0],
                            x: xs.map(snrX), y: xs.map((x) => (s.agg === 'mean' ? bySnr.get(x).reduce((a, b) => a + b, 0) / bySnr.get(x).length : hlMedian(bySnr.get(x)))),
                            line: { color: spec.color, width: 2, dash: s.dash || 'solid' }, marker: { size: s.dash ? 4 : 6 },
                            customdata: xs.map((x) => bySnr.get(x).length),
                            hovertemplate: `${name}${compareTip}<br>SNR %{x:.3g}<br>${s.agg === 'mean' ? 'share' : 'median'} %{y:.3g}<br>n = %{customdata}${windowTip}${shapeHover}<extra></extra>`,
                        });
                    }
                }
                // The selected use case: a dotted vertical line at its SNR (in the shape shown, unless comparing shapes).
                const markSnrs = new Set(selected
                    .filter((r) => (sv == null || r.grid_window_fwhm === sv) && (!study || ssCompare || ssShareKey(r) === shareSel))
                    .map(ssSnr).filter((v) => v != null));
                const selectedMarks = [...markSnrs].map((v) => ({ type: 'line', xref: 'x', yref: 'paper', x0: snrX(v), x1: snrX(v), y0: 0, y1: 1, line: { color: '#2563eb', width: 1, dash: 'dot' } }));
                Plotly.react(div, traces, {
                    title: sv == null ? undefined : { text: `window ${sv} × FWHM`, font: { size: 12 } },
                    margin: { l: 60, r: 10, t: sv == null ? 10 : 30, b: 50 },
                    xaxis, yaxis,
                    shapes: selectedMarks.concat(refLines.map((ref) => ({ type: 'line', xref: 'paper', x0: 0, x1: 1, y0: ref.y, y1: ref.y, line: { color: '#94a3b8', width: 1, dash: 'dash' } }))),
                    annotations: refLines.map((ref) => ({ xref: 'paper', x: 1, xanchor: 'right', y: ref.y, yanchor: 'bottom', text: ref.label, showarrow: false, font: { size: 10, color: '#94a3b8' } })),
                    legend: { orientation: 'h', y: -0.3 },
                }, config);
            }
        };
        snrPanels('ss-cost-snr', [{ key: 'cost', valueOf: (r) => r.measurements }], { title: 'measurements per run', type: 'log' });
        snrPanels('ss-search-snr', [{ key: 'search', valueOf: (r) => r.focus_found_step }], { title: 'measurements until a dip', type: 'log' });
        // 1σ solid, 2σ dashed, 3σ dotted; each against the share a correct σ gives.
        const sigmaKs = ssSigmaK === 'all' ? [1, 2, 3] : [ssSigmaK];
        const SIGMA_DASH = { 1: 'solid', 2: 'dash', 3: 'dot' };
        const within = (k) => (r) => { const z = ssAbsZ(r); return z == null ? null : (z <= k ? 1 : 0); };
        snrPanels('ss-sigma-snr',
            sigmaKs.map((k) => ({ key: `${k}σ`, valueOf: within(k), filter: ended, agg: 'mean', dash: k === 1 ? undefined : SIGMA_DASH[k] })),
            { title: sigmaKs.length > 1 ? 'share with |error| ≤ 1σ (solid), 2σ (dashed), 3σ (dotted)' : `share with |error| ≤ ${sigmaKs[0]}σ claimed`, range: [0, 1.02] },
            sigmaKs.map((k) => ({ y: SS_GAUSS_WITHIN[k], label: `${k}σ: ${(100 * SS_GAUSS_WITHIN[k]).toFixed(k === 3 ? 1 : 0)}%` })));
    }

    // ── Use cases: Stages and Accuracy are one block per selected use case ───
    // A use case is one signal at one noise level (generator x noise). Its numbers are never pooled with another's,
    // so a selection of several (a window range, an SNR range) renders the view body once per use case.

    // One use case's identity and the fields its label needs, read from a run of it. The SNR of a study noise
    // name `SNR(x)` is taken from the name when the run records none.
    function ucRow(p) {
        const info = (window.NVISION_GENERATOR_GRID_INFO && window.NVISION_GENERATOR_GRID_INFO[p.generator]) || {};
        const get = (k) => { const v = _mv(p, k); return v != null ? v : (info[k] != null ? info[k] : null); };
        const named = /^SNR\(([^)]+)\)$/.exec(p.noise || '');
        return {
            generator: p.generator, noise: p.noise,
            grid_window_fwhm: get('grid_window_fwhm'), grid_gaussian_share: get('grid_gaussian_share'),
            grid_hwhm: get('grid_hwhm'), grid_sigma_inhom: get('grid_sigma_inhom'),
            grid_contrast_total: get('grid_contrast_total'), noise_sigma: get('noise_sigma'),
            snr: get('snr') != null ? get('snr') : (named && isFinite(Number(named[1])) ? Number(named[1]) : null),
        };
    }

    // The use cases (generator x noise with runs) of the selection, in reading order.
    function ucList(gen, noises) {
        const genSet = toGenSet(gen);
        const noiseSet = new Set((Array.isArray(noises) ? noises : [noises]).filter(Boolean));
        const byKey = new Map();
        for (const p of scanPlots) {
            if (!genSet.has(p.generator) || !noiseSet.has(p.noise) || !p.strategy) continue;
            if (p.generator === 'Dummy-Generator') continue;
            const key = `${p.generator}\u0000${p.noise}`;
            if (!byKey.has(key)) byKey.set(key, { generator: p.generator, noise: p.noise, row: ucRow(p) });
        }
        return [...byKey.values()].sort((a, b) => ssUseCaseCompare(a.row, b.row));
    }

    // 'median': a selection of several use cases is one block, summarised by the median over its use cases (see
    // hlUnits); 'each': one block per use case.
    let ucScope = 'median';

    // "Median over 45 use cases · window 5, 10, 20 × FWHM · 0%, 35%, 70% Lorentzian · SNR 1, 2, 5, 10, 20".
    function ucScopeLabel(cases) {
        const uniq = (f) => [...new Set(cases.map((c) => f(c.row)).filter((v) => v != null))].sort((a, b) => a - b);
        const parts = [`Median over ${cases.length} use cases`];
        const windows = uniq((r) => r.grid_window_fwhm);
        const shares = uniq(ssShareKey);
        const snrs = uniq(ssSnr);
        if (windows.length) parts.push(`window ${windows.join(', ')} × FWHM`);
        if (shares.length) parts.push(shares.map(ssShapeLabel).join(', '));
        if (snrs.length) parts.push(`SNR ${snrs.map((v) => (v === Infinity ? '∞' : Number(v.toPrecision(3)))).join(', ')}`);
        return parts.join(' · ');
    }

    // The two scope controls (Stages and Accuracy) are one setting: keep them in step and redraw the open view.
    function ucBindScopeControls() {
        const ids = ['uc-scope-stages', 'uc-scope-accuracy'];
        for (const id of ids) {
            const group = document.getElementById(id);
            if (!group || group._hasListener) continue;
            group.addEventListener('click', (e) => {
                const btn = e.target.closest('button[data-value]');
                if (!btn) return;
                ucScope = btn.dataset.value;
                for (const other of ids) {
                    document.querySelectorAll(`#${other} button`).forEach((b) => {
                        const active = b.dataset.value === ucScope;
                        b.classList.toggle('is-active', active);
                        b.setAttribute('aria-checked', active ? 'true' : 'false');
                        b.tabIndex = active ? 0 : -1;
                    });
                }
                const mode = document.querySelector('#scan-view-mode button.is-active');
                if (mode) showScanViewPanels(mode.dataset.value);
            });
            group._hasListener = true;
        }
    }

    // Fills `bodyId` with one copy of its markup per use case of the selection (or, with the median scope, one copy
    // for the whole selection), each titled; the copy's element ids get the suffix `--uc<i>`, which
    // renderOne(useCase, suffix) uses to find its elements. In the median scope useCase.generator and .noise are
    // arrays covering the selection, otherwise single names.
    function ucRenderBlocks(bodyId, gen, noises, renderOne) {
        const body = document.getElementById(bodyId);
        if (!body) return;
        if (body._template == null) body._template = body.innerHTML;
        body.querySelectorAll('.js-plotly-plot').forEach((el) => Plotly.purge(el));
        body.innerHTML = '';
        ucBindScopeControls();
        let cases = ucList(gen, noises);
        if (!cases.length) {
            body.innerHTML = '<p style="color:#94a3b8;padding:1em;font-size:0.9em;">No runs for the selected signal and noise.</p>';
            return;
        }
        if (ucScope === 'median' && cases.length > 1) {
            cases = [{
                generator: [...new Set(cases.map((c) => c.generator))],
                noise: [...new Set(cases.map((c) => c.noise))],
                label: ucScopeLabel(cases),
            }];
        }
        cases.forEach((uc, i) => {
            const sfx = `--uc${i}`;
            const section = document.createElement('section');
            section.style.cssText = 'margin:0 0 2em;';
            section.innerHTML = `<h3 class="uc-title" style="margin:0.6em 0; padding:0.4em 0.8em; font-size:1em; color:#334155; background:#f8fafc; border:1px solid #e2e8f0; border-radius:6px;" title="${escapeHtml(uc.label ? uc.label : `${uc.generator} · ${uc.noise}`)}">${escapeHtml(uc.label || ssUseCaseLabel(uc.row))}</h3>`
                + body._template.replace(/\bid="([^"]+)"/g, `id="$1${sfx}"`);
            body.appendChild(section);
            renderOne(uc, sfx);
        });
    }

    // ── Stages tab ───────────────────────────────────────────────────────────
    // Which stage section the Stages view shows: 0 = whole run, 1 / 2 / 3 = search / focus / refine. The others are
    // collapsed rather than display:none: Plotly cannot size a plot in a hidden panel, and keeping their width means
    // switching back needs no redraw.
    let hlStageShown = 0;

    function hlApplyStageSelector() {
        document.querySelectorAll('#stages-body section[data-stage]').forEach((sec) => {
            sec.style.cssText = Number(sec.dataset.stage) === hlStageShown ? '' : 'height:0; overflow:hidden; visibility:hidden; margin:0;';
        });
        document.querySelectorAll('#hl-stages-from button').forEach((b) => {
            const active = Number(b.dataset.value) === hlStageShown;
            b.classList.toggle('is-active', active);
            b.setAttribute('aria-checked', active ? 'true' : 'false');
            b.tabIndex = active ? 0 : -1;
        });
    }

    function hlBindStageSelector() {
        const group = document.getElementById('hl-stages-from');
        if (!group || group._hasListener) return;
        group.addEventListener('click', (e) => {
            const btn = e.target.closest('button[data-value]');
            if (!btn) return;
            hlStageShown = Number(btn.dataset.value);
            hlApplyStageSelector();
        });
        group._hasListener = true;
    }

    function renderStagesTab(gen, noises) {
        if (toGenSet(gen).size === 0) return;
        ensureScanFieldsFor(gen, noises)
            .then(() => ensurePlotly())
            .then(() => {
                ucRenderBlocks('stages-body', gen, noises, (uc, sfx) => renderHlStages(uc.generator, [].concat(uc.noise), sfx));
                hlBindStageSelector();
                hlApplyStageSelector();
            })
            .catch(err => {
                const view = document.getElementById('stages-view');
                if (view) view.insertAdjacentHTML('beforeend', `<div style="padding:1em;color:#721c24;background:#f8d7da;border-radius:6px;"><strong>Stages render error:</strong> ${escapeHtml(String(err.message || err))}</div>`);
            });
    }

    // ── Stages: search -> focus -> refine ────────────────────────────────────
    // Boundaries and per-stage metrics come from one detector (nvision/metrics/stages.py) applied to every
    // run, so locators are compared stage by stage on equal terms. Runs that failed outright (no data) are
    // skipped; runs that merely hit their step budget are kept.
    const HL_STAGES = [
        { n: 1, label: 'Search' },
        { n: 2, label: 'Focus' },
        { n: 3, label: 'Refine' },
    ];

    function hlStageRuns(generator, noises) {
        const noiseSet = new Set((Array.isArray(noises) ? noises : [noises]).filter(Boolean));
        const genSet = toGenSet(generator);
        const byStrategy = new Map();
        for (const p of scanPlots) {
            if (!genSet.has(p.generator) || !noiseSet.has(p.noise) || !p.strategy) continue;
            // Same rule as metrics/compare.py usable_runs: drop timeouts/failures and runs with no measurements.
            if (p.failure_reason != null && p.failure_reason !== 'max_steps') continue;
            const nMeas = _mv(p, 'measurements');
            if (nMeas == null || !(nMeas > 0)) continue;
            if (!byStrategy.has(p.strategy)) byStrategy.set(p.strategy, []);
            byStrategy.get(p.strategy).push(p);
        }
        return byStrategy;
    }

    // ── Median over the selection ───────────────────────────────────────────
    // A selection of several use cases (window x line shape x SNR) is summarised by the median of the per-use-case
    // values: each metric is computed inside its own use case first and the use cases are then combined, so a use
    // case with more repeats does not weigh more and nothing is read off pooled runs. With one use case the values
    // are the runs' own (so the interquartile ranges stay over repeats).
    function hlCaseGroups(runs) {
        const groups = new Map();
        for (const p of runs) {
            const key = `${p.generator}\u0000${p.noise}`;
            if (!groups.has(key)) groups.set(key, []);
            groups.get(key).push(p);
        }
        return [...groups.values()];
    }

    // The values a summary is taken over: one per run for a single use case, else one per use case (the median of
    // valueOf over that use case's runs). valueOf(p) may return null (left out).
    function hlUnits(runs, valueOf) {
        const groups = hlCaseGroups(runs);
        if (groups.length <= 1) return runs.map(valueOf).filter(v => v != null);
        return groups.map(rs => hlMedian(rs.map(valueOf))).filter(v => v != null);
    }

    // Per use case, the share of its runs meeting pred (one value per use case; the median of them is the summary).
    function hlCaseShares(runs, pred) {
        return hlCaseGroups(runs).map(rs => rs.filter(pred).length / rs.length);
    }

    const HL_CMP_FMT = {
        count: (v) => (v == null ? '–' : Math.round(v).toLocaleString()),
        pct: (v) => (v == null ? '–' : `${Math.round(100 * v)}%`),
        khz: (v) => (v == null ? '–' : `${Math.round(v / 1e3)} kHz`),
        ratio: (v) => (v == null ? '–' : v.toFixed(3)),
        num: (v) => (v == null ? '–' : (Math.abs(v) >= 100 ? Math.round(v) : Number(v.toPrecision(3))).toString()),
    };

    // Bars of a per-stage field, one trace per locator; onlyStage (1 / 2 / 3) restricts them to that stage.
    function hlStageBarTraces(byStrategy, strategies, field, hoverLabel, onlyStage = null) {
        return strategies.map(strat => {
            const runs = byStrategy.get(strat);
            const x = [], y = [], up = [], down = [], text = [];
            for (const st of HL_STAGES.filter(s => onlyStage == null || s.n === onlyStage)) {
                const vals = hlSorted(hlUnits(runs, p => _mv(p, `stage${st.n}_${field}`)));
                if (!vals.length) continue;
                const med = hlQuantileSorted(vals, 0.5);
                x.push(st.label);
                y.push(med);
                up.push(hlQuantileSorted(vals, 0.75) - med);
                down.push(med - hlQuantileSorted(vals, 0.25));
                const nCases = hlCaseGroups(runs).length;
                text.push(nCases > 1
                    ? `${vals.length}/${nCases} use cases reached this stage (median over use cases)`
                    : `${vals.length}/${runs.length} repeats reached this stage`);
            }
            return {
                x, y, type: 'bar', name: _shortStratLabel(strat), text, textposition: 'none',
                marker: { color: hlStratColor(strategies, strat) },
                error_y: { type: 'data', symmetric: false, array: up, arrayminus: down, color: '#475569', thickness: 1 },
                hovertemplate: `%{x}: %{y:.3g} ${hoverLabel}<br>%{text}<extra>%{fullData.name}</extra>`,
            };
        });
    }

    // Locators side by side within ONE stage n (1 search, 2 focus, 3 refine): reached share, measurements spent, and
    // the stage's own metric: the share of runs that ever saw a dip (search), how close the stage measured to the
    // steepest point of the dip (focus), the Fisher efficiency eta (refine; the same quantity, per the stage detector).
    function renderHlStageCompare(byStrategy, strategies, sfx, n) {
        const box = document.getElementById(`hl-stage-compare-${n}${sfx}`);
        if (!box) return;
        const iqr = (vals) => {
            const v = hlSorted(vals);
            if (!v.length) return '–';
            return `${HL_CMP_FMT.num(hlQuantileSorted(v, 0.5))} <span style="color:#94a3b8">(${HL_CMP_FMT.num(hlQuantileSorted(v, 0.25))}–${HL_CMP_FMT.num(hlQuantileSorted(v, 0.75))})</span>`;
        };
        const extra = n === 1
            ? { head: 'Dip found', tip: 'Share of runs whose measurements ever showed a dip (median over use cases when several are selected).' }
            : n === 2
                ? { head: 'Sensitivity (1 = steepest point)', tip: 'How close the stage measured to the steepest point of the dip: 1 = at it, 0 = on the flat baseline or the dip centre (simulation ground truth).' }
                : { head: 'Fisher efficiency η (1 = optimal points)', tip: 'How close refine measured to the Fisher-optimal points (tail-mean information relative to the truth oracle).' };
        const rows = strategies.map(strat => {
            const runs = byStrategy.get(strat);
            const steps = hlUnits(runs, p => _mv(p, `stage${n}_steps`));
            const reachedShare = hlMedian(hlCaseShares(runs, p => _mv(p, `stage${n}_steps`) != null));
            const manyCases = hlCaseGroups(runs).length > 1;
            const row = {
                strat,
                reached: manyCases ? `${Math.round(100 * reachedShare)}%` : `${steps.length}/${runs.length}`,
                stepsMed: hlMedian(steps), stepsHtml: iqr(steps),
            };
            if (n === 1) {
                row.extraMed = hlMedian(hlCaseShares(runs, p => _mv(p, 'focus_found_step') != null));
                row.extraHtml = HL_CMP_FMT.pct(row.extraMed);
            } else {
                const sens = hlUnits(runs, p => _mv(p, `stage${n}_sens_eff`));
                row.extraMed = hlMedian(sens);
                row.extraHtml = iqr(sens);
            }
            return row;
        });
        const bestSteps = Math.min(...rows.map(r => r.stepsMed).filter(v => v != null));
        const bestExtra = Math.max(...rows.map(r => r.extraMed).filter(v => v != null));
        rows.sort((a, b) => (a.stepsMed ?? Infinity) - (b.stepsMed ?? Infinity));
        const td = (v, bold) => `<td style="padding:2px 8px;text-align:right;${bold ? 'font-weight:700;color:#047857' : ''}">${v}</td>`;
        box.innerHTML =
            '<table class="metric-table" style="border-collapse:collapse;font-size:0.85em;"><thead><tr>' +
            '<th style="text-align:left;padding:2px 12px 2px 0">Locator</th>' +
            `<th style="padding:2px 8px;text-align:right" title="Share of runs that got this far (a plain sweep never refines)">Reached</th>` +
            `<th style="padding:2px 8px;text-align:right" title="Median measurements in this stage (interquartile range); only runs that reached it count">Measurements</th>` +
            `<th style="padding:2px 8px;text-align:right" title="${escapeHtml(extra.tip)}">${extra.head}</th>` +
            `</tr></thead><tbody>${rows.map(r => `<tr><td style="padding:2px 12px 2px 0">${_shortStratLabel(r.strat)}</td>` +
                td(r.reached) + td(r.stepsHtml, r.stepsMed != null && r.stepsMed === bestSteps) +
                td(r.extraHtml, r.extraMed != null && r.extraMed === bestExtra) + '</tr>').join('')}</tbody></table>`;
    }

    // Which part of the run the over-time curves show: 0 = the whole run, 1 / 2 / 3 = just the search / focus / refine
    // stage. A stage view shifts each run so its stage begins at x = 1 (lining the locators up there) and stops at the
    // run's own end of that stage; runs that never reached the stage are left out.
    const HL_CURVE_STAGE_NAMES = { 1: 'search', 2: 'focus', 3: 'refine' };

    // First and last measurement (1-indexed) of the run in the chosen view, or null when the stage was not reached.
    function hlStageWindow(p, stage) {
        if (stage === 0) {
            const total = hlRunSteps(p);
            return total == null ? null : { start: 1, end: total };
        }
        const steps = _mv(p, `stage${stage}_steps`);
        if (!(steps > 0)) return null;
        const first = stage === 1 ? 1 : stage === 2 ? _mv(p, 'focus_found_step') + 1 : _mv(p, 'max_info_step');
        return { start: first, end: first - 1 + steps };
    }

    // Median (and interquartile band) over repeats of a per-step series value -- 'u' claimed uncertainty or
    // 'e' true error of the primary parameter -- against the measurements since the chosen start, one line per
    // locator. Diamonds / stars sit on each locator's curve at its median focus-found / max-information step.
    function renderHlStageCurve(div, byStrategy, strategies, key, yTitle, stage = 0) {
        const items = [];
        let maxRel = 1;
        for (const strat of strategies) {
            const runs = [];
            for (const p of byStrategy.get(strat)) {
                if (!p.series || !p.series[key]) continue;
                const win = hlStageWindow(p, stage);
                if (win == null) continue;
                runs.push({ p, c: `${p.generator}\u0000${p.noise}`, start: win.start, len: win.end - win.start + 1 });
                if (win.end - win.start + 1 > maxRel) maxRel = win.end - win.start + 1;
            }
            if (runs.length) items.push({ strat, runs });
        }
        const grid = hlStepGrid(maxRel);
        const traces = [];
        const markers = [];
        for (const { strat, runs } of items) {
            const color = hlStratColor(strategies, strat);
            const label = _shortStratLabel(strat);
            const xs = [], med = [], qLo = [], qHi = [];
            // Several use cases: the median (and band) is over the use cases' own medians at that step, and a step
            // needs at least half of them still going (a thin tail of long runs is not the selection's median); one
            // use case: over its repeats.
            const nCases = new Set(runs.map(r => r.c)).size;
            const minUnits = Math.max(Math.min(3, nCases), Math.ceil(nCases / 2));
            for (const rel of grid) {
                const at = runs.filter(r => rel <= r.len)
                    .map(({ p, c, start }) => ({ c, v: hlSeriesValueAt(p.series, key, start - 1 + rel) }))
                    .filter(x => x.v != null && x.v > 0);
                let vals;
                if (nCases <= 1) {
                    vals = hlSorted(at.map(x => x.v));
                } else {
                    const byCase = new Map();
                    for (const x of at) {
                        if (!byCase.has(x.c)) byCase.set(x.c, []);
                        byCase.get(x.c).push(x.v);
                    }
                    vals = hlSorted([...byCase.values()].map(hlMedian));
                }
                if (vals.length < minUnits || !vals.length) continue;
                xs.push(rel);
                med.push(hlQuantileSorted(vals, 0.5));
                qLo.push(hlQuantileSorted(vals, 0.25));
                qHi.push(hlQuantileSorted(vals, 0.75));
            }
            if (!xs.length) continue;
            traces.push({ x: xs, y: qHi, mode: 'lines', line: { width: 0 }, hoverinfo: 'skip', showlegend: false, legendgroup: strat });
            traces.push({ x: xs, y: qLo, mode: 'lines', line: { width: 0 }, fill: 'tonexty', fillcolor: hlHexToRgba(color, 0.13),
                hoverinfo: 'skip', showlegend: false, legendgroup: strat });
            traces.push({ x: xs, y: med, mode: 'lines', legendgroup: strat, name: nCases > 1 ? `${label} (${nCases} use cases)` : `${label} (n=${runs.length})`,
                line: { color, width: 2 }, hovertemplate: `step %{x}<br>median %{y:.4g} Hz<extra>${label}</extra>` });
            for (const [field, symbol, what] of [['focus_found_step', 'diamond', 'focus found'], ['max_info_step', 'star', 'max information']]) {
                const startOf = new Map(runs.map(r => [r.p, r.start]));
                const rel = hlMedian(hlUnits(runs.map(r => r.p), p => { const v = _mv(p, field); return v == null ? null : v - startOf.get(p) + 1; }));
                if (rel == null || rel < 1) continue;
                const at = xs.findIndex(x => x >= rel);
                if (at < 0) continue;
                markers.push({ x: [rel], y: [med[at]], mode: 'markers', legendgroup: strat, showlegend: false,
                    marker: { color, size: 11, symbol, line: { color: '#fff', width: 1 } },
                    hovertemplate: `${what}: ${Math.round(rel)} measurements in<extra>${label}</extra>` });
            }
        }
        const layout = hlBaseLayout();
        const xTitle = stage === 0 ? 'Measurements' : `Measurements into the ${HL_CURVE_STAGE_NAMES[stage]} stage`;
        layout.xaxis = { ...layout.xaxis, title: { text: xTitle, font: { size: 11 } }, type: 'log' };
        layout.yaxis = { ...layout.yaxis, title: { text: yTitle, font: { size: 11 } }, type: 'log' };
        Plotly.react(div, [...traces, ...markers], layout, { displayModeBar: false, responsive: true });
    }

    // One Stages block (a use case, or the median over the selection); `sfx` is the id suffix of its copy of the
    // markup (see ucRenderBlocks).
    function renderHlStages(generator, noises, sfx) {
        const stepsDiv = document.getElementById(`hl-stages-steps${sfx}`);
        const uncDiv = document.getElementById(`hl-stages-unc${sfx}`);
        const errCurveDiv = document.getElementById(`hl-stages-errcurve${sfx}`);
        if (!stepsDiv || !uncDiv || !errCurveDiv) return;
        const byStrategy = hlStageRuns(generator, noises);
        const strategies = [...byStrategy.keys()]
            .filter(s => byStrategy.get(s).some(p => _mv(p, 'stage1_steps') != null))
            .sort(hlStrategyCompare);
        if (!strategies.length) {
            for (const st of HL_STAGES) {
                const cmpBox = document.getElementById(`hl-stage-compare-${st.n}${sfx}`);
                if (cmpBox) cmpBox.innerHTML = '<p style="color:#94a3b8;padding:1em;font-size:0.9em;">No stage metrics for this use case — these runs predate the stage export. Re-run to include them.</p>';
                for (const id of [`hl-stages-steps-${st.n}`, `hl-stage-unc-${st.n}`, `hl-stage-err-${st.n}`]) {
                    const el = document.getElementById(`${id}${sfx}`);
                    if (el) Plotly.purge(el);
                }
            }
            Plotly.purge(stepsDiv);
            Plotly.purge(uncDiv);
            Plotly.purge(errCurveDiv);
            return;
        }

        const barLayout = () => {
            const layout = hlBaseLayout();
            layout.barmode = 'group';
            layout.yaxis = { ...layout.yaxis, title: { text: 'Measurements in stage (median)', font: { size: 11 } } };
            return layout;
        };
        for (const st of HL_STAGES) {
            renderHlStageCompare(byStrategy, strategies, sfx, st.n);
            const bars = document.getElementById(`hl-stages-steps-${st.n}${sfx}`);
            if (bars) {
                Plotly.react(bars, hlStageBarTraces(byStrategy, strategies, 'steps', 'measurements', st.n), barLayout(),
                    { displayModeBar: false, responsive: true });
            }
        }
        Plotly.react(stepsDiv, hlStageBarTraces(byStrategy, strategies, 'steps', 'measurements'), barLayout(),
            { displayModeBar: false, responsive: true });

        renderHlStageCurve(uncDiv, byStrategy, strategies, 'u', 'Median claimed uncertainty (Hz)');
        renderHlStageCurve(errCurveDiv, byStrategy, strategies, 'e', 'Median true |error| (Hz)');
        for (const st of HL_STAGES) {
            const unc = document.getElementById(`hl-stage-unc-${st.n}${sfx}`);
            const err = document.getElementById(`hl-stage-err-${st.n}${sfx}`);
            if (unc) renderHlStageCurve(unc, byStrategy, strategies, 'u', 'Median claimed uncertainty (Hz)', st.n);
            if (err) renderHlStageCurve(err, byStrategy, strategies, 'e', 'Median true |error| (Hz)', st.n);
        }

        renderHlRefineCurves(byStrategy, strategies, sfx);
    }

    // Refine stage aligned to its start: x = measurements since the stage began, y relative to the claimed
    // uncertainty at its start. Solid = the run's own curve (median + IQR over the runs still going), dashed =
    // the Fisher reference (series.r.f: start uncertainty improved only by the true Fisher information of the
    // measurements since; see nvision/metrics/series.py extract_refine_series). Same for every locator that
    // reaches the stage.
    const HL_REFINE_MIN_RUNS = 3;
    function renderHlRefineCurves(byStrategy, strategies, sfx) {
        const uncDiv = document.getElementById(`hl-refine-unc${sfx}`);
        const errDiv = document.getElementById(`hl-refine-err${sfx}`);
        if (!uncDiv || !errDiv) return;
        const uncTraces = [], errTraces = [];
        for (const strat of strategies) {
            const runs = byStrategy.get(strat).map(p => p.series && p.series.r).filter(r => r && r.u && r.u[0] > 0);
            if (runs.length < HL_REFINE_MIN_RUNS) continue;
            const color = hlStratColor(strategies, strat);
            const label = _shortStratLabel(strat);
            const maxK = Math.max(...runs.map(r => r.u.length - 1));
            const add = (traces, key, name, dash, band) => {
                const xs = [], med = [], lo = [], hi = [], n = [];
                for (let k = 0; k <= maxK; k++) {
                    const vals = hlSorted(runs.filter(r => r[key].length > k && r[key][k] != null).map(r => r[key][k] / r.u[0]));
                    if (vals.length < HL_REFINE_MIN_RUNS) break;
                    xs.push(k); n.push(vals.length);
                    med.push(hlQuantileSorted(vals, 0.5)); lo.push(hlQuantileSorted(vals, 0.25)); hi.push(hlQuantileSorted(vals, 0.75));
                }
                if (!xs.length) return;
                if (band) {
                    traces.push({ x: xs, y: hi, mode: 'lines', line: { width: 0 }, hoverinfo: 'skip', showlegend: false, legendgroup: strat });
                    traces.push({ x: xs, y: lo, mode: 'lines', line: { width: 0 }, fill: 'tonexty', fillcolor: hlHexToRgba(color, 0.13), hoverinfo: 'skip', showlegend: false, legendgroup: strat });
                }
                traces.push({
                    x: xs, y: med, mode: 'lines', legendgroup: strat, name: `${label} ${name}`, customdata: n,
                    line: { color, width: 2, dash },
                    hovertemplate: `${label} ${name}<br>%{x} refine steps<br>%{y:.3g} × start σ (%{customdata} runs)<extra></extra>`,
                });
            };
            add(uncTraces, 'u', `claimed σ (n=${runs.length})`, undefined, true);
            add(uncTraces, 'f', 'Fisher reference', 'dash', false);
            add(errTraces, 'e', `true error (n=${runs.length})`, undefined, true);
            add(errTraces, 'f', 'Fisher reference', 'dash', false);
        }
        for (const [div, traces, title] of [
            [uncDiv, uncTraces, 'Claimed σ / claimed σ at refine start'],
            [errDiv, errTraces, '|True error| / claimed σ at refine start'],
        ]) {
            if (!traces.length) {
                Plotly.purge(div);
                div.innerHTML = '<p style="color:#94a3b8;padding:1em;font-size:0.9em;">No run reached the refine stage (or these runs predate the refine export).</p>';
                continue;
            }
            const layout = hlBaseLayout();
            layout.legend = { orientation: 'h', yanchor: 'top', y: -0.22, xanchor: 'left', x: 0, font: { size: 10 } };
            layout.margin = { ...layout.margin, b: 110 };
            layout.xaxis = { ...layout.xaxis, title: { text: 'Measurements since refine start', font: { size: 11 } } };
            layout.yaxis = { ...layout.yaxis, title: { text: title, font: { size: 11 } }, type: 'log' };
            Plotly.react(div, traces, layout, { displayModeBar: false, responsive: true });
        }
    }

    // ── Accuracy tab ─────────────────────────────────────────────────────────

    function renderAccuracyTab(gen, noises) {
        if (toGenSet(gen).size === 0) return;
        ensureScanFieldsFor(gen, noises).then(() => {
        const accView = document.getElementById('accuracy-view');
        ensurePlotly().then(() => {
            hlPaceArgs.clear();
            // One block per selected use case: each is computed from that use case's runs alone.
            ucRenderBlocks('accuracy-body', gen, noises, (uc, sfx) => {
                const byStrategy = hlCollect(uc.generator, [].concat(uc.noise));
                const strategies = [...byStrategy.keys()].sort(hlStrategyCompare);
                renderHlStopQuality(byStrategy, strategies, sfx, !!uc.label);
            });
        }).catch(err => {
            const errDiv = accView;
            if (errDiv) {
                const msg = document.createElement('div');
                msg.style.cssText = 'padding:1em;color:#721c24;background:#f8d7da;border:1px solid #f5c6cb;border-radius:6px;margin:1em;';
                msg.innerHTML = `<strong>Accuracy render error:</strong> ${err.message || err}<br><pre style="white-space:pre-wrap;font-size:11px">${err.stack || ''}</pre>`;
                errDiv.prepend(msg);
            }
        });
        });
    }

    // ── Failed Runs tab ───────────────────────────────────────────────────────

    const FAILURE_LABELS = {
        max_steps: 'Max steps exhausted',
        theory_budget: 'Theory budget (CRLB backstop)',
        infeasible_crlb: 'Infeasible CRLB (run skipped)',
        timeout: 'Timeout',
    };

    function collectFailedRuns(generator, noises) {
        const noiseSet = new Set((Array.isArray(noises) ? noises : [noises]).filter(Boolean));
        const genSet = toGenSet(generator);
        return scanPlots.filter(p =>
            genSet.has(p.generator) &&
            (noiseSet.size === 0 || noiseSet.has(p.noise)) &&
            !isSuccessRun(p)
        );
    }

    function updateFailedRunsButton(generator, noises) {
        const btn = document.getElementById('scan-view-failed-runs-btn');
        if (!btn) return;
        const failed = collectFailedRuns(generator, noises);
        btn.style.display = failed.length > 0 ? '' : 'none';
        btn.textContent = failed.length > 0 ? `Failed Runs (${failed.length})` : 'Failed Runs';
    }

    // Shared table builder for the by-noise and by-span breakdown matrices.
    // rows: [{label, ...reason_counts}], reasons: string[]
    function _frBreakdownTable(rows, reasons) {
        const REASON_COLORS = {
            max_steps: '#b45309', theory_budget: '#1d4ed8',
            infeasible_crlb: '#dc2626', timeout: '#7c3aed',
        };
        const table = document.createElement('table');
        table.style.cssText = 'border-collapse:collapse;font-size:0.85em;margin-bottom:1.2em;';
        const thead = table.createTHead();
        const hrow = thead.insertRow();
        for (const h of ['', ...reasons.map(r => FAILURE_LABELS[r] || r), 'Total']) {
            const th = document.createElement('th');
            th.textContent = h;
            th.style.cssText = 'text-align:right;padding:5px 10px;border-bottom:2px solid #e2e8f0;white-space:nowrap;color:#475569;font-weight:600;';
            if (h === '') th.style.textAlign = 'left';
            hrow.appendChild(th);
        }
        const tbody = table.createTBody();
        for (const row of rows) {
            const tr = tbody.insertRow();
            tr.style.borderBottom = '1px solid #f1f5f9';
            const labelTd = tr.insertCell();
            labelTd.textContent = row.label;
            labelTd.style.cssText = 'padding:4px 10px;white-space:nowrap;color:#334155;font-weight:500;';
            let rowTotal = 0;
            for (const r of reasons) {
                const td = tr.insertCell();
                const n = row[r] || 0;
                rowTotal += n;
                td.textContent = n > 0 ? String(n) : '—';
                td.style.cssText = 'padding:4px 10px;text-align:right;';
                if (n > 0) td.style.color = REASON_COLORS[r] || '#374151';
            }
            const totalTd = tr.insertCell();
            totalTd.textContent = String(rowTotal);
            totalTd.style.cssText = 'padding:4px 10px;text-align:right;font-weight:600;color:#374151;';
        }
        return table;
    }

    function _frSectionHeader(text) {
        const h = document.createElement('h3');
        h.textContent = text;
        h.style.cssText = 'margin:1.2em 0 0.4em;color:#475569;font-size:0.92em;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;';
        return h;
    }

    function renderFailedRunsTab(generator, noises) {
        const summary = document.getElementById('failed-runs-summary');
        const tableContainer = document.getElementById('failed-runs-table-container');
        if (!summary || !tableContainer) return;

        const failed = collectFailedRuns(generator, noises);

        if (!failed.length) {
            summary.textContent = 'No failed runs for the current selection.';
            summary.style.background = '#f0fdf4';
            summary.style.borderColor = '#86efac';
            summary.style.color = '#166534';
            tableContainer.innerHTML = '';
            return;
        }

        // Overall counts by reason
        const counts = {};
        for (const p of failed) {
            const r = p.failure_reason || 'unknown';
            counts[r] = (counts[r] || 0) + 1;
        }
        const total = failed.length;
        const reasons = Object.keys(counts).sort();
        const countParts = reasons.map(r => `${counts[r]} ${FAILURE_LABELS[r] || r}`).join(', ');
        summary.textContent = `${total} run${total !== 1 ? 's' : ''} failed: ${countParts}`;
        summary.style.background = '#fef3c7';
        summary.style.borderColor = '#fde68a';
        summary.style.color = '#92400e';

        const frag = document.createDocumentFragment();

        // ── By Noise ────────────────────────────────────────────────────────
        const noiseKeys = sortNoiseLabels([...new Set(failed.map(p => p.noise).filter(Boolean))]);
        if (noiseKeys.length > 1) {
            frag.appendChild(_frSectionHeader('By Noise'));
            const noiseRows = noiseKeys.map(nk => {
                const row = { label: nk };
                for (const p of failed.filter(fp => fp.noise === nk)) {
                    const r = p.failure_reason || 'unknown';
                    row[r] = (row[r] || 0) + 1;
                }
                return row;
            });
            frag.appendChild(_frBreakdownTable(noiseRows, reasons));
        }

        // ── By Signal Span ───────────────────────────────────────────────────
        const SPAN_BINS = [
            { label: '< 0.5%', lo: 0, hi: 0.005 },
            { label: '0.5 – 2%', lo: 0.005, hi: 0.02 },
            { label: '2 – 5%', lo: 0.02, hi: 0.05 },
            { label: '5 – 15%', lo: 0.05, hi: 0.15 },
            { label: '> 15%', lo: 0.15, hi: Infinity },
        ];
        const spanEntries = failed.map(p => ({ p, span: hlFSpan(p) })).filter(e => e.span != null);
        if (spanEntries.length > 0) {
            frag.appendChild(_frSectionHeader('By Signal Span'));
            const spanRows = SPAN_BINS.map(bin => {
                const inBin = spanEntries.filter(e => e.span >= bin.lo && e.span < bin.hi);
                if (!inBin.length) return null;
                const row = { label: bin.label };
                for (const { p } of inBin) {
                    const r = p.failure_reason || 'unknown';
                    row[r] = (row[r] || 0) + 1;
                }
                return row;
            }).filter(Boolean);
            if (spanRows.length) frag.appendChild(_frBreakdownTable(spanRows, reasons));
        }

        // ── All Failed Runs (flat table) ─────────────────────────────────────
        frag.appendChild(_frSectionHeader('All Failed Runs'));
        const table = document.createElement('table');
        table.style.cssText = 'width:100%;border-collapse:collapse;font-size:0.88em;';
        const thead = table.createTHead();
        const hrow = thead.insertRow();
        for (const h of ['Repeat', 'Strategy', 'Noise', 'Span', 'Reason', 'Steps Used', 'Max Steps', 'Theory Budget', 'Notes']) {
            const th = document.createElement('th');
            th.textContent = h;
            th.style.cssText = 'text-align:left;padding:6px 10px;border-bottom:2px solid #e2e8f0;white-space:nowrap;color:#475569;font-weight:600;';
            hrow.appendChild(th);
        }
        const tbody = table.createTBody();
        const sorted = [...failed].sort((a, b) =>
            (a.strategy || '').localeCompare(b.strategy || '') ||
            (a.noise || '').localeCompare(b.noise || '') ||
            (a.repeat || 0) - (b.repeat || 0)
        );
        for (const p of sorted) {
            const row = tbody.insertRow();
            row.style.borderBottom = '1px solid #f1f5f9';
            const reason = p.failure_reason || 'unknown';
            const reasonLabel = FAILURE_LABELS[reason] || reason;
            const fspan = hlFSpan(p);
            const spanStr = fspan != null ? (fspan * 100).toFixed(1) + '%' : '—';
            let notes = '';
            if (reason === 'theory_budget' && p.theory_step_budget != null) {
                notes = `Budget was ${p.theory_step_budget} steps`;
            } else if (reason === 'infeasible_crlb') {
                notes = 'Run never started';
            } else if (reason === 'max_steps') {
                notes = 'Hit measurement limit';
            } else if (reason === 'timeout') {
                notes = 'Repeat timed out';
            }
            const cells = [
                p.repeat ?? '—', p.strategy ?? '—', p.noise ?? '—', spanStr,
                reasonLabel, p.locator_steps ?? '—', p.max_steps ?? '—',
                p.theory_step_budget ?? '—', notes,
            ];
            for (let i = 0; i < cells.length; i++) {
                const td = row.insertCell();
                td.textContent = String(cells[i]);
                td.style.cssText = 'padding:5px 10px;';
                if (i === 4) {
                    if (reason === 'max_steps') td.style.color = '#b45309';
                    else if (reason === 'theory_budget') td.style.color = '#1d4ed8';
                    else if (reason === 'infeasible_crlb') td.style.color = '#dc2626';
                    else if (reason === 'timeout') td.style.color = '#7c3aed';
                }
            }
        }
        frag.appendChild(table);

        tableContainer.innerHTML = '';
        tableContainer.appendChild(frag);
    }

    // Panel 3: was the stop right, and did the claimed σ relate to the real error?
    // The run stops once the claimed σ falls below the target τ, so σ at the stop is ≈ τ for every repeat and
    // says nothing by itself. Three views, each using the known truth:
    //   * stop table  -- the true error at the stop step, in units of τ (no σ involved);
    //   * pace        -- claimed σ(t) next to the true |error|(t) over the run;
    //   * reality     -- true |error| against the claimed σ across all steps (σ varies there, unlike at the stop).
    // overSelection: the runs are those of several use cases. The stop table (error in units of the stop target) and
    // the σ-vs-error scatter read across them; the pace chart plots absolute Hz against measurements, which would mix
    // windows and SNRs, so it is left to the per-use-case scope.
    function renderHlStopQuality(byStrategy, strategies, sfx, overSelection = false) {
        renderHlStopTable(byStrategy, strategies, sfx);
        if (overSelection) {
            const pace = document.getElementById(`hl-sigma-pace${sfx}`);
            if (pace) {
                Plotly.purge(pace);
                pace.innerHTML = '<p style="color:#94a3b8;padding:1em;font-size:0.9em;">Absolute σ and error against measurements only make sense within one use case: choose "Each use case" above.</p>';
            }
        } else {
            renderHlSigmaPace(byStrategy, strategies, sfx);
        }
        renderHlSigmaReality(byStrategy, strategies, sfx);
    }

    function renderHlStopTable(byStrategy, strategies, sfx) {
        const div = document.getElementById(`hl-stop-table${sfx}`);
        if (!div) return;
        const fmtFrac = (k, n) => {
            const w = hlWilson(k, n);
            return w ? `${(w.p * 100).toFixed(0)}% <span style="color:#94a3b8">[${(w.lo * 100).toFixed(0)}–${(w.hi * 100).toFixed(0)}]</span>` : '–';
        };
        const fmtX = v => (v == null ? '–' : `${v.toFixed(2)}×`);
        const body = [];
        for (const strat of strategies) {
            const runs = byStrategy.get(strat) || [];
            const ratios = [];
            for (const p of runs) {
                const err = _mv(p, 'err_primary_at_milestone');
                const tau = p.series ? p.series.tau : null;
                if (p.primary_converged_step == null || err == null || !(tau > 0)) continue;
                ratios.push(err / tau);
            }
            const sorted = hlSorted(ratios);
            const n = sorted.length;
            const over = t => sorted.filter(r => r > t).length;
            body.push(`<tr>
                <td style="text-align:left;font-weight:600;">${_shortStratLabel(strat)}</td>
                <td>${n}/${runs.length}</td>
                <td>${fmtX(hlQuantileSorted(sorted, 0.5))}</td>
                <td>${fmtX(hlQuantileSorted(sorted, 0.9))}</td>
                <td>${fmtX(hlQuantileSorted(sorted, 0.99))}</td>
                <td>${fmtFrac(over(1), n)}</td>
                <td>${fmtFrac(over(2), n)}</td>
                <td>${fmtFrac(over(3), n)}</td>
            </tr>`);
        }
        if (!body.length) {
            div.innerHTML = '<p style="color:#94a3b8;padding:1em;font-size:0.9em;">No repeats in this use case.</p>';
            return;
        }
        div.innerHTML = `<table class="hl-stop-table" style="border-collapse:collapse;font-size:0.85em;width:100%;text-align:right;">
            <thead><tr style="color:#64748b;border-bottom:1px solid #e2e8f0;">
                <th style="text-align:left;">Strategy</th><th>Stopped / runs</th>
                <th>Median |err|</th><th>90th pct</th><th>99th pct</th>
                <th>&gt; 1× τ</th><th>&gt; 2× τ</th><th>&gt; 3× τ</th>
            </tr></thead><tbody>${body.join('')}</tbody></table>`;
        div.querySelectorAll('td, th').forEach(c => { c.style.padding = '4px 10px'; });
    }

    function renderHlSigmaPace(byStrategy, strategies, sfx) {
        const div = document.getElementById(`hl-sigma-pace${sfx}`);
        if (!div) return;
        hlPaceArgs.set(sfx, { byStrategy, strategies });
        const toggle = document.getElementById(`hl-pace-bands-toggle${sfx}`);
        if (toggle) {
            toggle.checked = hlPaceBands;
            if (!toggle._hasListener) {
                // The bands option is one setting for the whole view: redraw every use case's pace chart.
                toggle.addEventListener('change', () => {
                    hlPaceBands = toggle.checked;
                    for (const [key, args] of hlPaceArgs) {
                        const other = document.getElementById(`hl-pace-bands-toggle${key}`);
                        if (other) other.checked = hlPaceBands;
                        renderHlSigmaPace(args.byStrategy, args.strategies, key);
                    }
                });
                toggle._hasListener = true;
            }
        }
        let globalMax = 1;
        for (const s of strategies) {
            if (isSweepBaseline(s)) continue; // a sweep's full-grid step count would swamp the adaptive scale
            for (const p of byStrategy.get(s)) {
                const m = hlRunSteps(p);
                if (m != null && m > globalMax) globalMax = m;
            }
        }
        const grid = hlStepGrid(globalMax);
        const traces = [];
        const taus = [];
        const perStrategy = [];
        for (const strat of strategies) {
            const runs = byStrategy.get(strat).filter(p => p.series && p.series.e && p.series.u);
            if (!runs.length) continue;
            runs.forEach(p => { if (p.series.tau > 0) taus.push(p.series.tau); });
            const xs = [], errMed = [], sigMed = [];
            for (const step of grid) {
                const errs = hlSorted(runs.map(p => hlSeriesValueAt(p.series, 'e', step)));
                const sigs = hlSorted(runs.map(p => hlSeriesValueAt(p.series, 'u', step)));
                if (!errs.length || !sigs.length) continue;
                xs.push(step);
                errMed.push(hlQuantileSorted(errs, 0.5));
                sigMed.push(hlQuantileSorted(sigs, 0.5));
            }
            if (!xs.length) continue;
            perStrategy.push({ strat, xs, errMed, sigMed });
        }
        // Per strategy: the claimed σ line, then deviation shells above it, coloured by how far out they are
        // (1σ-2σ amber, 2σ-3σ red), then the true-error line on top. Below σ is left clear: an error there is normal.
        // Plotly fills 'tonexty' up to the previous trace, so each shell is the trace above the one beneath it.
        for (const { strat, xs, errMed, sigMed } of perStrategy) {
            const color = hlStratColor(strategies, strat);
            const label = _shortStratLabel(strat);
            traces.push({
                x: xs, y: sigMed, mode: 'lines', legendgroup: strat, name: `${label} claimed σ`,
                line: { color, width: 2, dash: 'dot' },
                hovertemplate: 'step %{x}<br>median claimed σ %{y:.4g} Hz<extra>' + label + '</extra>',
            });
            (hlPaceBands ? [[2, '#f59e0b', 0.22], [3, '#dc2626', 0.18]] : []).forEach(([k, shell, alpha]) => {
                traces.push({
                    x: xs, y: sigMed.map(v => k * v), mode: 'lines', line: { width: 0 },
                    fill: 'tonexty', fillcolor: hlHexToRgba(shell, alpha),
                    legendgroup: strat, showlegend: false,
                    hovertemplate: 'step %{x}<br>' + k + 'σ %{y:.4g} Hz<extra>' + label + '</extra>',
                });
            });
            traces.push({
                x: xs, y: errMed, mode: 'lines', legendgroup: strat, name: `${label} true |err|`,
                line: { color, width: 2 },
                hovertemplate: 'step %{x}<br>median true |err| %{y:.4g} Hz<extra>' + label + '</extra>',
            });
        }
        if (!traces.length) {
            div.innerHTML = '<p style="color:#94a3b8;padding:1em;font-size:0.9em;">No per-step series available.</p>';
            return;
        }
        const layout = hlBaseLayout();
        layout.xaxis = { ...layout.xaxis, title: { text: 'Measurements', font: { size: 11 } }, type: 'log' };
        layout.yaxis = { ...layout.yaxis, title: { text: 'Median over repeats (Hz)', font: { size: 11 } }, type: 'log' };
        const tauMed = hlMedian(taus);
        if (tauMed != null && tauMed > 0) {
            layout.shapes = [{ type: 'line', xref: 'paper', x0: 0, x1: 1, yref: 'y', y0: tauMed, y1: tauMed, line: { color: '#64748b', width: 1.5, dash: 'dash' } }];
            layout.annotations = [{ xref: 'paper', x: 0.99, yref: 'y', y: Math.log10(tauMed), text: 'stop target τ', showarrow: false, font: { size: 9, color: '#64748b' }, yanchor: 'bottom', xanchor: 'right' }];
        }
        if (hlPaceBands) {
            layout.annotations = (layout.annotations || []).concat([{
                xref: 'paper', yref: 'paper', x: 0.01, y: 0.02, xanchor: 'left', yanchor: 'bottom', showarrow: false,
                align: 'left', font: { size: 9, color: '#64748b' },
                text: '<span style="color:#f59e0b">■</span> 1–2σ above claimed σ &nbsp; <span style="color:#dc2626">■</span> 2–3σ above claimed σ',
            }]);
        }
        Plotly.react(div, traces, layout, { displayModeBar: false, responsive: true });
    }

    function renderHlSigmaReality(byStrategy, strategies, sfx) {
        const div = document.getElementById(`hl-sigma-reality${sfx}`);
        if (!div) return;
        const traces = [];
        let xMin = Infinity, xMax = -Infinity;
        for (const strat of strategies) {
            const xs = [], ys = [];
            for (const p of byStrategy.get(strat)) {
                const ser = p.series;
                if (!ser || !ser.e || !ser.u) continue;
                for (let i = 0; i < ser.s.length; i++) {
                    if (ser.u[i] > 0 && ser.e[i] != null) { xs.push(ser.u[i]); ys.push(ser.e[i]); }
                }
            }
            const bin = hlLogBinMedian(xs, ys, 20, 5);
            if (!bin.cx.length) continue;
            const color = hlStratColor(strategies, strat);
            const label = _shortStratLabel(strat);
            xMin = Math.min(xMin, bin.cx[0]);
            xMax = Math.max(xMax, bin.cx[bin.cx.length - 1]);
            traces.push({
                x: bin.cx.concat([...bin.cx].reverse()), y: bin.hi.concat([...bin.lo].reverse()),
                fill: 'toself', fillcolor: hlHexToRgba(color, 0.12), line: { width: 0 },
                mode: 'lines', hoverinfo: 'skip', showlegend: false, legendgroup: strat,
            });
            traces.push({
                x: bin.cx, y: bin.med, mode: 'lines+markers', legendgroup: strat, name: label,
                line: { color, width: 2 }, marker: { color, size: 4 }, customdata: bin.n,
                hovertemplate: 'claimed σ %{x:.3g} Hz<br>median true |err| %{y:.3g} Hz<br>n=%{customdata}<extra>' + label + '</extra>',
            });
        }
        if (!traces.length) {
            div.innerHTML = '<p style="color:#94a3b8;padding:1em;font-size:0.9em;">No (error, uncertainty) pairs available.</p>';
            return;
        }
        // A calibrated Gaussian belief has median |error| = 0.6745 σ. A curve parallel to this line means σ tracks the
        // real error up to a constant factor; a flatter curve means σ says little about the error.
        traces.push({
            x: [xMin, xMax], y: [0.6745 * xMin, 0.6745 * xMax], mode: 'lines', name: 'calibrated Gaussian (0.67 σ)',
            line: { color: '#64748b', width: 1.5, dash: 'dash' }, hoverinfo: 'skip',
        });
        const layout = hlBaseLayout();
        layout.xaxis = { ...layout.xaxis, title: { text: 'Claimed σ (Hz)', font: { size: 11 } }, type: 'log' };
        layout.yaxis = { ...layout.yaxis, title: { text: 'True |error| (Hz): median and IQR per σ bin', font: { size: 11 } }, type: 'log' };
        Plotly.react(div, traces, layout, { displayModeBar: false, responsive: true });
    }

    function formatHz(v) {
        if (v == null || !isFinite(v)) return '?';
        if (Math.abs(v) >= 1e6) return (v / 1e6).toFixed(1) + ' MHz';
        if (Math.abs(v) >= 1e3) return (v / 1e3).toFixed(1) + ' kHz';
        return v.toFixed(1) + ' Hz';
    }


    // Stopping criteria selector
    const stoppingCriteriaGroup = document.getElementById('scan-stopping-criteria');
    if (stoppingCriteriaGroup) {
        stoppingCriteriaGroup.addEventListener('click', (e) => {
            const btn = e.target.closest('button[data-value]');
            if (!btn || btn.disabled) return;
            setStoppingCriteria(btn.dataset.value);
            if (currentPlot) findAndDisplayPlot();
        });
    }

    // Noise argument the aggregate renderers expect: an array in noise-range
    // mode, otherwise the single effective noise.
    function compareNoisesArg() {
        return isNoiseRangeMode() ? getSelectedScanNoises() : getEffectiveScanNoise();
    }

    // Single source of truth for which Scan/Compare panel is visible and what it
    // renders. All entry points (toggle click, plot refresh, range-mode refresh)
    // route through here so the aggregate axes stay consistent.
    function showScanViewPanels(mode) {
        const repeatView = document.getElementById('scan-repeat-view');
        const stepSizeView = document.getElementById('stepsize-view');
        const ssControls = document.getElementById('ss-controls');
        const accuracyView = document.getElementById('accuracy-view');
        const stagesView = document.getElementById('stages-view');
        const failedRunsView = document.getElementById('failed-runs-view');
        const stoppingRow = document.getElementById('stopping-criteria-row');
        const gen = compareGeneratorsArg();
        const noises = compareNoisesArg();

        if (repeatView) repeatView.style.display = 'none';
        const runContent = document.getElementById('scan-run-content');
        // Collapsed, not display:none: the Run plots still render into it and Plotly cannot size a hidden panel.
        if (runContent) runContent.style.cssText = mode === 'single' ? '' : 'height:0; overflow:hidden; visibility:hidden;';
        if (stepSizeView) stepSizeView.style.display = 'none';
        if (ssControls) ssControls.style.display = mode === 'locators' || mode === 'accuracy' ? 'block' : 'none';
        if (accuracyView) accuracyView.style.display = 'none';
        if (stagesView) stagesView.style.display = 'none';
        if (failedRunsView) failedRunsView.style.display = 'none';

        const compareSweepRow = document.getElementById('scan-compare-sweep-row') || document.getElementById('scan-compare-sweep-container');
        if (compareSweepRow) {
            if (mode === 'single') {
                const currentStrat = (currentPlot && currentPlot.strategy) || controlValue(scanStrategy) || '';
                compareSweepRow.style.display = _isSweepStrategyName(currentStrat) ? 'none' : 'flex';
            } else {
                compareSweepRow.style.display = 'none';
            }
        }

        if (mode === 'single') {
            if (repeatView) repeatView.style.display = 'block';
            updateStoppingCriteriaVisibility(currentPlot);
        } else if (mode === 'locators') {
            if (stoppingRow) stoppingRow.style.display = 'none';
            if (stepSizeView) {
                stepSizeView.style.display = 'block';
                renderStepSizeTab();
            }
        } else if (mode === 'accuracy') {
            if (stoppingRow) stoppingRow.style.display = 'none';
            if (accuracyView) {
                accuracyView.style.display = 'block';
                renderAccuracyTab(gen, noises);
                renderStepSizeTab();   // the "Is the claimed σ right?" chart across the family
            }
        } else if (mode === 'stages') {
            if (stoppingRow) stoppingRow.style.display = 'none';
            if (stagesView) {
                stagesView.style.display = 'block';
                renderStagesTab(gen, noises);
            }
        } else if (mode === 'failed-runs') {
            if (stoppingRow) stoppingRow.style.display = 'none';
            if (failedRunsView) {
                failedRunsView.style.display = 'block';
                renderFailedRunsTab(gen, noises);
            }
        }
        syncHashFromState();
    }

    const scanViewMode = document.getElementById('scan-view-mode');
    if (scanViewMode) {
        scanViewMode.addEventListener('click', (e) => {
            if (e.target.tagName === 'BUTTON' && !e.target.style.display.includes('none')) {
                scanViewMode.querySelectorAll('button').forEach(b => {
                    b.classList.remove('is-active');
                    b.setAttribute('aria-checked', 'false');
                    b.tabIndex = -1;
                });
                e.target.classList.add('is-active');
                e.target.setAttribute('aria-checked', 'true');
                e.target.tabIndex = 0;

                showScanViewPanels(e.target.dataset.value);
            }
        });
        scanViewMode.addEventListener('keydown', (e) => {
            if (e.target.tagName !== 'BUTTON') return;
            const buttons = Array.from(scanViewMode.querySelectorAll('button'));
            const index = buttons.indexOf(e.target);
            let nextIndex = null;
            if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
                nextIndex = (index + 1) % buttons.length;
            } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
                nextIndex = (index - 1 + buttons.length) % buttons.length;
            }
            if (nextIndex !== null) {
                e.preventDefault();
                buttons[nextIndex].focus();
                buttons[nextIndex].click();
            }
        });
    }

    const summaryTabBar = document.getElementById('summary-tab-bar');
    if (summaryTabBar) {
        summaryTabBar.addEventListener('click', (e) => {
            if (e.target.tagName === 'BUTTON') {
                summaryTabBar.querySelectorAll('button').forEach(b => {
                    b.classList.remove('is-active');
                    b.setAttribute('aria-selected', 'false');
                    b.tabIndex = -1;
                    const panel = document.getElementById(b.dataset.tab);
                    if (panel) panel.classList.remove('is-active');
                });
                e.target.classList.add('is-active');
                e.target.setAttribute('aria-selected', 'true');
                e.target.tabIndex = 0;
                const activePanel = document.getElementById(e.target.dataset.tab);
                if (activePanel) activePanel.classList.add('is-active');

                // Trigger resize so Plotly fits correctly if it was hidden
                window.dispatchEvent(new Event('resize'));
            }
        });
        summaryTabBar.addEventListener('keydown', (e) => {
            if (e.target.tagName !== 'BUTTON') return;
            const buttons = Array.from(summaryTabBar.querySelectorAll('button'));
            const index = buttons.indexOf(e.target);
            let nextIndex = null;
            if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
                nextIndex = (index + 1) % buttons.length;
            } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
                nextIndex = (index - 1 + buttons.length) % buttons.length;
            }
            if (nextIndex !== null) {
                e.preventDefault();
                buttons[nextIndex].focus();
                buttons[nextIndex].click();
            }
        });
    }

    // With the Strategy picker hidden, the Locator panel only holds the "View at"
    // row; show the panel only while that row is visible (it is toggled via
    // style.display in several places, so observe it rather than patch each one).
    const locatorPanel = document.getElementById('panel-locator');
    const stoppingCriteriaRow = document.getElementById('stopping-criteria-row');
    if (locatorPanel && stoppingCriteriaRow) {
        const syncLocatorPanelVisibility = () => {
            locatorPanel.hidden = stoppingCriteriaRow.style.display === 'none';
        };
        new MutationObserver(syncLocatorPanelVisibility)
            .observe(stoppingCriteriaRow, { attributes: true, attributeFilter: ['style'] });
        syncLocatorPanelVisibility();
    }

    if (scanIframe) {
        scanIframe.addEventListener('load', () => {
            // Keep legend preference when switching locator strategy/repeat (new iframe src).
            applyScanLegendPreferenceInScanIframe();
            bindScanIframeLegendPreferenceSync();
            // Parse and render narrowed param bounds from the scan figure meta.
            renderNarrowedBoundsFromIframe();
        });
    }

    const narrowedBoundsPanel = document.getElementById('narrowed-bounds-panel');


    function renderNarrowedBoundsPanel(narrowedBounds) {
        if (!narrowedBoundsPanel) return;
        if (!narrowedBounds || typeof narrowedBounds !== 'object' || Object.keys(narrowedBounds).length === 0) {
            narrowedBoundsPanel.hidden = true;
            narrowedBoundsPanel.innerHTML = '';
            return;
        }
        const entries = Object.entries(narrowedBounds)
            .filter(([, range]) => Array.isArray(range) && range.length === 2)
            .map(([name, [lo, hi]]) => ({ name, lo, hi }));
        if (entries.length === 0) {
            narrowedBoundsPanel.hidden = true;
            narrowedBoundsPanel.innerHTML = '';
            return;
        }

        let cardsHtml = '';
        for (const { name, lo, hi } of entries) {
            let selectedVal = undefined;
            if (currentPlot && currentPlot.true_params && currentPlot.true_params.params) {
                const params = currentPlot.true_params.params;
                if (params[name] !== undefined) {
                    selectedVal = params[name];
                } else {
                    const lowerName = name.toLowerCase();
                    const foundKey = Object.keys(params).find(k => k.toLowerCase() === lowerName);
                    if (foundKey) {
                        selectedVal = params[foundKey];
                    }
                }
            }
            if (selectedVal === undefined || typeof selectedVal !== 'number') {
                selectedVal = (lo + hi) / 2;
            }

            let percent = 50;
            if (hi > lo) {
                percent = Math.min(100, Math.max(0, (selectedVal - lo) / (hi - lo) * 100));
            }

            const fmtLo = formatHzValue(name, lo);
            const fmtHi = formatHzValue(name, hi);
            const fmtVal = formatHzValue(name, selectedVal);

            cardsHtml +=
                '<div class="param-slider-card" title="' + name + ': [' + lo + ', ' + hi + '] — Selected: ' + selectedVal + '">' +
                '<div class="param-slider-label">🔍 ' + escapeHtml(name) + '</div>' +
                '<div class="param-slider-wrapper">' +
                '<div class="param-slider-track-bg"></div>' +
                '<div class="param-slider-track-fill" style="width: ' + percent + '%"></div>' +
                '<div class="param-slider-handle" style="left: ' + percent + '%"></div>' +
                '<div class="param-slider-value" style="left: ' + percent + '%">' + fmtVal + '</div>' +
                '</div>' +
                '<div class="param-slider-bounds">' +
                '<span class="param-slider-bound-lo">' + fmtLo + '</span>' +
                '<span class="param-slider-bound-hi">' + fmtHi + '</span>' +
                '</div>' +
                '</div>';
        }

        const sectionId = 'narrowed-priors';
        const isCollapsed = isSectionCollapsed(sectionId);
        narrowedBoundsPanel.innerHTML =
            `<div class="param-bounds-header section-collapsible-header${isCollapsed ? ' is-collapsed' : ''}" role="button" tabindex="0" aria-expanded="${!isCollapsed}" data-section-id="${sectionId}" title="${isCollapsed ? 'Click to expand' : 'Click to collapse'}">` +
                `<span class="section-collapse-arrow" aria-hidden="true">${COLLAPSE_ARROW_SVG}</span>` +
                `<span>Sweep-narrowed priors:</span>` +
            `</div>` +
            `<div class="param-bounds-grid"${isCollapsed ? ' style="display:none;"' : ''}>` + cardsHtml + `</div>`;
        narrowedBoundsPanel.hidden = false;
        const nbHeader = narrowedBoundsPanel.querySelector('.param-bounds-header');
        const nbGrid = narrowedBoundsPanel.querySelector('.param-bounds-grid');
        if (nbHeader && nbGrid) {
            const toggle = () => {
                toggleCollapsibleSection(sectionId, nbHeader, nbGrid);
                nbHeader.setAttribute('title', nbHeader.classList.contains('is-collapsed') ? 'Click to expand' : 'Click to collapse');
            };
            nbHeader.addEventListener('click', toggle);
            nbHeader.addEventListener('keydown', (e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    toggle();
                }
            });
        }
    }

    function renderNarrowedBoundsFromIframe() {
        if (!narrowedBoundsPanel) return;
        // JSON path: read directly from the Plotly graph div
        const scanPlotDiv = document.getElementById('scan-plot-div');
        if (scanPlotDiv && scanPlotDiv.style.display !== 'none' && scanPlotDiv.layout) {
            const meta = scanPlotDiv.layout.meta;
            renderNarrowedBoundsPanel(meta && meta.narrowed_param_bounds);
            return;
        }
        // Legacy HTML iframe path
        if (!scanIframe) return;
        const frameDoc = scanIframe.contentDocument;
        if (!frameDoc) { renderNarrowedBoundsPanel(null); return; }
        const html = frameDoc.documentElement ? frameDoc.documentElement.outerHTML : '';
        if (!html) { renderNarrowedBoundsPanel(null); return; }
        try {
            const m = html.match(/Plotly\.newPlot\(\s*"[^"]+",\s*/);
            if (!m) { renderNarrowedBoundsPanel(null); return; }
            const pos = m.index + m[0].length;
            const dataStr = html.slice(pos);
            let depth = 0, end = 0;
            for (let i = 0; i < dataStr.length; i++) {
                if (dataStr[i] === '[') depth++;
                else if (dataStr[i] === ']') {
                    depth--;
                    if (depth === 0) { end = i + 1; break; }
                }
            }
            let layoutStart = pos + end;
            while (layoutStart < html.length && /[\s,]/.test(html[layoutStart])) layoutStart++;
            if (html[layoutStart] !== '{') { renderNarrowedBoundsPanel(null); return; }
            let ldepth = 0, lend = 0;
            for (let i = layoutStart; i < html.length; i++) {
                if (html[i] === '{') ldepth++;
                else if (html[i] === '}') {
                    ldepth--;
                    if (ldepth === 0) { lend = i + 1; break; }
                }
            }
            if (lend <= layoutStart) { renderNarrowedBoundsPanel(null); return; }
            const layout = JSON.parse(html.slice(layoutStart, lend));
            const meta = layout && layout.meta;
            renderNarrowedBoundsPanel(meta && meta.narrowed_param_bounds);
        } catch (e) {
            renderNarrowedBoundsPanel(null);
        }
    }

    function setupTabs() {
        const tabBar = document.querySelector('.tab-bar');
        const tabPanels = document.querySelectorAll('.tab-panel');

        tabBar.style.display = 'flex';
        tabBar.innerHTML = ''; // Clear existing

        const hasScans = scanPlots.length > 0;

        if (hasScans) {
            const button = document.createElement('button');
            button.className = 'tab-button';
            button.textContent = 'Scan measurements';
            button.dataset.tab = 'scan-section';
            button.setAttribute('role', 'tab');
            button.setAttribute('id', 'tab-scan');
            button.setAttribute('aria-controls', 'scan-section');
            button.setAttribute('aria-selected', 'false');
            tabBar.appendChild(button);
        }

        // Noise Sweep top-level tab removed (moved under Scan View -> Noise Metrics)

        const tabButtons = Array.from(tabBar.querySelectorAll('.tab-button'));
        if (tabButtons.length > 0) {
            tabButtons[0].classList.add('is-active');
            tabButtons[0].setAttribute('aria-selected', 'true');
            tabButtons[0].tabIndex = 0;
            for (let i = 1; i < tabButtons.length; i++) {
                tabButtons[i].tabIndex = -1;
            }
            const initialTabId = tabButtons[0].dataset.tab;
            tabPanels.forEach(panel => {
                if (panel.id === initialTabId) {
                    panel.classList.remove('is-hidden');
                } else {
                    panel.classList.add('is-hidden');
                }
            });
            // With a single top-level section there is nothing to switch between,
            // so hide the lone tab button (the panel stays visible above).
            if (tabButtons.length <= 1) tabBar.style.display = 'none';
        } else {
            tabBar.style.display = 'none';
        }

        tabBar.addEventListener('click', (e) => {
            const target = e.target;
            if (!target.matches('.tab-button')) {
                return;
            }

            tabButtons.forEach(button => {
                button.classList.remove('is-active');
                button.setAttribute('aria-selected', 'false');
                button.tabIndex = -1;
            });
            target.classList.add('is-active');
            target.setAttribute('aria-selected', 'true');
            target.tabIndex = 0;

            tabPanels.forEach(panel => {
                if (panel.id === target.dataset.tab) {
                    panel.classList.remove('is-hidden');
                } else {
                    panel.classList.add('is-hidden');
                }
            });
            // Trigger a window resize event so responsive Plotly charts adjust to their visible containers
            setTimeout(() => {
                window.dispatchEvent(new Event('resize'));
            }, 0);
        });

        tabBar.addEventListener('keydown', (e) => {
            const target = e.target;
            if (!target.matches('.tab-button')) {
                return;
            }
            const index = tabButtons.indexOf(target);
            let nextIndex = null;
            if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
                nextIndex = (index + 1) % tabButtons.length;
            } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
                nextIndex = (index - 1 + tabButtons.length) % tabButtons.length;
            }
            if (nextIndex !== null) {
                e.preventDefault();
                tabButtons[nextIndex].focus();
                tabButtons[nextIndex].click();
            }
        });
    }

    scanGenerator.addEventListener('controlchange', () => {
        lastComparePairIds = { a: null, b: null };
        lastSummaryKey = null;
        updateAllScanControls();
        findAndDisplayPlot();
    });
    scanNoise.addEventListener('controlchange', () => {
        updateNoiseViewMode();
        updateScanStrategyControl();
        updateScanRepeatControl();
        findAndDisplayPlot();
    });
    scanStrategy.addEventListener('controlchange', () => {
        updateScanRepeatControl();
        findAndDisplayPlot();
    });
    scanRepeat.addEventListener('change', () => {
        scanRepeat.dataset.value = scanRepeat.value || '';
        updateRepeatNavButtons();
        findAndDisplayPlot();
    });

    if (scanCompareSweep) {
        scanCompareSweep.addEventListener('change', () => {
            applySweepComparisonOverlay(scanCompareSweep.value);
        });
    }


    if (scanRepeatPrev) {
        scanRepeatPrev.addEventListener('click', () => {
            selectRepeatByOffset(-1);
        });
    }
    if (scanRepeatNext) {
        scanRepeatNext.addEventListener('click', () => {
            selectRepeatByOffset(1);
        });
    }

    const scanFlipViewToggle = document.getElementById('scan-flip-view-toggle');
    if (scanFlipViewToggle) {
        scanFlipViewToggle.addEventListener('change', () => {
            scanFlipViewEnabled = scanFlipViewToggle.checked;
            const scanPlotDiv = document.getElementById('scan-plot-div');
            if (scanPlotDiv && scanPlotDiv._lastJsonPath) {
                renderPlotFromJson(scanPlotDiv, scanPlotDiv._lastJsonPath);
            }
        });
    }

    if (scanDefault) {
        scanGenerator.dataset.value = scanDefault.generator ?? '';
        
        const defaultNoise = scanDefault.noise ?? '';
        if (defaultNoise) {
            scanNoise.dataset.selectedValues = JSON.stringify([defaultNoise]);
        }

        scanStrategy.dataset.value = scanDefault.strategy ?? '';
        scanRepeat.dataset.value =
            scanDefault.repeat === undefined || scanDefault.repeat === null
                ? ''
                : String(scanDefault.repeat);
    }

    // Overrides the defaults above with whatever the URL hash requests. Invalid
    // or unavailable values (e.g. a generator that isn't in this manifest) are
    // harmless: updateAllScanControls()'s renderSegmentedControl/renderSelectControl
    // calls already fall back to a valid selection when the "previous value" they're
    // handed doesn't match any current item, so there's no need to validate here.
    function applyHashToDom() {
        const params = getHashParams();
        const hGenerator = params.get('generator');
        const hNoise = params.get('noise');
        const hStrategy = params.get('strategy');
        const hRepeat = params.get('repeat');
        const hView = params.get('view');
        const hBayesTab = params.get('bayesTab');

        if (hGenerator) scanGenerator.dataset.value = hGenerator;
        if (hNoise) scanNoise.dataset.selectedValues = JSON.stringify([hNoise]);
        if (hStrategy) scanStrategy.dataset.value = hStrategy;
        if (hRepeat) scanRepeat.dataset.value = hRepeat;
        if (hBayesTab) pendingHashBayesTab = hBayesTab;

        updateAllScanControls();
        findAndDisplayPlot();

        if (hView) {
            const targetBtn = Array.from(document.querySelectorAll('#scan-view-mode button'))
                .find((b) => b.dataset.value === hView);
            if (targetBtn && targetBtn.style.display !== 'none' && !targetBtn.disabled) {
                targetBtn.click();
            }
        }
    }

    try {
        setupTabs();
        applyHashToDom();
        if (!window.__nvisionHashRoutingBound) {
            window.__nvisionHashRoutingBound = true;
            window.addEventListener('hashchange', () => applyHashToDom());
        }
    } catch (error) {
        console.error('Error initializing UI controls:', error);
        // Show an error message to the user
        const errorDiv = document.createElement('div');
        errorDiv.setAttribute('role', 'alert');
        errorDiv.style.padding = '20px';
        errorDiv.style.margin = '20px';
        errorDiv.style.border = '1px solid #f5c6cb';
        errorDiv.style.backgroundColor = '#f8d7da';
        errorDiv.style.color = '#721c24';
        errorDiv.style.borderRadius = '4px';
        errorDiv.innerHTML = '<h3>Error: Failed to initialize UI</h3><p>There was a problem initializing the user interface. Please check the console for more details.</p>';
        document.body.appendChild(errorDiv);
    }
}

// Keyboard shortcut, recalc button, and app init are in reload.js
